// HomeMaster estimator — generated by tools/build_web.mjs

const HM = globalThis.HM_ESTIMATOR = globalThis.HM_ESTIMATOR || {};

const HM_RULES_URL = (typeof globalThis !== "undefined" && (globalThis.HM_ESTIMATOR_RULES_URL || globalThis.HM_RULES_URL)) || "https://config.home-master.eu/estimator/rules.json";

HM.RULES_URL = HM_RULES_URL;


// ===== engine.js =====
/**
 * HomeMaster product configurator — pure estimation engine.
 * No fetch, DOM, Date.now, or Math.random.
 */

const EMPTY = Object.freeze({});

const SYSTEM_SECTION_IDS = [
  "heating",
  "ventilation",
  "water",
  "electrical",
  "security",
  "lighting_scenes",
];

/** Enclosure search space: whole DIN rows only (false panel covers a full row). */
const ENCLOSURE_ROW_WIDTHS = [12, 18, 24];
const ENCLOSURE_MAX_ROWS = 6;
const ENCLOSURE_MAX_CAPACITY = 24 * 6; // 144 per section
/** Max coupled DIN enclosure sections for one panel (physical cabinet). */
const ENCLOSURE_MAX_SECTIONS = 4;
const ENCLOSURE_TE_MM = 17.5;
const ENCLOSURE_WIDTH_MARGIN_MM = 100;
const ENCLOSURE_ROW_PITCH_MM = 125;
const ENCLOSURE_HEIGHT_MARGIN_MM = 200;

/**
 * @param {object} inputs
 * @param {object} rules
 * @param {object} [prices]
 * @returns {object}
 */
/**
 * Panel count is only what the user set on screen 1 (or one default).
 * Demand that exceeds one 6×24 body uses coupled enclosure sections
 * (enclosure.cabinets), not extra panels.
 */
function estimate(inputs, rules, prices = EMPTY) {
  return estimateCore(inputs, rules, prices);
}

function estimateCore(inputs, rules, prices = EMPTY) {
  const panels = resolvePanels(inputs);
  const haNeeded =
    (inputs.systems?.system?.ha_server || "needed") !== "own";
  const panelResults = panels.map((panel, index) => {
    const sliced = sliceInputsForPanel(inputs, panel, panels);
    const one = estimatePanel(sliced, rules, prices, {
      includeHaServer: index === 0 && haNeeded,
      haServerNeeded: haNeeded,
    });
    const roomNames = (sliced.rooms || [])
      .map((r) => String(r?.name ?? "").trim())
      .filter(Boolean);
    const systems = listSystemsForPanel(inputs, panel, panels, sliced);
    const enc = one.enclosure || null;
    return {
      id: panel.id,
      name: panel.name,
      location: panel.location || "",
      ...one,
      rooms: roomNames,
      systems,
      din_needed: enc?.din_needed ?? null,
      capacity: enc?.capacity ?? null,
      din_occupied: enc?.din_occupied ?? enc?.din_total ?? null,
      din_reserve: enc?.din_reserve ?? null,
      din_free: enc?.din_free ?? null,
      occupied: enc?.din_occupied ?? enc?.din_total ?? null,
      reserve: enc?.din_reserve ?? null,
      free: enc?.din_free ?? null,
      enclosure: enc,
    };
  });

  const aggregated = aggregatePanelResults(panelResults, rules);

  let split_warning = null;
  if (panels.length > 1) {
    const merged = estimatePanel(
      mergeInputsToSinglePanel(inputs, panels),
      rules,
      prices,
      { includeHaServer: haNeeded, haServerNeeded: haNeeded },
    );
    split_warning = buildSplitWarning(
      panelResults,
      merged,
      rules,
      panels.length,
    );
  }

  return {
    ...aggregated,
    panels: panelResults,
    split_warning,
    not_included: listNotIncluded(rules),
  };
}

function listNotIncluded(rules) {
  const fromRules = rules?.not_included;
  if (Array.isArray(fromRules) && fromRules.length) {
    return fromRules.map((x) => String(x));
  }
  return [...DEFAULT_NOT_INCLUDED];
}

const DEFAULT_NOT_INCLUDED = [
  "Main isolator — not included. Rating depends on the supply; to be specified by the electrical design.",
  "Group breakers on the 230 V side — not included. Load grouping is a site design decision.",
  "Voltage monitoring relay — not included. Specify if required by the installation or local code.",
  "Busbar comb — not included. Depends on the final arrangement of protective devices.",
  "Cable duct between DIN rows — not included. Depends on enclosure make and wiring route.",
  "False panel and enclosure door — not included. Chosen with the enclosure manufacturer.",
  "24 V buffer / UPS — not included. Without it the automation stops on mains failure; specify if required.",
];


/**
 * Flat demand_mapping shortcuts (systems.leak_zones, underfloor_circuits, …)
 * → canonical Systems section id for panels[].systems.
 * Nested systems.heating.* etc. are detected separately via systemSectionHasContent.
 */
const FLAT_FIELD_TO_SECTION = Object.freeze({
  underfloor_circuits: "heating",
  collector_loops: "heating",
  heating_pumps: "heating",
  circulation_pumps: "heating",
  opentherm_boilers: "heating",
  opentherm: "heating",
  rtd_sensors: "heating",
  rtd_input: "heating",
  onewire_buses: "heating",
  onewire_sensor: "heating",
  pt100_sensors: "heating",
  ds18b20_sensors: "heating",
  fan_coils: "heating",
  heat_pump: "heating",
  fireplace: "heating",
  ahu: "ventilation",
  recuperator: "ventilation",
  extract_fans: "ventilation",
  dampers_0_10v: "ventilation",
  sensors_0_10v: "ventilation",
  sensors_4_20ma: "ventilation",
  analog_sensors: "ventilation",
  analog_in: "ventilation",
  analog_in_4_20: "ventilation",
  analog_outputs: "ventilation",
  analog_out: "ventilation",
  leak_zones: "water",
  leak_zone: "water",
  flow_pulses: "water",
  flow_pulse: "water",
  shutoff_valves: "water",
  water_meters: "water",
  irrigation: "water",
  water_pumps: "water",
  dhw_recirc: "water",
  gas_valve: "water",
  energy_meters: "electrical",
  energy_phases: "electrical",
  energy_phase: "electrical",
  alarm_zones: "security",
  alarm_zone_powered: "security",
  alarm_zone_dry: "security",
  dry_contacts: "security",
  locks: "security",
  presence_sensors: "security",
  presence_in: "security",
  stair_steps: "lighting_scenes",
  garden_lights: "lighting_scenes",
  rgb_strips: "lighting_scenes",
  pwm_led_ch: "lighting_scenes",
  dimmer_groups: "lighting_scenes",
});

/**
 * System section ids on this panel. Includes nested systems.<section> and
 * flat demand_mapping shortcuts (systems.leak_zones / top-level
 * underfloor_circuits). Flat + orphan nested → first panel.
 */
function listSystemsForPanel(inputs, panel, panels, sliced) {
  const fallback = defaultPanelId(panels);
  const isFirst = panel.id === fallback;
  const found = new Set();

  for (const sec of SYSTEM_SECTION_IDS) {
    const src = sliced?.systems?.[sec];
    if (systemSectionHasContent(src)) found.add(sec);
  }

  if (panels.length === 1 || isFirst) {
    for (const sec of SYSTEM_SECTION_IDS) {
      if (systemSectionHasContent(inputs.systems?.[sec])) found.add(sec);
    }
    for (const sec of flatDemandSections(inputs)) found.add(sec);
  } else {
    for (const sec of systemsAssignedToPanel(inputs, panel, panels)) {
      found.add(sec);
    }
  }

  return SYSTEM_SECTION_IDS.filter((sec) => found.has(sec));
}

/** Sections implied by positive flat aliases on inputs or inputs.systems. */
function flatDemandSections(inputs) {
  const out = new Set();
  const bags = [inputs, inputs?.systems].filter(Boolean);
  for (const bag of bags) {
    if (!bag || typeof bag !== "object") continue;
    for (const [field, sec] of Object.entries(FLAT_FIELD_TO_SECTION)) {
      if (!positiveDemandValue(bag[field])) continue;
      out.add(sec);
    }
  }
  return out;
}

function positiveDemandValue(v) {
  if (v == null || v === false) return false;
  if (v === true) return true;
  if (typeof v === "number") return Number.isFinite(v) && v > 0;
  if (typeof v === "string") {
    const t = v.trim();
    if (!t || t === "none") return false;
    const n = Number(t);
    if (Number.isFinite(n)) return n > 0;
    return true;
  }
  if (Array.isArray(v)) return v.length > 0;
  return false;
}

function uniqueStrings(ids) {
  const out = [];
  const seen = new Set();
  for (const id of ids) {
    if (!id || seen.has(id)) continue;
    seen.add(id);
    out.push(id);
  }
  return out;
}

/**
 * Nested systems.<section> on this panel: explicit panel_id, else first panel.
 */
function systemsAssignedToPanel(inputs, panel, panels) {
  const fallback = defaultPanelId(panels);
  const systemsIn = inputs.systems || {};
  return SYSTEM_SECTION_IDS.filter((sec) => {
    const src = systemsIn[sec];
    if (!systemSectionHasContent(src)) return false;
    return knownPanelId(src.panel_id, panels, fallback) === panel.id;
  });
}

/** True when a systems.<section> object carries real demand. */
function systemSectionHasContent(src) {
  if (!src || typeof src !== "object") return false;
  for (const [k, v] of Object.entries(src)) {
    if (k === "panel_id") continue;
    if (positiveDemandValue(v)) {
      if (typeof v === "string" && v.trim() === "none") continue;
      return true;
    }
  }
  return false;
}

/** Single-panel pipeline (one logical panel; enclosure may be N coupled sections). */
function estimatePanel(inputs, rules, prices = EMPTY, opts = {}) {
  const assumptions = [];
  // Each panel is one logical cabinet; RS-485 / incomer floor is 1.
  const forced = {
    ...inputs,
    cabinets: 1,
    systems: {
      ...(inputs.systems || {}),
      system: {
        ...((inputs.systems && inputs.systems.system) || {}),
        cabinets: 1,
      },
    },
  };
  const normalized = normalize(forced, rules, assumptions);
  normalized.cabinets = 1;
  const demand = buildDemand(normalized, rules);
  const allocated = allocate(demand, rules, assumptions, normalized, prices);
  warnAlmRail(allocated, normalized, rules, assumptions);
  const topology = buildTopology(allocated, normalized, rules, assumptions);
  warnOnewireRails(demand, topology.modules, rules, assumptions);
  const power = computePower(topology.modules, rules, assumptions, demand);
  const companions = buildCompanions(
    allocated,
    topology.modules,
    power,
    normalized,
    rules,
    assumptions,
    demand,
    opts,
  );
  // Coupled section count is chosen inside computeEnclosure (not inputs.cabinets).
  const enclosure = computeEnclosure(topology.modules, companions, rules);
  const companionsFinal = finalizeEnclosureCompanions(
    companions,
    enclosure,
    rules,
    assumptions,
  );
  const channel_usage = computeChannelUsage(
    demand,
    topology.modules,
    rules,
    allocated,
  );
  const priced = attachPrices(
    topology,
    companionsFinal,
    power,
    enclosure,
    rules,
    prices,
    assumptions,
  );
  priced.channel_usage = channel_usage;
  return priced;
}

function newPanelId(index) {
  return `panel-${index + 1}`;
}

/** Panels from inputs, or one migrated "Main panel". */
function resolvePanels(inputs) {
  const raw = inputs?.panels;
  if (Array.isArray(raw) && raw.length > 0) {
    return raw.map((p, i) => ({
      id: String(p.id || newPanelId(i)),
      name: String(p.name || `Panel ${i + 1}`).trim() || `Panel ${i + 1}`,
      location: String(p.location || "").trim(),
    }));
  }
  return [{ id: "panel-1", name: "Main panel", location: "" }];
}

function defaultPanelId(panels) {
  return panels[0]?.id || "panel-1";
}

function knownPanelId(rawId, panels, fallback) {
  const id = String(rawId || "").trim();
  if (id && panels.some((p) => p.id === id)) return id;
  return fallback;
}

function sliceInputsForPanel(inputs, panel, panels) {
  const fallback = defaultPanelId(panels);
  const rooms = (inputs.rooms || []).filter((r) => {
    const pid = knownPanelId(r.panel_id, panels, fallback);
    return pid === panel.id;
  });

  const systemsIn = inputs.systems || {};
  const systemsOut = {
    system: { ...(systemsIn.system || {}), cabinets: 1 },
  };
  for (const sec of SYSTEM_SECTION_IDS) {
    const src = systemsIn[sec] || {};
    // Orphan panel_id (deleted panel, stale localStorage) must not drop the
    // whole Systems section — remap to the first panel.
    const secPanel = knownPanelId(src.panel_id, panels, fallback);
    if (secPanel === panel.id) {
      systemsOut[sec] = { ...src, panel_id: secPanel };
    } else {
      systemsOut[sec] = emptySystemSection(sec);
    }
  }

  const isFirst = panel.id === fallback;
  // Flat demand_mapping shortcuts under systems (systems.leak_zones, …)
  // belong to the first panel only — same as top-level light_groups.
  if (isFirst) {
    for (const [key, val] of Object.entries(systemsIn)) {
      if (SYSTEMS_NEST_KEYS.has(key)) continue;
      systemsOut[key] = val;
    }
  }

  const top = inputs._panel_top?.[panel.id];
  const panelSystems = inputs._panel_systems?.[panel.id];
  if (top || panelSystems) {
    const systemsMerged = panelSystems
      ? {
          ...panelSystems,
          // Flat aliases only on the first panel.
          ...(isFirst
            ? Object.fromEntries(
                Object.entries(systemsIn).filter(
                  ([key]) => !SYSTEMS_NEST_KEYS.has(key),
                ),
              )
            : {}),
        }
      : systemsOut;
    return {
      ...inputs,
      cabinets: 1,
      rooms,
      systems: systemsMerged,
      shutters: top?.shutters || 0,
      light_groups: top?.light_groups || 0,
      lights_onoff: top?.lights_onoff || 0,
      underfloor_circuits: top?.underfloor_circuits || 0,
      relay_needs_contactor: top?.relay_needs_contactor || 0,
      expert: top?.expert,
      mode: top?.expert ? "expert" : inputs.mode,
    };
  }

  return {
    ...inputs,
    cabinets: 1,
    rooms,
    systems: systemsOut,
    // Legacy top-level demand shortcuts apply to the first panel only.
    underfloor_circuits: isFirst ? inputs.underfloor_circuits : 0,
    shutters: isFirst ? inputs.shutters : 0,
    light_groups: isFirst ? inputs.light_groups : 0,
    lights_onoff: isFirst ? inputs.lights_onoff : 0,
    expert: isFirst ? inputs.expert : undefined,
    mode: isFirst ? inputs.mode : inputs.mode,
  };
}

function emptySystemSection(sec) {
  if (sec === "heating") {
    return {
      panel_id: "",
      boiler: "none",
      collector_loops: 0,
      heating_pumps: 0,
      fan_coils: 0,
      heat_pump: 0,
      fireplace: 0,
      pt100_sensors: 0,
      ds18b20_sensors: 0,
    };
  }
  if (sec === "ventilation") {
    return {
      panel_id: "",
      ahu: 0,
      recuperator: 0,
      extract_fans: 0,
      dampers_0_10v: 0,
      sensors_0_10v: 0,
      sensors_4_20ma: 0,
    };
  }
  if (sec === "water") {
    return {
      panel_id: "",
      leak_zones: 0,
      shutoff_valves: 0,
      water_meters: 0,
      irrigation: 0,
      water_pumps: 0,
      dhw_recirc: 0,
      gas_valve: 0,
    };
  }
  if (sec === "electrical") {
    return {
      panel_id: "",
      energy_phases: 0,
      load_shed: 0,
      ev_chargers: 0,
      pv_inverters: 0,
      fault_contacts: 0,
    };
  }
  if (sec === "security") {
    return {
      panel_id: "",
      powered_sensors: [],
      dry_contacts: 0,
      gates: 0,
      locks: 0,
      panic_buttons: 0,
    };
  }
  if (sec === "lighting_scenes") {
    return {
      panel_id: "",
      stair_steps: 0,
      accent_zones: 0,
      garden_lights: 0,
    };
  }
  return { panel_id: "" };
}

function mergeInputsToSinglePanel(inputs, panels) {
  const mainId = defaultPanelId(panels);
  const rooms = (inputs.rooms || []).map((r) => ({ ...r, panel_id: mainId }));
  const systemsIn = inputs.systems || {};
  const systemsOut = {
    system: { ...(systemsIn.system || {}), cabinets: 1 },
  };
  for (const sec of SYSTEM_SECTION_IDS) {
    const src = systemsIn[sec] || {};
    systemsOut[sec] = { ...src, panel_id: mainId };
  }
  return {
    ...inputs,
    cabinets: 1,
    panels: [{ id: mainId, name: "Combined", location: "" }],
    rooms,
    systems: systemsOut,
  };
}

function moduleQtyMap(modules) {
  const map = {};
  for (const m of modules || []) {
    map[m.id] = (map[m.id] || 0) + (m.qty || 0);
  }
  return map;
}

function countByMaster(modules, rules, wantMaster) {
  const specs = rules.modules || EMPTY;
  let n = 0;
  for (const m of modules || []) {
    const master = !!specs[m.id]?.master;
    if (master === wantMaster) n += m.qty || 0;
  }
  return n;
}

function buildSplitWarning(panelResults, merged, rules, panelCount) {
  const splitCtrl = panelResults.reduce(
    (s, p) => s + countByMaster(p.modules, rules, true),
    0,
  );
  const splitSlaves = panelResults.reduce(
    (s, p) => s + countByMaster(p.modules, rules, false),
    0,
  );
  const oneCtrl = countByMaster(merged.modules, rules, true);
  const oneSlaves = countByMaster(merged.modules, rules, false);
  const extraCtrl = splitCtrl - oneCtrl;
  const extraMods = splitSlaves - oneSlaves;
  if (extraCtrl <= 0 && extraMods <= 0) return null;
  return (
    `Splitting into ${panelCount} panels adds ${Math.max(0, extraCtrl)} controllers` +
    ` and ${Math.max(0, extraMods)} modules compared with a single panel.`
  );
}

function aggregatePanelResults(panelResults, rules) {
  const modMap = {};
  const accMap = {};
  const cartMap = {};
  const channelMap = {};
  let powerW = 0;
  const powerRequirements = [];
  let segments = 0;
  let dinTotal = 0;
  let dinNeeded = 0;
  let dinCapacity = 0;
  let dinModules = 0;
  let dinCompanions = 0;
  let dinReserve = 0;
  let dinFree = 0;
  let enclosureCabinets = 0;
  let enclosureBlocked = false;
  let enclosureOverflow = false;
  const blockedMods = [];
  const assumptions = [];
  const provenance = [];
  const lines = [];

  for (const p of panelResults) {
    for (const m of p.modules || []) {
      if (!modMap[m.id]) modMap[m.id] = { ...m, qty: 0 };
      modMap[m.id].qty += m.qty || 0;
    }
    for (const a of p.accessories || []) {
      const key =
        a.bind_module && a.bind_index != null
          ? `${a.id}::${p.id || p.name || ""}::${a.bind_module}#${a.bind_index}`
          : a.id || a.label;
      if (!accMap[key]) accMap[key] = { ...a, qty: 0 };
      accMap[key].qty += a.qty || 0;
    }
    for (const c of p.cart_lines || []) {
      if (!cartMap[c.sku]) cartMap[c.sku] = { ...c, qty: 0 };
      cartMap[c.sku].qty += c.qty || 0;
    }
    for (const row of p.channel_usage || []) {
      if (!channelMap[row.channel]) {
        channelMap[row.channel] = {
          channel: row.channel,
          label: row.label,
          needed: 0,
          supplied: 0,
          spare: 0,
          reserve: !!row.reserve,
          note: row.note || "",
        };
      }
      channelMap[row.channel].needed += row.needed || 0;
      channelMap[row.channel].supplied += row.supplied || 0;
      if (row.reserve) channelMap[row.channel].reserve = true;
      if (row.note) channelMap[row.channel].note = row.note;
    }
    powerW += p.power?.total_w || 0;
    for (const req of p.power?.requirements || []) {
      powerRequirements.push(
        p.name ? { ...req, text: `[${p.name}] ${req.text || ""}` } : req,
      );
    }
    segments += p.topology?.segments?.length || 0;
    if (p.enclosure?.status === "blocked") {
      enclosureBlocked = true;
      blockedMods.push(...(p.enclosure.modules || []));
    } else if (p.enclosure) {
      dinTotal += p.enclosure.din_total || 0;
      dinNeeded += p.enclosure.din_needed || 0;
      dinCapacity += p.enclosure.capacity || 0;
      dinModules += p.enclosure.din_modules || 0;
      dinCompanions += p.enclosure.din_companions || 0;
      dinReserve += p.enclosure.din_reserve || 0;
      dinFree += p.enclosure.din_free || 0;
      enclosureCabinets += p.enclosure.cabinets || 0;
      if (
        p.enclosure.overflow ||
        p.enclosure.status === "overflow" ||
        (p.enclosure.capacity != null &&
          (p.enclosure.din_needed || 0) > p.enclosure.capacity)
      ) {
        enclosureOverflow = true;
      }
    }
    for (const a of p.assumptions || []) {
      assumptions.push(`[${p.name}] ${a}`);
    }
    provenance.push({ panel: p.id, items: p.provenance });
    for (const line of p.lines || []) {
      lines.push({ ...line, panel_id: p.id, panel_name: p.name });
    }
  }

  for (const row of Object.values(channelMap)) {
    row.spare = row.supplied - row.needed;
  }

  const modules = Object.values(modMap);
  // Prefer first occurrence's price/sku metadata; qty already summed.
  for (const m of modules) {
    const spec = rules.modules?.[m.id];
    if (spec) {
      m.sku = m.sku || spec.sku;
      m.din_units = spec.din_units ?? m.din_units;
      m.shop_url = m.shop_url || spec.shop_url;
      m.tmpl_id = m.tmpl_id ?? spec.product_template_id;
      m.product_id = m.product_id ?? spec.product_id;
    }
  }

  return {
    modules,
    accessories: Object.values(accMap),
    cart_lines: Object.values(cartMap),
    channel_usage: Object.values(channelMap).sort((a, b) =>
      a.label.localeCompare(b.label),
    ),
    power:
      panelResults.length === 1 && panelResults[0].power
        ? { ...panelResults[0].power }
        : {
            total_w: Math.round(powerW * 100) / 100,
            requirements: powerRequirements,
          },
    topology:
      panelResults.length === 1 && panelResults[0].topology
        ? {
            ...panelResults[0].topology,
            segment_count:
              panelResults[0].topology.segments?.length ?? segments,
          }
        : (() => {
            const flatSegs = [];
            const flatCtrl = [];
            for (const p of panelResults) {
              const segs = p.topology?.segments || [];
              const base = flatSegs.length;
              for (let i = 0; i < segs.length; i++) {
                flatSegs.push({
                  ...segs[i],
                  panel_id: p.id,
                  panel_name: p.name,
                });
                flatCtrl.push({
                  id: segs[i].controller,
                  segment: base + i + 1,
                  segment_index: base + i,
                  panel_id: p.id,
                  panel_name: p.name,
                  slaves: (segs[i].slaves || []).length,
                  poll_weight: segs[i].poll_weight ?? 0,
                });
              }
            }
            return {
              segment_count: flatSegs.length || segments,
              segments: flatSegs,
              controllers: flatCtrl,
            };
          })(),
    enclosure: enclosureBlocked
      ? {
          status: "blocked",
          reason: "din_units_missing",
          modules: [...new Set(blockedMods)],
        }
      : panelResults.length === 1 && panelResults[0].enclosure
        ? {
            ...panelResults[0].enclosure,
            panels: 1,
          }
        : {
            status: enclosureOverflow ? "overflow" : "ok",
            din_modules: Math.round(dinModules * 100) / 100,
            din_companions: Math.round(dinCompanions * 100) / 100,
            din_total: Math.round(dinTotal * 100) / 100,
            din_occupied: Math.round(dinTotal * 100) / 100,
            din_reserve: dinReserve,
            din_needed: dinNeeded,
            din_free: dinFree,
            occupied: Math.round(dinTotal * 100) / 100,
            reserve: dinReserve,
            free: dinFree,
            capacity: dinCapacity,
            cabinets: enclosureCabinets,
            panels: panelResults.length,
            reserve_pct: 0,
            overflow: enclosureOverflow,
            max_capacity: ENCLOSURE_MAX_CAPACITY,
            max_sections: ENCLOSURE_MAX_SECTIONS,
          },
    lines,
    assumptions,
    provenance,
    panel_count: panelResults.length,
  };
}

// ── Stage 1: normalize ──────────────────────────────────────────────

function normalize(inputs, rules, assumptions) {
  const systems = inputs.systems || EMPTY;
  const systemCfg = systems.system || EMPTY;
  const out = {
    cabinets: Math.max(
      1,
      Number(systemCfg.cabinets ?? inputs.cabinets) || 1,
    ),
    mode: inputs.mode ?? "rooms",
    demand: {},
    shutters: 0,
    relay_needs_contactor: 0,
    room_ufh_loops: 0,
    inductive_loads: 0,
    // Channel reserve removed — spare is unused channels on allocated modules.
    reserve_pct: 0,
    stage: inputs.stage || "design",
    property_type: inputs.property_type || "",
    floor_area_m2: Number(inputs.floor_area_m2) || 0,
    floors: Math.max(1, Number(inputs.floors) || 1),
    manual_control: systemCfg.manual_control !== false,
    ha_server: systemCfg.ha_server || "needed",
    alarm_ma: 0,
    meta: {
      stage: inputs.stage || "design",
      ha_server: systemCfg.ha_server || "needed",
      manual_control: systemCfg.manual_control !== false,
    },
  };

  if (inputs.expert?.demand) {
    Object.assign(out.demand, inputs.expert.demand);
    out.mode = "expert";
    if (inputs.expert.shutters != null) out.shutters = inputs.expert.shutters;
    if (inputs.expert.relay_needs_contactor != null) {
      out.relay_needs_contactor = inputs.expert.relay_needs_contactor;
    }
    if (inputs.expert.inductive_loads != null) {
      out.inductive_loads = Number(inputs.expert.inductive_loads) || 0;
    } else if (inputs.inductive_loads != null) {
      out.inductive_loads = Number(inputs.inductive_loads) || 0;
    }
    return out;
  }

  const templates = rules.room_templates ?? EMPTY;

  if (inputs.rooms) {
    for (const room of inputs.rooms) {
      if (!String(room?.name ?? "").trim()) continue;
      const type = room.template ?? room.type ?? "living";
      const tpl = templates[type] ?? EMPTY;
      const merged = { ...tpl, ...room, template: type };
      applyRoomDemand(out, merged, room);
    }
  }

  applySystemsDemand(out, systems, rules, assumptions);

  // Collector loops: max(house Systems value, sum of per-room ufh_loops).
  const houseLoops = Math.max(
    0,
    Number(systems.heating?.collector_loops) || 0,
    Number(systems.collector_loops) || 0,
    Number(inputs.underfloor_circuits) || 0,
    Number(systems.underfloor_circuits) || 0,
  );
  const loops = Math.max(out.room_ufh_loops, houseLoops);
  if (loops > 0) addDemand(out.demand, "out_24v_ch", loops);
  if (houseLoops > 0 || out.room_ufh_loops > 0) {
    assumptions.push(
      `Collector loops: max(rooms ${out.room_ufh_loops}, house ${houseLoops}) = ${loops}.`,
    );
  }

  if (inputs.shutters != null) {
    out.shutters += Number(inputs.shutters) || 0;
  }
  if (inputs.relay_needs_contactor != null) {
    out.relay_needs_contactor += Number(inputs.relay_needs_contactor) || 0;
  }

  // Channel shortcuts: top-level inputs AND flat keys under systems.
  // Canonical Systems UI shape is nested (systems.water.leak_zones); flat
  // systems.leak_zones is accepted via demand_mapping so callers are not silent.
  const mapping = rules.demand_mapping ?? EMPTY;
  const topSkip = new Set([
    "cabinets",
    "panels",
    "rooms",
    "mode",
    "expert",
    "shutters",
    "relay_needs_contactor",
    "underfloor_circuits",
    "name",
    "systems",
    "stage",
    "property_type",
    "floor_area_m2",
    "floors",
  ]);
  applyMappedDemand(out, inputs, mapping, topSkip);
  // Flat shortcuts under systems (systems.leak_zones, …). Nested sections are
  // handled by applySystemsDemand; loop counts stay on the houseLoops path.
  const systemsSkip = new Set([
    ...SYSTEMS_NEST_KEYS,
    "underfloor_circuits",
    "collector_loops",
  ]);
  applyMappedDemand(out, systems, mapping, systemsSkip);

  warnUnrecognisedInputs(inputs, systems, mapping, assumptions);

  return out;
}

/** Section ids + meta under inputs.systems — not channel shortcuts. */
const SYSTEMS_NEST_KEYS = new Set([
  "system",
  "heating",
  "ventilation",
  "water",
  "electrical",
  "security",
  "lighting_scenes",
]);

/** Known field names per Systems section (must match UI SYSTEM_SECTIONS). */
const SYSTEMS_SECTION_FIELDS = {
  heating: new Set([
    "panel_id",
    "boiler",
    "collector_loops",
    "heating_pumps",
    "fan_coils",
    "heat_pump",
    "fireplace",
    "pt100_sensors",
    "ds18b20_sensors",
  ]),
  ventilation: new Set([
    "panel_id",
    "ahu",
    "recuperator",
    "extract_fans",
    "dampers_0_10v",
    "sensors_0_10v",
    "sensors_4_20ma",
  ]),
  water: new Set([
    "panel_id",
    "leak_zones",
    "shutoff_valves",
    "water_meters",
    "irrigation",
    "water_pumps",
    "dhw_recirc",
    "gas_valve",
  ]),
  electrical: new Set([
    "panel_id",
    "energy_phases",
    "load_shed",
    "ev_chargers",
    "pv_inverters",
    "fault_contacts",
  ]),
  security: new Set([
    "panel_id",
    "powered_sensors",
    "dry_contacts",
    "gates",
    "locks",
    "panic_buttons",
  ]),
  lighting_scenes: new Set([
    "panel_id",
    "stair_steps",
    "accent_zones",
    "garden_lights",
  ]),
  system: new Set([
    "reserve_pct",
    "manual_control",
    "ha_server",
    "cabinets",
  ]),
};

const KNOWN_TOP_INPUT_FIELDS = new Set([
  "cabinets",
  "panels",
  "rooms",
  "mode",
  "expert",
  "shutters",
  "relay_needs_contactor",
  "underfloor_circuits",
  "name",
  "systems",
  "stage",
  "property_type",
  "floor_area_m2",
  "floors",
  "light_groups",
  "lights_onoff",
  "_panel_top",
  "_panel_systems",
  "_skip_enclosure_autosplit",
  "_autosplit_depth",
]);

function applyMappedDemand(out, bag, mapping, skipKeys) {
  if (!bag || typeof bag !== "object") return;
  for (const [field, channel] of Object.entries(mapping)) {
    if (skipKeys.has(field)) continue;
    if (bag[field] == null) continue;
    if (channel === "shutters") {
      const n = Number(bag[field]) || 0;
      if (n) out.shutters += n;
      continue;
    }
    if (channel === "relay_needs_contactor") {
      const n = Number(bag[field]) || 0;
      if (n) out.relay_needs_contactor += n;
      continue;
    }
    const n = Number(bag[field]);
    if (Number.isFinite(n) && n !== 0) addDemand(out.demand, channel, n);
    else if (bag[field] === true) addDemand(out.demand, channel, 1);
  }
}

function warnUnrecognisedInputs(inputs, systems, mapping, assumptions) {
  const mappingKeys = new Set(Object.keys(mapping || {}));
  for (const key of Object.keys(inputs || {})) {
    if (KNOWN_TOP_INPUT_FIELDS.has(key) || mappingKeys.has(key)) continue;
    assumptions.push(`unrecognised input field: ${key}`);
  }
  if (!systems || typeof systems !== "object") return;
  for (const key of Object.keys(systems)) {
    if (SYSTEMS_NEST_KEYS.has(key)) continue;
    if (mappingKeys.has(key)) continue;
    assumptions.push(`unrecognised input field: systems.${key}`);
  }
  for (const sec of Object.keys(SYSTEMS_SECTION_FIELDS)) {
    const block = systems[sec];
    if (!block || typeof block !== "object") continue;
    const known = SYSTEMS_SECTION_FIELDS[sec];
    for (const key of Object.keys(block)) {
      if (known.has(key) || mappingKeys.has(key)) continue;
      assumptions.push(`unrecognised input field: systems.${sec}.${key}`);
    }
  }
}

function clamp(n, lo, hi) {
  return Math.min(hi, Math.max(lo, n));
}

function addRelay(out, qty) {
  const n = Math.max(0, Number(qty) || 0);
  if (n > 0) addDemand(out.demand, "relay_out_3a", n);
}

/** Inductive actuators that need an RC snubber / varistor (WLD README). */
function addInductive(out, qty) {
  const n = Math.max(0, Number(qty) || 0);
  if (n > 0) out.inductive_loads = (out.inductive_loads || 0) + n;
}

/**
 * Screen 3 equipment → channel bag.
 * Canonical keys (UI): systems.heating.*, systems.water.*, …
 * Flat demand_mapping aliases under systems (systems.leak_zones, …) are
 * applied in normalize via applyMappedDemand.
 */
function applySystemsDemand(out, systems, rules, assumptions) {
  if (!systems || typeof systems !== "object") return;
  const h = systems.heating || EMPTY;
  const v = systems.ventilation || EMPTY;
  const w = systems.water || EMPTY;
  const e = systems.electrical || EMPTY;
  const s = systems.security || EMPTY;
  const L = systems.lighting_scenes || EMPTY;

  const boiler = String(h.boiler || "none").toLowerCase();
  if (boiler === "opentherm") addDemand(out.demand, "opentherm", 1);
  else if (boiler === "relay") addRelay(out, 1);

  // collector_loops applied later via max()
  addRelay(out, h.heating_pumps);
  addInductive(out, h.heating_pumps);
  addRelay(out, h.fan_coils);
  addInductive(out, h.fan_coils);
  addRelay(out, h.heat_pump);
  addInductive(out, h.heat_pump);
  addRelay(out, h.fireplace);
  addInductive(out, h.fireplace);
  if (h.pt100_sensors) addDemand(out.demand, "rtd_input", h.pt100_sensors);
  if (h.ds18b20_sensors) addDemand(out.demand, "onewire", h.ds18b20_sensors);

  addRelay(out, v.ahu);
  addInductive(out, v.ahu);
  addRelay(out, v.recuperator);
  addInductive(out, v.recuperator);
  addRelay(out, v.extract_fans);
  addInductive(out, v.extract_fans);
  if (v.dampers_0_10v) addDemand(out.demand, "analog_out", v.dampers_0_10v);
  if (v.sensors_0_10v) addDemand(out.demand, "analog_in", v.sensors_0_10v);
  if (v.sensors_4_20ma) addDemand(out.demand, "analog_in", v.sensors_4_20ma);

  if (w.leak_zones) addDemand(out.demand, "leak_or_pulse", w.leak_zones);
  addRelay(out, w.shutoff_valves);
  addInductive(out, w.shutoff_valves);
  if (w.water_meters) addDemand(out.demand, "leak_or_pulse", w.water_meters);
  addRelay(out, w.irrigation);
  addInductive(out, w.irrigation);
  addRelay(out, w.water_pumps);
  addInductive(out, w.water_pumps);
  addRelay(out, w.dhw_recirc);
  addInductive(out, w.dhw_recirc);
  addRelay(out, w.gas_valve);
  addInductive(out, w.gas_valve);

  if (e.energy_phases) addDemand(out.demand, "energy_phase", e.energy_phases);
  addRelay(out, e.load_shed);
  if (e.ev_chargers) {
    addRelay(out, e.ev_chargers);
    out.relay_needs_contactor += Math.max(0, Number(e.ev_chargers) || 0);
  }
  if (e.pv_inverters) addDemand(out.demand, "di_dry", e.pv_inverters);
  if (e.fault_contacts) addDemand(out.demand, "di_dry", e.fault_contacts);

  const sensorTypes = rules.alarm_sensor_types || EMPTY;
  let alarmZones = 0;
  let alarmMa = 0;
  for (const row of s.powered_sensors || []) {
    const qty = Math.max(0, Number(row.qty) || 0);
    if (!qty) continue;
    const spec = sensorTypes[row.type] || { ma: 20 };
    alarmZones += qty;
    alarmMa += qty * (Number(spec.ma) || 20);
  }
  if (alarmZones) addDemand(out.demand, "alarm_zone", alarmZones);
  out.alarm_ma = alarmMa;

  if (s.dry_contacts) addDemand(out.demand, "alarm_zone", s.dry_contacts);
  addRelay(out, s.gates);
  addInductive(out, s.gates);
  if (s.gates) addDemand(out.demand, "di_dry", s.gates);
  addRelay(out, s.locks);
  if (s.panic_buttons) addDemand(out.demand, "alarm_zone", s.panic_buttons);

  if (L.stair_steps) addDemand(out.demand, "pwm_led_ch", L.stair_steps);
  if (L.accent_zones) addDemand(out.demand, "pwm_led_ch", L.accent_zones);
  addRelay(out, L.garden_lights);
}

/**
 * Map one named room card onto the demand bag / shutter count.
 * @param {{ demand: object, shutters: number }} out
 * @param {object} room merged template + overrides
 * @param {object} [raw] original room object (for legacy field detection)
 */
function applyRoomDemand(out, room, raw = room) {
  const lights = Math.max(0, Number(room.lights_onoff) || 0);
  const dimmable = Math.min(lights, Math.max(0, Number(room.lights_dimmable) || 0));
  const onOff = lights - dimmable;
  if (onOff > 0) addDemand(out.demand, "relay_out_3a", onOff);
  if (dimmable > 0) addDemand(out.demand, "dimmer_ac_ch", dimmable);

  const strips = Math.max(0, Number(room.led_strips) || 0);
  const ch = Math.max(3, Math.min(5, Number(room.led_strip_channels) || 4));
  if (strips > 0) addDemand(out.demand, "pwm_led_ch", strips * ch);

  const single = Math.max(0, Number(room.led_single) || 0);
  if (single > 0) addDemand(out.demand, "pwm_led_ch", single);

  const switches = Math.max(0, Number(room.switches) || 0);
  if (switches > 0) addDemand(out.demand, "di_dry", switches);

  const shutters = Math.max(0, Number(room.shutters) || 0);
  if (shutters > 0) out.shutters += shutters;

  // Room collector loops — accumulated for max() with house Systems value.
  const ufh = Math.max(0, Number(room.ufh_loops) || 0);
  if (ufh > 0) out.room_ufh_loops += ufh;

  const ufhEl = Math.max(0, Number(room.ufh_electric) || 0);
  if (ufhEl > 0) addDemand(out.demand, "relay_out_3a", ufhEl);

  const v010 = Math.max(0, Number(room.lights_0_10v) || 0);
  if (v010 > 0) addDemand(out.demand, "analog_out", v010);

  const temp = String(room.temp_sensor || "none").toUpperCase();
  if (temp === "DS18B20") addDemand(out.demand, "onewire", 1);
  else if (temp === "PT100" || temp === "PT1000") addDemand(out.demand, "rtd_input", 1);

  const leak = Math.max(0, Number(room.leak_sensors) || 0);
  if (leak > 0) addDemand(out.demand, "leak_or_pulse", leak);

  const motion = Math.max(0, Number(room.motion_sensors) || 0);
  if (motion > 0) addDemand(out.demand, "presence_in", motion);

  const presence = Math.max(0, Number(room.presence_sensors) || 0);
  if (presence > 0) addDemand(out.demand, "presence_in", presence);

  const doors = Math.max(0, Number(room.door_contacts) || 0);
  if (doors > 0) addDemand(out.demand, "di_dry", doors);

  const sockets = Math.max(0, Number(room.smart_sockets) || 0);
  if (sockets > 0) addDemand(out.demand, "relay_out_3a", sockets);

  const fan = Math.max(0, Number(room.extract_fan) || 0);
  if (fan > 0) {
    addDemand(out.demand, "relay_out_3a", fan);
    out.inductive_loads = (out.inductive_loads || 0) + fan;
  }

  // Legacy fixture fields — only when the new card fields were not supplied.
  if (raw.lights_onoff == null && raw.light_groups != null) {
    const legacyLights = Math.max(0, Number(raw.light_groups) || 0);
    if (legacyLights > 0) addDemand(out.demand, "relay_out_3a", legacyLights);
  }
  if (raw.switches == null && raw.keys != null) {
    const legacyKeys = Math.max(0, Number(raw.keys) || 0);
    if (legacyKeys > 0) addDemand(out.demand, "di_dry", legacyKeys);
  }
}

function addDemand(bag, channel, qty) {
  const n = Number(qty);
  if (!Number.isFinite(n) || n === 0) return;
  bag[channel] = (bag[channel] ?? 0) + n;
}

// ── Stage 2: demand ─────────────────────────────────────────────────

function buildDemand(normalized, _rules) {
  return {
    ...normalized.demand,
    shutters: normalized.shutters,
    relay_needs_contactor: normalized.relay_needs_contactor,
    inductive_loads: normalized.inductive_loads || 0,
    _reserve_pct: normalized.reserve_pct,
  };
}

function almSensorRails(rules) {
  const rails = rules.modules?.["ALM-173-R1"]?.sensor_rails;
  if (!Array.isArray(rails)) return { v12: 150, v5: 200 };
  const r12 = rails.find((r) => Number(r.voltage_v) === 12);
  const r5 = rails.find((r) => Number(r.voltage_v) === 5);
  return {
    v12: r12?.budget_ma != null ? Number(r12.budget_ma) : 150,
    v5: r5?.budget_ma != null ? Number(r5.budget_ma) : 200,
  };
}

function warnAlmRail(allocated, normalized, rules, assumptions) {
  const ma = normalized.alarm_ma || 0;
  if (ma <= 0) return;
  // 12 V budget is shared across PS/1 and PS/2 — never multiply by terminal count.
  const { v12: rail } = almSensorRails(rules);
  const almQty = allocated.modules["ALM-173-R1"] || 0;
  const budget = rail * Math.max(almQty, 1);
  if (ma > budget) {
    assumptions.push(
      `ALM 12 V rail: ${ma} mA sensor draw exceeds ${budget} mA ` +
        `(${rail} mA shared across PS/1+PS/2 × ${Math.max(almQty, 1)} module(s)). ` +
        `Use an external supply or more ALM modules.`,
    );
  } else {
    assumptions.push(
      `ALM 12 V rail: ${ma} mA of ${budget} mA budget ` +
        `(${rail} mA shared across PS/1+PS/2 per module).`,
    );
  }
}

/**
 * 1-Wire aux rail budget across modules that feed onewire (OTG 50 mA, WLD 150 mA, …).
 * Rails with budget_ma null (MISSING) are noted but not counted.
 */
function warnOnewireRails(demand, modulesList, rules, assumptions) {
  const sensors = Math.max(0, Number(demand.onewire) || 0);
  if (sensors <= 0) return;
  const designMa = rules.policy?.onewire_sensor_design_ma ?? 5;
  const draw = sensors * designMa;
  let budget = 0;
  const parts = [];
  const missing = [];
  const specs = rules.modules ?? EMPTY;

  for (const line of modulesList || []) {
    const rails = specs[line.id]?.sensor_rails;
    if (!Array.isArray(rails)) continue;
    for (const rail of rails) {
      if (!(rail.feeds || []).includes("onewire")) continue;
      if (rail.budget_ma == null || !Number.isFinite(Number(rail.budget_ma))) {
        missing.push(line.id);
        continue;
      }
      const railQty = Math.max(1, Number(rail.qty) || 1) * (line.qty || 1);
      const ma = Number(rail.budget_ma) * railQty;
      budget += ma;
      const vNote = rail.also_voltage_v
        ? `${rail.voltage_v}/${rail.also_voltage_v} V`
        : `${rail.voltage_v} V`;
      parts.push(`${line.qty}× ${line.id} ${vNote} @ ${rail.budget_ma} mA`);
    }
  }

  if (missing.length) {
    assumptions.push(
      `1-Wire aux rail: current limit MISSING in specs for ${[...new Set(missing)].join(", ")}.`,
    );
  }
  if (budget <= 0) {
    if (!missing.length) {
      assumptions.push(
        `1-Wire: ${sensors} sensor(s) × ${designMa} mA design = ${draw} mA — no module rail budget available.`,
      );
    }
    return;
  }
  if (draw > budget) {
    assumptions.push(
      `1-Wire sensor rail: ${draw} mA design draw (${sensors}× ${designMa} mA) exceeds ${budget} mA (${parts.join("; ")}). Use fewer sensors or an external supply.`,
    );
  } else {
    assumptions.push(
      `1-Wire sensor rail: ${draw} mA of ${budget} mA budget (${parts.join("; ")}).`,
    );
  }
}

// ── Stage 3: allocate (supply-pool / deficit) ────────────────────────

/**
 * Channels that exist on modules but are never auto-assigned.
 * Installer uses them deliberately (inverted fail-on logic).
 */
const RESERVE_ONLY_CHANNELS = new Set(["relay_out_nc"]);

const RELAY_NC_RESERVE_NOTE =
  "Not auto-assigned. Inverted logic — load is powered when the relay is de-energised. Use it yourself where equipment must switch on if the panel loses power.";

/** Effective channel provides for one module instance. */
function effectiveProvides(modId, rules) {
  const spec = (rules.modules ?? EMPTY)[modId];
  if (!spec) return {};
  const out = {};
  for (const [ch, n] of Object.entries(spec.provides || {})) {
    const v = Number(n) || 0;
    if (v <= 0) continue;
    if (ch === "out_24v_ch") {
      const policyCap = rules.policy?.str_actuators_per_module ?? 32;
      out[ch] = Math.min(v, policyCap);
    } else {
      out[ch] = v;
    }
  }
  return out;
}

/** Provides that may enter the allocate supply pool (excludes reserve-only). */
function poolProvides(modId, rules) {
  const out = { ...effectiveProvides(modId, rules) };
  for (const ch of RESERVE_ONLY_CHANNELS) delete out[ch];
  return out;
}

function addProvides(supply, provides, qty = 1) {
  for (const [ch, n] of Object.entries(provides || {})) {
    if (RESERVE_ONLY_CHANNELS.has(ch)) continue;
    supply[ch] = (supply[ch] || 0) + n * qty;
  }
}

function channelDeficit(needed, supply, shutterNeed) {
  const def = {};
  for (const [ch, n] of Object.entries(needed)) {
    const d = n - (supply[ch] || 0);
    if (d > 0) def[ch] = d;
  }
  if (shutterNeed > 0) def.shutter_interlock = shutterNeed;
  return def;
}

/**
 * Pick which deficit channel to cover next.
 * Specialty order first, then shutters, then universal relay/DI.
 */
function pickDeficitChannel(def, allocateOrder) {
  for (const ch of allocateOrder || []) {
    if (def[ch] > 0) return ch;
  }
  if (def.shutter_interlock > 0) return "shutter_interlock";
  if (def.relay_out_3a > 0) return "relay_out_3a";
  if (def.di_dry > 0) return "di_dry";
  return Object.keys(def)[0] || null;
}

function moduleForChannel(channel, rules) {
  if (RESERVE_ONLY_CHANNELS.has(channel)) return null;
  if (channel === "shutter_interlock" || channel === "relay_out_3a" || channel === "di_dry") {
    return "DIO-430-R1";
  }
  return (rules.specialty_modules ?? EMPTY)[channel] || null;
}

/**
 * Allocate slaves by growing a shared supply pool.
 * Controller provides are injected first when known.
 * A module is added only while some channel still has deficit; every channel
 * it provides joins the pool (side channels included).
 *
 * @param {{ recordReserve?: boolean, trackInstances?: boolean }} [opts]
 */
function allocateWithPool(demand, rules, assumptions, controllerSupply, opts = {}) {
  const trackInstances = opts.trackInstances === true;
  const modules = {};
  const accessories = [];
  const provenance = [];
  const instances = [];

  const needed = {};
  for (const [ch, n] of Object.entries(demand)) {
    if (
      ch === "shutters" ||
      ch === "relay_needs_contactor" ||
      ch === "inductive_loads" ||
      ch === "_reserve_pct"
    ) {
      continue;
    }
    if (RESERVE_ONLY_CHANNELS.has(ch)) continue;
    const v = Number(n) || 0;
    if (v > 0) needed[ch] = v;
  }
  let shutterNeed = Math.max(0, Number(demand.shutters) || 0);

  const contactorCount = Math.max(0, Number(demand.relay_needs_contactor) || 0);
  if (contactorCount > 0) {
    accessories.push({
      id: "contactor_modular",
      qty: contactorCount,
      label: "Modular contactor",
      requirement: true,
    });
    provenance.push({ kind: "relay_needs_contactor", qty: contactorCount });
  }

  const supply = {};
  addProvides(supply, controllerSupply);
  provenance.push({
    kind: "controller_supply",
    supply: { ...controllerSupply },
  });

  const order = rules.allocate_order ?? [];
  let guard = 0;
  while (guard++ < 200) {
    const def = channelDeficit(needed, supply, shutterNeed);
    const channel = pickDeficitChannel(def, order);
    if (!channel) break;

    const modId = moduleForChannel(channel, rules);
    if (!modId) {
      assumptions.push(`No module covers channel ${channel} (deficit ${def[channel]}).`);
      break;
    }

    const caps = poolProvides(modId, rules);
    if (channel === "shutter_interlock") {
      // One DIO per shutter (interlock pair). Free 3rd relay + all DI enter the pool.
      addModule(modules, modId, 1, "shutter_interlock");
      if (trackInstances) instances.push({ id: modId, shutter: true });
      shutterNeed -= 1;
      supply.relay_out_3a = (supply.relay_out_3a || 0) + 1;
      supply.di_dry = (supply.di_dry || 0) + (caps.di_dry || 0);
      provenance.push({
        kind: "shutter_interlock",
        module: modId,
        note: "Interlock pair on DIO; 1 free relay_out_3a + DI enter supply pool.",
      });
      continue;
    }

    if ((caps[channel] || 0) <= 0 && channel !== "shutter_interlock") {
      assumptions.push(`Module ${modId} does not provide ${channel}.`);
      break;
    }

    addModule(modules, modId, 1, `deficit:${channel}`);
    if (trackInstances) instances.push({ id: modId, shutter: false });
    addProvides(supply, caps);
    provenance.push({
      kind: "deficit",
      channel,
      module: modId,
      added_provides: caps,
      deficit_before: def[channel],
    });
  }

  return {
    modules,
    accessories,
    provenance,
    instances,
    supply,
    needed,
    shutter_need_remaining: shutterNeed,
    remaining: channelDeficit(needed, supply, shutterNeed),
  };
}

function controllerCandidates(rules) {
  const list = rules.controllers?.candidates;
  if (Array.isArray(list) && list.length > 0) return list;
  return ["MicroPLC", "MiniPLC"];
}

/** Price + DIN score for one controller + its slave modules. */
function scoreControllerCombo(ctrlId, modulesBag, rules, prices) {
  let money = 0;
  let din = 0;
  let priced = true;
  const ctrlSpec = (rules.modules ?? EMPTY)[ctrlId];
  const ctrlPrice = ctrlSpec?.sku ? prices?.[ctrlSpec.sku] : null;
  // Prefer in-stock controllers when the shop marks one OutOfStock.
  const available = !ctrlPrice || ctrlPrice.available !== false;
  const add = (id, qty) => {
    const spec = (rules.modules ?? EMPTY)[id];
    if (!spec) {
      priced = false;
      return;
    }
    const d = Number(spec.din_units);
    if (Number.isFinite(d)) din += d * qty;
    else priced = false;
    const p = prices?.[spec.sku];
    if (p && typeof p.amount === "number") money += p.amount * qty;
    else priced = false;
  };
  add(ctrlId, 1);
  for (const [id, qty] of Object.entries(modulesBag || {})) {
    if (id === "_sources" || typeof qty !== "number") continue;
    if ((rules.modules ?? EMPTY)[id]?.master) continue;
    add(id, qty);
  }
  return { money, din, priced, available };
}

function comboBetter(a, b) {
  if (!b) return true;
  if (a.available !== b.available) return a.available;
  if (a.priced && b.priced) {
    if (a.money !== b.money) return a.money < b.money;
    return a.din < b.din;
  }
  return a.din < b.din;
}

/**
 * Pick MicroPLC or MiniPLC for a segment demand by trying both + slave modules.
 * Cheaper by shop prices; ties / missing prices → fewer DIN units.
 */
function pickControllerForDemand(segDemand, rules, prices, assumptions) {
  const candidates = controllerCandidates(rules);
  let best = null;
  for (const ctrlId of candidates) {
    const trialAssumptions = [];
    const alloc = allocateWithPool(
      segDemand,
      rules,
      trialAssumptions,
      effectiveProvides(ctrlId, rules),
      { recordReserve: false, trackInstances: false },
    );
    const score = scoreControllerCombo(ctrlId, alloc.modules, rules, prices);
    if (!best || comboBetter(score, best.score)) {
      best = { id: ctrlId, alloc, score };
    }
  }
  if (!best) {
    const fallback = candidates[0] || "MicroPLC";
    const alloc = allocateWithPool(segDemand, rules, assumptions, {}, {
      recordReserve: false,
    });
    return { id: fallback, alloc, score: scoreControllerCombo(fallback, alloc.modules, rules, prices) };
  }
  assumptions.push(
    `Controller ${best.id}: ` +
      (best.score.priced
        ? `${best.score.money} price units, ${best.score.din} M`
        : `${best.score.din} M (prices incomplete — DIN only)`),
  );
  return best;
}

function slaveLinesFromBare(bare, rules) {
  const moduleSpecs = rules.modules ?? EMPTY;
  if (bare.instances?.length) {
    return bare.instances.map((inst) => {
      const w = Number(moduleSpecs[inst.id]?.poll_weight);
      return {
        id: inst.id,
        shutter: !!inst.shutter,
        poll_weight: Number.isFinite(w) ? w : 0,
      };
    });
  }
  const lines = [];
  for (const [id, qty] of Object.entries(bare.modules || {})) {
    if (id === "_sources" || typeof qty !== "number") continue;
    if (moduleSpecs[id]?.master) continue;
    const w = Number(moduleSpecs[id]?.poll_weight);
    for (let i = 0; i < qty; i++) {
      lines.push({
        id,
        shutter: false,
        poll_weight: Number.isFinite(w) ? w : 0,
      });
    }
  }
  return lines;
}

/**
 * Attribute panel channel demand to packed segments by claiming each slave's
 * provides (and shutter flags) from the remaining global demand.
 */
function splitDemandAcrossSegments(demand, segments, rules) {
  const remaining = {};
  for (const [ch, n] of Object.entries(demand || {})) {
    if (ch === "shutters" || ch === "relay_needs_contactor" || ch === "inductive_loads" || ch === "_reserve_pct") continue;
    const v = Number(n) || 0;
    if (v > 0) remaining[ch] = v;
  }
  let shuttersLeft = Math.max(0, Number(demand.shutters) || 0);
  const reserve = demand._reserve_pct;
  const out = [];

  for (const seg of segments) {
    const segD = {};
    if (reserve != null) segD._reserve_pct = reserve;
    let segShutters = 0;
    for (const slave of seg.slaves) {
      if (slave.shutter) {
        segShutters += 1;
        // Shutter DIO interlock uses two relays; the free third relay + all DI
        // enter the supply pool — claim those against remaining demand here.
        const takeRelay = Math.min(1, remaining.relay_out_3a || 0);
        if (takeRelay > 0) {
          segD.relay_out_3a = (segD.relay_out_3a || 0) + takeRelay;
          remaining.relay_out_3a -= takeRelay;
          if (remaining.relay_out_3a <= 0) delete remaining.relay_out_3a;
        }
        const diCap = effectiveProvides(slave.id, rules).di_dry || 0;
        const takeDi = Math.min(diCap, remaining.di_dry || 0);
        if (takeDi > 0) {
          segD.di_dry = (segD.di_dry || 0) + takeDi;
          remaining.di_dry -= takeDi;
          if (remaining.di_dry <= 0) delete remaining.di_dry;
        }
        continue;
      }
      const caps = poolProvides(slave.id, rules);
      for (const [ch, n] of Object.entries(caps)) {
        const take = Math.min(n, remaining[ch] || 0);
        if (take > 0) {
          segD[ch] = (segD[ch] || 0) + take;
          remaining[ch] -= take;
          if (remaining[ch] <= 0) delete remaining[ch];
        }
      }
    }
    const takeSh = Math.min(segShutters, shuttersLeft);
    if (takeSh > 0) {
      segD.shutters = takeSh;
      shuttersLeft -= takeSh;
    }
    out.push(segD);
  }

  // Demand covered only via side-channels of modules already claimed: fold leftovers
  // into the first segment so nothing is dropped.
  if (out.length > 0) {
    for (const [ch, n] of Object.entries(remaining)) {
      if (n > 0) out[0][ch] = (out[0][ch] || 0) + n;
    }
    if (shuttersLeft > 0) {
      out[0].shutters = (out[0].shutters || 0) + shuttersLeft;
    }
  }
  return out;
}

function mergeModuleBags(into, from) {
  for (const [id, qty] of Object.entries(from || {})) {
    if (id === "_sources" || typeof qty !== "number") continue;
    into[id] = (into[id] || 0) + qty;
  }
}

/**
 * Allocate slaves, then choose each segment's controller by channel economics
 * (MicroPLC vs MiniPLC + add-on modules). Segment count comes from bare-module
 * poll_weight packing — not from controller type.
 */
function allocate(demand, rules, assumptions, normalized = EMPTY, prices = EMPTY) {
  const segmentBudget = rules.bus?.segment_budget ?? 10;
  const hardMax = rules.bus?.hard_max_modules ?? 15;
  const minSegments = Math.max(1, Number(normalized.cabinets) || 1);

  // Contactors once for the whole panel.
  const contactorDemand = {
    relay_needs_contactor: demand.relay_needs_contactor || 0,
  };
  const contactorPart = allocateWithPool(contactorDemand, rules, assumptions, {}, {
    recordReserve: false,
  });

  // Bare slave BOM (no controller I/O) — drives segment packing / count.
  const bareDemand = { ...demand, relay_needs_contactor: 0 };
  const bare = allocateWithPool(bareDemand, rules, [], {}, {
    recordReserve: false,
    trackInstances: true,
  });
  const slaveLines = slaveLinesFromBare(bare, rules);
  let segments = packSegments(slaveLines, segmentBudget, hardMax, minSegments);

  const mergedModules = {};
  const mergedSupply = {};
  let shutterNeedRemaining = 0;
  const provenance = [...(contactorPart.provenance || [])];
  const picks = [];
  const segmentPlans = [];

  function absorbAlloc(alloc) {
    for (const [ch, n] of Object.entries(alloc?.supply || {})) {
      mergedSupply[ch] = (mergedSupply[ch] || 0) + (Number(n) || 0);
    }
    shutterNeedRemaining += Math.max(0, Number(alloc?.shutter_need_remaining) || 0);
  }

  if (segments.length === 0) {
    // Controller-only (or empty) panel — still one controller on the cabinet.
    const pick = pickControllerForDemand(bareDemand, rules, prices, assumptions);
    picks.push(pick.id);
    mergeModuleBags(mergedModules, pick.alloc.modules);
    absorbAlloc(pick.alloc);
    provenance.push(...(pick.alloc.provenance || []));
    segmentPlans.push({ controller: pick.id, modules: { ...pick.alloc.modules } });
  } else {
    const segDemands = splitDemandAcrossSegments(bareDemand, segments, rules);
    for (let i = 0; i < segments.length; i++) {
      const pick = pickControllerForDemand(segDemands[i], rules, prices, assumptions);
      picks.push(pick.id);
      mergeModuleBags(mergedModules, pick.alloc.modules);
      absorbAlloc(pick.alloc);
      provenance.push(...(pick.alloc.provenance || []));
      segmentPlans.push({
        controller: pick.id,
        modules: { ...pick.alloc.modules },
      });
    }
  }

  const result = {
    modules: mergedModules,
    accessories: contactorPart.accessories || [],
    provenance,
    controller_picks: picks,
    segment_plans: segmentPlans,
    supply: mergedSupply,
    shutter_need_remaining: shutterNeedRemaining,
  };
  result.provenance = result.provenance.filter((p) => p.kind !== "controller_picks");
  result.provenance.push({ kind: "controller_picks", picks });
  return result;
}

function addModule(bag, id, qty, source) {
  if (qty <= 0) return;
  bag[id] = (bag[id] ?? 0) + qty;
  if (!bag._sources) bag._sources = {};
  bag._sources[id] = bag._sources[id] ?? [];
  bag._sources[id].push(source);
}

// ── Stage 4: topology ───────────────────────────────────────────────

function expandPlanSlaves(modulesBag, rules) {
  const moduleSpecs = rules.modules ?? EMPTY;
  const lines = [];
  for (const [id, qty] of Object.entries(modulesBag || {})) {
    if (id === "_sources" || typeof qty !== "number") continue;
    if (moduleSpecs[id]?.master) continue;
    const spec = moduleSpecs[id];
    const weight = Number(spec?.poll_weight);
    for (let i = 0; i < qty; i++) {
      lines.push({
        id,
        poll_weight: Number.isFinite(weight) ? weight : 0,
        sku: spec?.sku,
        tmpl_id: spec?.product_template_id,
        product_id: spec?.product_id,
        shop_url: spec?.shop_url,
      });
    }
  }
  return lines;
}

function buildTopology(allocated, normalized, rules, assumptions) {
  const moduleSpecs = rules.modules ?? EMPTY;
  const terminatorsPer = rules.terminators_per_segment ?? 2;
  const warnAbove = rules.bus?.warn_above ?? 12;
  const minSegments = Math.max(1, Number(normalized.cabinets) || 1);
  const fallbackCtrl = controllerCandidates(rules)[0] || "MicroPLC";

  const moduleMap = {};
  const segments = [];
  const plans = allocated.segment_plans;

  if (Array.isArray(plans) && plans.length > 0) {
    for (const plan of plans) {
      const slaves = expandPlanSlaves(plan.modules, rules);
      const ctrlId = plan.controller || fallbackCtrl;
      segments.push({
        slaves,
        controller: ctrlId,
        poll_weight: slaves.reduce((s, sl) => s + sl.poll_weight, 0),
        terminators: terminatorsPer,
      });
      addModule(moduleMap, ctrlId, 1, "topology:controller");
      for (const [id, qty] of Object.entries(plan.modules || {})) {
        if (id === "_sources" || typeof qty !== "number") continue;
        addModule(moduleMap, id, qty, "allocate");
      }
    }
  } else {
    // Legacy path: pack slaves, one fallback controller each.
    const slaves = expandPlanSlaves(allocated.modules, rules);
    let packed = packSegments(
      slaves,
      rules.bus?.segment_budget ?? 10,
      rules.bus?.hard_max_modules ?? 15,
      minSegments,
    );
    if (packed.length === 0) {
      packed = Array.from({ length: minSegments }, () => ({
        slaves: [],
        poll_weight: 0,
      }));
    }
    for (const seg of packed) {
      seg.controller = fallbackCtrl;
      seg.terminators = terminatorsPer;
      seg.poll_weight = seg.slaves.reduce((s, sl) => s + sl.poll_weight, 0);
      segments.push(seg);
      addModule(moduleMap, fallbackCtrl, 1, "topology:controller");
    }
    for (const [id, qty] of Object.entries(allocated.modules || {})) {
      if (id === "_sources" || typeof qty !== "number") continue;
      if (moduleSpecs[id]?.master) continue;
      addModule(moduleMap, id, qty, "allocate");
    }
  }

  const warnings = [];
  for (const seg of segments) {
    if (seg.slaves.length > warnAbove) {
      warnings.push(`Segment has ${seg.slaves.length} slaves (warn above ${warnAbove}).`);
    }
  }

  const esphome = buildEsphomeYaml(segments, rules);

  const modulesList = Object.entries(moduleMap)
    .filter(([id]) => id !== "_sources")
    .map(([id, qty]) => moduleLine(id, qty, moduleSpecs, allocated));

  const controllers = segments.map((seg, i) => ({
    id: seg.controller,
    segment: i + 1,
    segment_index: i,
    slaves: (seg.slaves || []).length,
    poll_weight: seg.poll_weight ?? 0,
  }));

  return {
    modules: modulesList,
    accessories: allocated.accessories,
    provenance: allocated.provenance,
    topology: {
      segments,
      controllers,
      segment_count: segments.length,
      esphome_yaml: esphome,
      warnings,
    },
    assumptions,
  };
}

/**
 * Pack slaves into RS-485 segments.
 * Segment count comes from poll_weight vs budget, hard_max_modules, and
 * cabinets as a minimum — but never from the room count, and never by
 * creating empty segments (those previously spawned extra controllers).
 */
function packSegments(slaves, budget, hardMax, minSegments) {
  if (slaves.length === 0) return [];

  // First-fit decreasing by poll_weight.
  const sorted = [...slaves].sort((a, b) => b.poll_weight - a.poll_weight);
  let segments = [{ slaves: [], poll_weight: 0 }];

  for (const slave of sorted) {
    let placed = false;
    for (const seg of segments) {
      const newWeight = seg.poll_weight + slave.poll_weight;
      const newCount = seg.slaves.length + 1;
      if (newWeight <= budget && newCount <= hardMax) {
        seg.slaves.push(slave);
        seg.poll_weight = newWeight;
        placed = true;
        break;
      }
    }
    if (!placed) {
      segments.push({ slaves: [slave], poll_weight: slave.poll_weight });
    }
  }

  // Honour cabinets as a floor only while every segment still has ≥1 slave.
  const target = Math.min(Math.max(1, minSegments), slaves.length);
  while (segments.length < target) {
    const donor = segments.reduce((a, b) =>
      b.slaves.length > a.slaves.length ? b : a,
    );
    if (donor.slaves.length <= 1) break;
    const moved = donor.slaves.pop();
    donor.poll_weight = donor.slaves.reduce((s, sl) => s + sl.poll_weight, 0);
    segments.push({ slaves: [moved], poll_weight: moved.poll_weight });
  }

  return segments.filter((seg) => seg.slaves.length > 0);
}

function buildEsphomeYaml(segments, rules) {
  const defs = rules.esphome_defaults ?? EMPTY;
  const lines = [
    "# RS-485 Modbus bus configuration",
    `# ${defs.comment ?? "Explicit timings required."}`,
    "",
  ];
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i];
    lines.push(`modbus_controller:`);
    lines.push(`  - id: hm_segment_${i + 1}`);
    lines.push(`    update_interval: 1s`);
    lines.push(`    command_throttle: 0ms`);
    if (rules.bus?.requires_explicit_timings) {
      lines.push(`    turnaround_time: ${defs.turnaround_time ?? "100ms"}`);
      lines.push(`    send_wait_time: ${defs.send_wait_time ?? "250ms"}`);
    }
    lines.push(`    # slaves: ${seg.slaves.map((s) => s.id).join(", ") || "none"}`);
    lines.push("");
  }
  return lines.join("\n");
}

function moduleLine(id, qty, moduleSpecs, allocated) {
  const spec = moduleSpecs[id] ?? EMPTY;
  return {
    id,
    sku: spec.sku ?? `HM-${id}`,
    qty,
    tmpl_id: spec.product_template_id,
    product_id: spec.product_id,
    shop_url: spec.shop_url ?? "",
    provenance: allocated.modules._sources?.[id] ?? [],
  };
}

// ── Stage 5: power ──────────────────────────────────────────────────
//
// Three independent supplies — never sum field LED load into logic PSU:
//   1. Module logic PSU (24 V DC) — Σ power_w_max × headroom — one per panel
//   2. One LED PS per RGB / STR module (separate LED PS inputs, 12/24 V)
//   3. Strip length unknown — RGB ceiling only; STR sized by assigned actuators

function splitAcrossModules(total, moduleQty, perMod) {
  const out = [];
  let left = Math.max(0, Number(total) || 0);
  const n = Math.max(0, Math.floor(Number(moduleQty) || 0));
  const cap = Math.max(1, Number(perMod) || 32);
  for (let i = 0; i < n; i++) {
    const take = Math.min(cap, left);
    out.push(take);
    left -= take;
  }
  return out;
}

function computePower(modulesList, rules, assumptions, demand = EMPTY) {
  const moduleSpecs = rules.modules ?? EMPTY;
  const headroomPct = rules.policy?.psu_headroom_pct ?? 30;
  const headroomFactor = 1 + headroomPct / 100;

  let logicW = 0;
  let strModules = 0;
  let rgbModules = 0;
  const requirements = [];
  const ledSupplies = [];

  for (const line of modulesList) {
    const spec = moduleSpecs[line.id] ?? EMPTY;
    logicW += (spec.power_w_max ?? 0) * line.qty;

    if (line.id === "STR-3221-R1") strModules += line.qty;
    if (line.id === "RGB-621-R1") rgbModules += line.qty;

    if (line.id === "ALM-173-R1" && line.qty > 0) {
      const { v12, v5 } = almSensorRails(rules);
      requirements.push({
        kind: "alm_12v",
        text:
          `${line.qty}× ALM-173-R1: isolated sensor domain (GND_ISO) — ` +
          `12 V @ ${v12} mA shared across PS/1+PS/2; 5 V @ ${v5} mA. ` +
          `12 V and 5 V share GND_ISO (not separate islands); isolation is field↔logic only.`,
      });
    }
    if (line.id === "WLD-521-R1" && line.qty > 0) {
      requirements.push({
        kind: "wld_supply",
        text: `${line.qty}× WLD-521-R1: ~150 mA sensor supply budget per module (+12 V / +5 V ISO shared).`,
      });
    }
    if (line.id === "OpenthermGateway" && line.qty > 0) {
      requirements.push({
        kind: "otg_5v",
        text: `${line.qty}× OpenthermGateway: +5 V aux for 1-Wire sensors, max 50 mA per module.`,
      });
    }
    if (line.id === "AIO-422-R1" && line.qty > 0) {
      requirements.push({
        kind: "loop_power",
        text: `${line.qty}× AIO-422-R1: 4–20 mA loops — 20 mA × 24 V per active loop.`,
      });
    }
  }

  const moduleCount = modulesList.reduce((s, l) => s + l.qty, 0);
  const capacitanceUF = 330 * moduleCount;

  // 1. Logic only — shared 24 V source for this panel.
  const logicTotal = logicW * headroomFactor;
  const logicWMin = Math.ceil(logicTotal);
  requirements.unshift({
    kind: "module_logic_psu",
    text: `Module logic PSU — 24 V DC, ≥${logicWMin} W`,
  });

  const inrushA = rules.policy?.str_actuator_inrush_a ?? 0.3;
  const perMod = rules.policy?.str_actuators_per_module ?? 32;
  const strLim =
    moduleSpecs["STR-3221-R1"]?.led_ps_input_a ??
    rules.policy?.str_led_ps_input_a ??
    20;
  const rgbLim =
    moduleSpecs["RGB-621-R1"]?.led_ps_input_a ??
    rules.policy?.rgb_led_ps_input_a ??
    10;

  // 2. One LED PS per STR — actuators split across modules (not capacity).
  const assigned = Math.max(0, Number(demand.out_24v_ch) || 0);
  const strShare = splitAcrossModules(assigned, strModules, perMod);
  let strLedPsA = 0;
  let strActuators = 0;
  for (let i = 0; i < strShare.length; i++) {
    const n = strShare[i];
    strActuators += n;
    const a = round1(n * inrushA);
    strLedPsA = round1(strLedPsA + a);
    const sized =
      n > 0
        ? `≥${a} A for ${n} actuators, up to ${strLim} A`
        : `up to ${strLim} A`;
    const text = `LED PS for STR-3221-R1 #${i + 1} — 12/24 V, ${sized}`;
    requirements.push({ kind: "str_led_ps", text, module: "STR-3221-R1", index: i + 1 });
    ledSupplies.push({
      id: "psu_led_str",
      module: "STR-3221-R1",
      index: i + 1,
      label: text,
      actuators: n,
      amps: a,
    });
  }

  // 3. One LED PS per RGB — ceiling only.
  for (let i = 0; i < rgbModules; i++) {
    const text = `LED PS for RGB-621-R1 #${i + 1} — 12/24 V, up to ${rgbLim} A`;
    requirements.push({ kind: "rgb_led_ps", text, module: "RGB-621-R1", index: i + 1 });
    ledSupplies.push({
      id: "psu_led_rgb",
      module: "RGB-621-R1",
      index: i + 1,
      label: text,
      actuators: 0,
      amps: 0,
    });
  }

  requirements.push({
    kind: "capacitance",
    text: `Bulk capacitance: ${capacitanceUF} µF recommended (330 µF × ${moduleCount} modules).`,
  });

  return {
    logic_w: round1(logicW),
    field_w: 0,
    str_led_ps_a: strLedPsA,
    str_led_ps_actuators: strActuators,
    str_led_ps_w: 0,
    led_supplies: ledSupplies,
    total_w: round1(logicTotal),
    headroom_pct: headroomPct,
    capacitance_uF: capacitanceUF,
    requirements,
  };
}

function round1(n) {
  return Math.round(n * 10) / 10;
}

// ── Companions (panel hardware without SKU) ─────────────────────────

/**
 * Build companion BOM lines that contribute DIN width but never prices.
 * Per-circuit MCB from used switched channels; field terminals from
 * field_wires_per_channel (terminal-maps); incomer stays separate.
 */
function buildCompanions(
  allocated,
  modulesList,
  power,
  normalized,
  rules,
  assumptions,
  demand = EMPTY,
  opts = {},
) {
  const labels = rules.companion_labels ?? EMPTY;
  const dinMap = rules.companion_din_units ?? EMPTY;
  const out = [];

  for (const a of allocated.accessories || []) {
    out.push({
      id: a.id,
      qty: a.qty,
      label: a.label || labels[a.id] || a.id,
      requirement: !!a.requirement,
      din_units: dinMap[a.id] ?? null,
      sku: "",
      unit_price: null,
      rating: null,
    });
  }

  const moduleCount = (modulesList || []).reduce(
    (s, l) => s + Math.max(0, Number(l.qty) || 0),
    0,
  );
  const hasMiniPlc = (modulesList || []).some(
    (l) => l.id === "MiniPLC" && (l.qty || 0) > 0,
  );
  const haNeeded =
    opts.haServerNeeded != null
      ? !!opts.haServerNeeded
      : (normalized.ha_server || "needed") !== "own";
  const includeHa = !!opts.includeHaServer && haNeeded;

  if (includeHa) {
    out.push({
      id: "ha_server_din",
      qty: 1,
      label: labels.ha_server_din || "Home Assistant server (DIN)",
      requirement: true,
      din_units: dinMap.ha_server_din ?? 6,
      sku: "",
      unit_price: null,
      rating: null,
      role: "network",
      note: "One per project — first panel when Home Assistant server is needed.",
    });
  }

  if (hasMiniPlc || haNeeded) {
    out.push({
      id: "eth_switch_din",
      qty: 1,
      label: labels.eth_switch_din || "Ethernet switch (DIN)",
      requirement: true,
      din_units: dinMap.eth_switch_din ?? 4,
      sku: "",
      unit_price: null,
      rating: null,
      role: "network",
      note: hasMiniPlc
        ? "MiniPLC has Ethernet — DIN switch in this panel."
        : "Home Assistant server needed — DIN Ethernet switch in this panel.",
    });
  }

  const watts = power.total_w ?? 0;
  if (watts > 0) {
    if (watts <= 60) {
      out.push({
        id: "psu_din_60w",
        qty: 1,
        label: labels.psu_din_60w || "DIN PSU 60 W (module logic)",
        requirement: true,
        din_units: dinMap.psu_din_60w ?? 4,
        sku: "",
        unit_price: null,
        rating: null,
        role: "logic",
      });
    } else {
      const qty = Math.max(1, Math.ceil(watts / 100));
      out.push({
        id: "psu_din_100w",
        qty,
        label: labels.psu_din_100w || "DIN PSU 100 W (module logic)",
        requirement: true,
        din_units: dinMap.psu_din_100w ?? 6,
        sku: "",
        unit_price: null,
        rating: null,
        role: "logic",
      });
    }
  }

  // One DIN LED PSU per RGB / STR module (separate LED PS inputs).
  for (const led of power.led_supplies || []) {
    out.push({
      id: led.id,
      qty: 1,
      label: led.label,
      requirement: true,
      din_units: dinMap[led.id] ?? dinMap.psu_din_100w ?? 6,
      sku: "",
      unit_price: null,
      rating: null,
      role: "led_ps",
      bind_module: led.module,
      bind_index: led.index,
    });
  }

  // 24 V logic distribution — fused per branch (RGB README); terminals V+/0V per module.
  if (moduleCount > 0 && watts > 0) {
    out.push({
      id: "fuse_24v_branch",
      qty: moduleCount,
      label: labels.fuse_24v_branch || "24 V branch fuse (1 M)",
      requirement: true,
      din_units: dinMap.fuse_24v_branch ?? 1,
      sku: "",
      unit_price: null,
      rating: null,
      role: "logic_dist",
      note: "One fuse per module on the shared 24 V logic PSU (fused per branch).",
    });
    out.push({
      id: "terminal_24v",
      qty: moduleCount * 2,
      label: labels.terminal_24v || "24 V distribution terminal",
      requirement: true,
      din_units: dinMap.terminal_24v ?? 0.35,
      sku: "",
      unit_price: null,
      rating: null,
      role: "logic_dist",
      note: "V+ and 0 V landing per module on the logic supply.",
    });
  }

  const cabinets = Math.max(1, normalized.cabinets || 1);

  // Incomer — separate from per-circuit protection.
  out.push({
    id: "mcb_1p_n",
    qty: cabinets,
    label: labels.mcb_1p_n || "MCB 1P+N (incomer)",
    requirement: true,
    din_units: dinMap.mcb_1p_n ?? 2,
    sku: "",
    unit_price: null,
    rating: null,
    note: "Panel incomer — not group / per-circuit protection.",
  });
  out.push({
    id: "rcd_2p",
    qty: cabinets,
    label: labels.rcd_2p || "RCD 2P (incomer)",
    requirement: true,
    din_units: dinMap.rcd_2p ?? 2,
    sku: "",
    unit_price: null,
    rating: null,
    note: "Panel incomer RCD.",
  });
  assumptions.push(
    `Incomer protection: ${cabinets}× MCB 1P+N + ${cabinets}× RCD 2P (panel incomer, not per-circuit).`,
  );

  // Per used switched circuit — count by assignment, not module capacity.
  const relayCircuits = Math.max(0, Number(demand.relay_out_3a) || 0);
  const dimmerCircuits = Math.max(0, Number(demand.dimmer_ac_ch) || 0);
  const contactorLoads = Math.max(0, Number(demand.relay_needs_contactor) || 0);
  const shutterCircuits = Math.max(0, Number(demand.shutters) || 0);
  const perCircuit =
    relayCircuits + dimmerCircuits + contactorLoads + shutterCircuits;
  const PER_CIRCUIT_NOTE =
    "Per-circuit overcurrent protection is mandatory (module README). " +
    "Module output limit is 3 A per relay — a shared breaker must NOT " +
    "be sized by summation of outputs. Rating to be determined by the " +
    "electrical design: load, installation method, and local code.";
  if (perCircuit > 0) {
    out.push({
      id: "mcb_1p",
      qty: perCircuit,
      label: labels.mcb_1p || "MCB 1P (per load circuit)",
      requirement: true,
      din_units: dinMap.mcb_1p ?? 1,
      sku: "",
      unit_price: null,
      rating: null,
      note: PER_CIRCUIT_NOTE,
    });
    assumptions.push(
      `Per-circuit protection: ${perCircuit}× MCB 1P (${relayCircuits} relay + ${dimmerCircuits} dimmer + ${contactorLoads} contactor + ${shutterCircuits} shutter). ` +
        `If RCBO 1P+N (2 M) is chosen instead, protection DIN width doubles.`,
    );
  }

  const inductive =
    Math.max(0, Number(demand.inductive_loads) || 0) + shutterCircuits;
  if (inductive > 0) {
    out.push({
      id: "snubber_rc",
      qty: inductive,
      label: labels.snubber_rc || "RC snubber / varistor (inductive load)",
      requirement: true,
      din_units: dinMap.snubber_rc ?? 0,
      sku: "",
      unit_price: null,
      rating: null,
      note: "Mandatory for inductive loads (pumps, valves, fans, actuators) per module README.",
    });
  }

  // Mains field circuits: phase on field terminals (relay NO+C / dimmer L);
  // N and PE land on 12-way bars — not the same wires as the switched pair.
  const mainsCircuits =
    relayCircuits + dimmerCircuits + shutterCircuits + contactorLoads;
  if (mainsCircuits > 0) {
    const barQty = Math.ceil(mainsCircuits / 12);
    out.push({
      id: "n_bar_12",
      qty: barQty,
      label: labels.n_bar_12 || "N bar 12-way (1 M)",
      requirement: true,
      din_units: dinMap.n_bar_12 ?? 1,
      sku: "",
      unit_price: null,
      rating: null,
      note: `${mainsCircuits} mains circuit(s) → ${barQty}× 12-way N bar.`,
    });
    out.push({
      id: "pe_bar_12",
      qty: barQty,
      label: labels.pe_bar_12 || "PE bar 12-way (1 M)",
      requirement: true,
      din_units: dinMap.pe_bar_12 ?? 1,
      sku: "",
      unit_price: null,
      rating: null,
      note: `${mainsCircuits} mains circuit(s) → ${barQty}× 12-way PE bar.`,
    });
    assumptions.push(
      `Mains landing: ${mainsCircuits} circuit(s) — switched phase on field ` +
        `terminal(s) (relay NO+C or dimmer L); N on ${barQty}× n_bar_12; ` +
        `PE on ${barQty}× pe_bar_12. NO+C are not N/PE.`,
    );
  }

  const termCounts = countFieldTerminals(
    demand,
    modulesList,
    rules,
    assumptions,
  );
  if (termCounts.single > 0) {
    out.push({
      id: "terminal_block",
      qty: termCounts.single,
      label: labels.terminal_block || "Field terminal (1-tier)",
      requirement: true,
      din_units: dinMap.terminal_block ?? 0.35,
      sku: "",
      unit_price: null,
      rating: null,
    });
  }
  if (termCounts.double > 0) {
    out.push({
      id: "terminal_block_2t",
      qty: termCounts.double,
      label: labels.terminal_block_2t || "Field terminal (2-tier, two circuits)",
      requirement: true,
      din_units: dinMap.terminal_block_2t ?? 0.35,
      sku: "",
      unit_price: null,
      rating: null,
      note: "One 2-tier block per channel with exactly two field wires.",
    });
  }

  out.push({
    id: "internal_wiring",
    qty: 1,
    label: labels.internal_wiring || "Internal wiring (terminals → modules)",
    requirement: true,
    din_units: dinMap.internal_wiring ?? 0,
    sku: "",
    unit_price: null,
    rating: null,
    meters: null,
    note: "Cross-section per circuit; labelling per project. Meterage TBD.",
  });

  // Markers: field + 24 V terminals + protective devices.
  const termQty =
    termCounts.single +
    termCounts.double +
    (out.find((c) => c.id === "terminal_24v")?.qty || 0);
  const breakerQty = out
    .filter((c) =>
      /^(mcb_|rcd_|rcbo_)/.test(c.id),
    )
    .reduce((s, c) => s + (Number(c.qty) || 0), 0);
  const markerQty = termQty + breakerQty;
  if (markerQty > 0) {
    out.push({
      id: "terminal_markers",
      qty: markerQty,
      label: labels.terminal_markers || "Terminal / circuit markers",
      requirement: true,
      din_units: dinMap.terminal_markers ?? 0,
      sku: "",
      unit_price: null,
      rating: null,
      note: `${termQty} terminal(s) + ${breakerQty} protective device(s).`,
    });
  }

  const dinModules = (modulesList || []).reduce((s, l) => {
    const w = Number(rules.modules?.[l.id]?.din_units);
    return s + (Number.isFinite(w) ? w * (l.qty || 0) : 0);
  }, 0);
  const termDin =
    termCounts.single * (dinMap.terminal_block ?? 0.35) +
    termCounts.double * (dinMap.terminal_block_2t ?? 0.35);
  const termPositions = termCounts.single + termCounts.double;
  if (termDin > dinModules && termPositions > 0) {
    assumptions.push(
      `Field terminals DIN width (${round2(termDin)} M) exceeds HomeMaster modules (${round2(dinModules)} M).`,
    );
  }

  return out;
}

/**
 * Field intermediate terminals from used channels × terminal-maps derived table.
 * Slaves first (field I/O), then masters — matches workshop wiring: field
 * cables land on expansion-module terminals before controller onboard I/O.
 * Each shutter DIO uses two relay groups (interlock); the free third relay
 * and DI remain available for other demand on that module.
 *
 * A channel with exactly 2 field wires → one 2-tier terminal (0.35 M).
 * Otherwise one 1-tier terminal per wire.
 *
 * @returns {{ single: number, double: number }}
 */
function countFieldTerminals(demand, modulesList, rules, assumptions) {
  const table = rules.field_wires_per_channel || EMPTY;
  const remaining = {};
  for (const [ch, n] of Object.entries(demand || {})) {
    if (
      ch === "shutters" ||
      ch === "relay_needs_contactor" ||
      ch === "inductive_loads" ||
      ch === "_reserve_pct"
    ) {
      continue;
    }
    const v = Math.max(0, Number(n) || 0);
    if (v > 0) remaining[ch] = v;
  }
  let shuttersLeft = Math.max(0, Number(demand.shutters) || 0);

  let single = 0;
  let double = 0;
  const missingMods = [];

  function addWires(wireCount, times = 1) {
    const n = Math.max(0, Number(times) || 0);
    if (n <= 0) return;
    const w = Math.max(0, Number(wireCount) || 0);
    if (w === 2) double += n;
    else if (w > 0) single += w * n;
  }

  const ordered = [...(modulesList || [])].sort((a, b) => {
    const am = rules.modules?.[a.id]?.master ? 1 : 0;
    const bm = rules.modules?.[b.id]?.master ? 1 : 0;
    return am - bm;
  });

  for (const line of ordered) {
    const entry = table[line.id];
    if (!entry || entry.MISSING === "terminal-maps confidence not full") {
      if (
        (line.qty || 0) > 0 &&
        rules.modules?.[line.id] &&
        !rules.modules[line.id].master
      ) {
        missingMods.push(line.id);
      }
      continue;
    }
    if (Array.isArray(entry.MISSING) && entry.MISSING.length) {
      for (const ch of entry.MISSING) {
        if ((remaining[ch] || 0) > 0) {
          assumptions.push(
            `field_wires MISSING for ${line.id} channel ${ch} — terminals not counted.`,
          );
        }
      }
    }
    const channels = entry.channels || EMPTY;
    const qty = Math.max(0, Number(line.qty) || 0);
    const relayConf =
      channels.relay_out_3a || channels.relay_out_nc || null;
    const relayPer = Number(relayConf?.per_channel) || 0;
    const canShutter =
      shuttersLeft > 0 &&
      line.id === "DIO-430-R1" &&
      relayPer > 0 &&
      (Number(rules.modules?.[line.id]?.provides?.relay_out_3a) || 0) >= 2;

    for (let i = 0; i < qty; i++) {
      let usedOnThis = false;
      let relayCap =
        Number(rules.modules?.[line.id]?.provides?.relay_out_3a) ||
        Number(rules.modules?.[line.id]?.provides?.relay_out_nc) ||
        0;

      if (canShutter && shuttersLeft > 0) {
        // Interlock pair: two relay terminal groups per shutter.
        addWires(relayPer, 2);
        shuttersLeft -= 1;
        relayCap = Math.max(0, relayCap - 2);
        usedOnThis = true;
      }

      for (const [ch, conf] of Object.entries(channels)) {
        const need = remaining[ch] || 0;
        if (need <= 0) continue;
        let capacity =
          Number(rules.modules?.[line.id]?.provides?.[ch]) || 0;
        if (ch === "relay_out_3a" || ch === "relay_out_nc") {
          capacity = relayCap;
        }
        if (capacity <= 0 && !conf.group_capacity) continue;
        const take = Math.min(
          need,
          capacity > 0 ? capacity : Number(conf.group_capacity) || 0,
        );
        if (take <= 0) continue;
        usedOnThis = true;
        remaining[ch] = need - take;
        if (remaining[ch] <= 0) delete remaining[ch];
        if (ch === "relay_out_3a" || ch === "relay_out_nc") {
          relayCap = Math.max(0, relayCap - take);
        }
        const per = Number(conf.per_channel) || 0;
        addWires(per, take);
        if (conf.shared_rail_per_group && conf.group_size) {
          const groups = Math.ceil(take / Number(conf.group_size));
          addWires(Number(conf.shared_rail_per_group) || 0, groups);
        }
        if (conf.shared_return_per_module) {
          addWires(Number(conf.shared_return_per_module) || 0, 1);
        }
      }
      if (usedOnThis) {
        addWires(Number(entry.shared_per_module) || 0, 1);
      }
    }
  }

  if (shuttersLeft > 0) {
    assumptions.push(
      `field_wires: ${shuttersLeft}× shutter still unassigned to a DIO terminal map.`,
    );
  }
  for (const [ch, n] of Object.entries(remaining)) {
    if (n > 0) {
      assumptions.push(
        `field_wires: ${n}× ${ch} still unassigned to a module terminal map.`,
      );
    }
  }
  if (missingMods.length) {
    assumptions.push(
      `field_wires table missing/incomplete for: ${[...new Set(missingMods)].join(", ")}.`,
    );
  }
  return { single, double };
}

// ── Stage 6: enclosure ──────────────────────────────────────────────

function dinWidthForModule(line, moduleSpecs) {
  const spec = moduleSpecs[line.id];
  if (!spec) return { width: null, missing: true };
  if (spec.din_units == null) return { width: null, missing: true };
  return { width: Number(spec.din_units) * line.qty, missing: false };
}

function enclosureDimsMm(rowWidth, rows) {
  return {
    width_mm: rowWidth * ENCLOSURE_TE_MM + ENCLOSURE_WIDTH_MARGIN_MM,
    height_mm: rows * ENCLOSURE_ROW_PITCH_MM + ENCLOSURE_HEIGHT_MARGIN_MM,
  };
}

/**
 * Enumerate row_width ∈ {12,18,24} × rows ∈ {1..6}. Prefer best aspect
 * ratio, then least spare capacity, then fewer rows. Whole rows only.
 * @returns {null|{row_width,rows,capacity,width_mm,height_mm,aspect,spare}}
 */
function pickEnclosureLayout(needed) {
  const need = Math.max(0, Math.ceil(Number(needed) || 0));
  let best = null;
  for (const rowWidth of ENCLOSURE_ROW_WIDTHS) {
    for (let rows = 1; rows <= ENCLOSURE_MAX_ROWS; rows++) {
      const capacity = rows * rowWidth;
      if (capacity < need) continue;
      const { width_mm, height_mm } = enclosureDimsMm(rowWidth, rows);
      const aspect =
        Math.max(width_mm, height_mm) / Math.min(width_mm, height_mm);
      const spare = capacity - need;
      const cand = {
        row_width: rowWidth,
        rows,
        capacity,
        width_mm,
        height_mm,
        aspect,
        spare,
      };
      if (
        !best ||
        aspect < best.aspect - 1e-9 ||
        (Math.abs(aspect - best.aspect) < 1e-9 && spare < best.spare) ||
        (Math.abs(aspect - best.aspect) < 1e-9 &&
          spare === best.spare &&
          rows < best.rows) ||
        (Math.abs(aspect - best.aspect) < 1e-9 &&
          spare === best.spare &&
          rows === best.rows &&
          rowWidth < best.row_width)
      ) {
        best = cand;
      }
    }
  }
  return best;
}

/**
 * Pick 1..ENCLOSURE_MAX_SECTIONS identical bodies so total capacity ≥ need.
 * Prefer fewer sections, then least spare, then best single-body aspect.
 */
function pickCoupledEnclosure(dinNeeded) {
  const need = Math.max(0, Math.ceil(Number(dinNeeded) || 0));
  let best = null;
  for (let sections = 1; sections <= ENCLOSURE_MAX_SECTIONS; sections++) {
    const needPer = Math.ceil(need / sections);
    const layout = pickEnclosureLayout(needPer);
    if (!layout) continue;
    const capacity = layout.capacity * sections;
    const spare = capacity - need;
    const cand = {
      cabinets: sections,
      row_width: layout.row_width,
      rows: layout.rows,
      capacity_each: layout.capacity,
      capacity,
      width_mm: layout.width_mm * sections,
      height_mm: layout.height_mm,
      section_width_mm: layout.width_mm,
      aspect: layout.aspect,
      spare,
    };
    if (
      !best ||
      cand.cabinets < best.cabinets ||
      (cand.cabinets === best.cabinets && cand.spare < best.spare) ||
      (cand.cabinets === best.cabinets &&
        cand.spare === best.spare &&
        cand.aspect < best.aspect - 1e-9)
    ) {
      best = cand;
    }
  }
  return best;
}

/**
 * Sum DIN units across HomeMaster modules + companions, apply reserve
 * once, then pick coupled enclosure section(s). Blanking / enclosure BOM
 * lines are added afterwards (they must not inflate din_needed).
 */
function computeEnclosure(modulesList, companions, rules) {
  const moduleSpecs = rules.modules ?? EMPTY;
  const dinMap = rules.companion_din_units ?? EMPTY;
  const missing = [];

  for (const line of modulesList) {
    const { missing: miss } = dinWidthForModule(line, moduleSpecs);
    if (miss) missing.push(line.id);
  }

  if (missing.length > 0) {
    return {
      status: "blocked",
      reason: "din_units_missing",
      modules: [...new Set(missing)],
    };
  }

  let dinModules = 0;
  const breakdown = [];
  for (const line of modulesList) {
    const w = Number(moduleSpecs[line.id].din_units) * line.qty;
    dinModules += w;
    breakdown.push({
      id: line.id,
      qty: line.qty,
      din_units: moduleSpecs[line.id].din_units,
      din_total: w,
      kind: "module",
    });
  }

  let dinCompanions = 0;
  for (const c of companions || []) {
    if (c.id === "blanking_plate" || c.id === "din_enclosure") continue;
    const unit =
      c.din_units != null ? Number(c.din_units) : Number(dinMap[c.id]);
    if (!Number.isFinite(unit) || !c.qty) continue;
    const w = unit * c.qty;
    dinCompanions += w;
    breakdown.push({
      id: c.id,
      label: c.label,
      qty: c.qty,
      din_units: unit,
      din_total: w,
      kind: "companion",
    });
  }

  const dinTotal = dinModules + dinCompanions;
  // No enclosure reserve % — size to occupied DIN (ceil). Unused channels
  // on modules already in the BOM are free spare and do not add DIN.
  const dinReserve = 0;
  const reservePct = 0;
  const dinNeeded = Math.ceil(dinTotal - 1e-9);
  const layout = pickCoupledEnclosure(dinNeeded);

  if (!layout) {
    return {
      status: "overflow",
      din_modules: round2(dinModules),
      din_companions: round2(dinCompanions),
      din_total: round2(dinTotal),
      din_occupied: round2(dinTotal),
      din_reserve: dinReserve,
      reserve_pct: reservePct,
      din_needed: dinNeeded,
      din_free: null,
      // Aliases for the quote / console (same values as din_*).
      occupied: round2(dinTotal),
      reserve: dinReserve,
      free: null,
      cabinets: null,
      row_width: null,
      rows: null,
      capacity_each: null,
      capacity: null,
      width_mm: null,
      height_mm: null,
      overflow: true,
      max_capacity: ENCLOSURE_MAX_CAPACITY,
      max_sections: ENCLOSURE_MAX_SECTIONS,
      breakdown,
    };
  }

  const dinFree = Math.max(0, layout.capacity - dinNeeded);

  return {
    status: "ok",
    din_modules: round2(dinModules),
    din_companions: round2(dinCompanions),
    din_total: round2(dinTotal),
    din_occupied: round2(dinTotal),
    din_reserve: dinReserve,
    reserve_pct: reservePct,
    din_needed: dinNeeded,
    din_free: dinFree,
    occupied: round2(dinTotal),
    reserve: dinReserve,
    free: dinFree,
    cabinets: layout.cabinets,
    row_width: layout.row_width,
    rows: layout.rows,
    capacity_each: layout.capacity_each,
    capacity: layout.capacity,
    width_mm: layout.width_mm,
    height_mm: layout.height_mm,
    section_width_mm: layout.section_width_mm,
    overflow: false,
    max_capacity: ENCLOSURE_MAX_CAPACITY,
    max_sections: ENCLOSURE_MAX_SECTIONS,
    breakdown,
  };
}

/**
 * Blanking plates fill unused DIN slots; enclosure is a quote line with
 * approx. outer dimensions. Neither feeds back into din_needed.
 */
function finalizeEnclosureCompanions(companions, enclosure, rules, assumptions) {
  const labels = rules.companion_labels ?? EMPTY;
  const dinMap = rules.companion_din_units ?? EMPTY;
  const out = [...(companions || [])];
  if (
    !enclosure ||
    enclosure.status === "blocked" ||
    enclosure.status === "overflow" ||
    enclosure.overflow
  ) {
    return out;
  }

  const capacity = Number(enclosure.capacity) || 0;
  const occupied = Number(enclosure.din_occupied ?? enclosure.din_total) || 0;
  const blankQty = Math.max(0, Math.floor(capacity - occupied + 1e-9));
  if (blankQty > 0) {
    out.push({
      id: "blanking_plate",
      qty: blankQty,
      label: labels.blanking_plate || "DIN blanking plate",
      requirement: true,
      din_units: dinMap.blanking_plate ?? 1,
      sku: "",
      unit_price: null,
      rating: null,
      note: "Covers unused DIN slots behind the false panel.",
    });
  }

  const rows = enclosure.rows;
  const rowWidth = enclosure.row_width;
  const capEach = enclosure.capacity_each;
  const cabinets = Math.max(1, enclosure.cabinets || 1);
  const w = enclosure.width_mm;
  const h = enclosure.height_mm;
  const note =
    `Occupied ${enclosure.din_occupied} M · needed ${enclosure.din_needed} M · ` +
    `free after rounding ${enclosure.din_free} M.` +
    (cabinets > 1 ? " Coupled enclosure sections." : " Final enclosure selection by the electrical design.");
  out.push({
    id: "din_enclosure",
    // Single quote line; section count lives in enclosure.cabinets and the label.
    qty: 1,
    label:
      cabinets > 1
        ? `DIN enclosure, ${cabinets} × (${rows} rows × ${rowWidth}) = ${capacity} modules, approx. ${w} × ${h} mm — supplied as coupled sections.`
        : `DIN enclosure, ${rows} rows × ${rowWidth} = ${capEach} modules, approx. ${w} × ${h} mm`,
    requirement: true,
    din_units: dinMap.din_enclosure ?? 0,
    sku: "",
    unit_price: null,
    rating: null,
    note,
  });
  enclosure.blanking_qty = blankQty;

  const railRows =
    Math.max(1, Number(enclosure.rows) || 1) *
    Math.max(1, Number(enclosure.cabinets) || 1);
  out.push({
    id: "din_rail",
    qty: railRows,
    label: labels.din_rail || "DIN rail",
    requirement: true,
    din_units: dinMap.din_rail ?? 0,
    sku: "",
    unit_price: null,
    rating: null,
    note: `One rail per enclosure row (${enclosure.row_width} M). Base of the row — no DIN width.`,
  });

  return out;
}

const CHANNEL_LABELS = {
  relay_out_3a: "Relay ≤3 A (NO/SPDT)",
  relay_out_nc: "Relay NC-only (reserve)",
  di_dry: "Dry inputs",
  out_24v_ch: "24 V outputs",
  onewire: "1-Wire",
  pwm_led_ch: "LED PWM channels",
  dimmer_ac_ch: "Dimmer channels",
  leak_or_pulse: "Leak / pulse inputs",
  energy_phase: "Energy phases",
  alarm_zone: "Alarm zones",
  opentherm: "OpenTherm",
  analog_in: "Analog inputs",
  analog_out: "Analog outputs",
  rtd_input: "RTD inputs",
  presence_in: "Presence inputs",
  shutter_interlock: "Shutter interlocks",
};

/**
 * Channel usage from the allocate supply pool (controller + modules, with
 * shutter free-relay accounting already applied).
 * Reserve-only channels (relay_out_nc) are listed separately — never needed.
 */
function computeChannelUsage(demand, modulesList, rules, allocated) {
  const needed = {};
  for (const [ch, n] of Object.entries(demand || {})) {
    if (ch === "shutters" || ch === "relay_needs_contactor" || ch === "inductive_loads" || ch === "_reserve_pct") continue;
    if (RESERVE_ONLY_CHANNELS.has(ch)) continue;
    const v = Number(n) || 0;
    if (v > 0) needed[ch] = v;
  }
  const shutters = Math.max(0, Number(demand?.shutters) || 0);
  if (shutters > 0) needed.shutter_interlock = shutters;

  const supplied = { ...(allocated?.supply || {}) };
  if (shutters > 0) {
    const remaining = Math.max(0, Number(allocated?.shutter_need_remaining) || 0);
    supplied.shutter_interlock = shutters - remaining;
  }

  const rows = [];
  for (const ch of Object.keys(needed)) {
    const need = needed[ch];
    const have = supplied[ch] || 0;
    rows.push({
      channel: ch,
      label: CHANNEL_LABELS[ch] || ch,
      needed: need,
      supplied: have,
      spare: have - need,
    });
  }

  // NC-only relays sit on the BOM but are never auto-assigned.
  let ncReserve = 0;
  const specs = rules?.modules ?? EMPTY;
  for (const line of modulesList || []) {
    const n = Number(specs[line.id]?.provides?.relay_out_nc) || 0;
    if (n > 0) ncReserve += n * (line.qty || 0);
  }
  if (ncReserve > 0) {
    rows.push({
      channel: "relay_out_nc",
      label: CHANNEL_LABELS.relay_out_nc,
      needed: 0,
      supplied: ncReserve,
      spare: ncReserve,
      reserve: true,
      note: RELAY_NC_RESERVE_NOTE,
    });
  }

  rows.sort((a, b) => a.label.localeCompare(b.label));
  return rows;
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

// ── Stage 7: price ──────────────────────────────────────────────────

function attachPrices(
  topologyResult,
  companions,
  power,
  enclosure,
  rules,
  prices,
  assumptions,
) {
  const moduleSpecs = rules.modules ?? EMPTY;
  const modules = topologyResult.modules.map((m) => ({
    ...m,
    din_units: moduleSpecs[m.id]?.din_units ?? null,
    price: prices[m.sku] ?? null,
  }));

  const accessories = (companions || []).map((a) => ({
    ...a,
    price: null,
  }));

  const cart_lines = modules
    .filter((m) => m.sku?.startsWith("HM-"))
    .map((m) => ({
      tmpl_id: m.tmpl_id,
      product_id: m.product_id,
      qty: m.qty,
      sku: m.sku,
    }));

  const lines = [
    ...modules.map((m) => ({
      kind: "module",
      sku: m.sku,
      label: m.id,
      qty: m.qty,
      din_units: m.din_units,
      unit_price: m.price?.amount ?? null,
      currency: m.price?.currency ?? null,
      shop_url: m.shop_url,
      requirement: false,
    })),
    ...accessories.map((a) => ({
      kind: "companion",
      sku: "",
      label: a.label ?? a.id,
      qty: a.qty,
      din_units: a.din_units,
      unit_price: null,
      currency: null,
      requirement: true,
    })),
    ...power.requirements
      .filter((r) => r.kind !== "psu")
      .map((r) => ({
        kind: "requirement",
        label: r.text,
        requirement: true,
        din_units: null,
        unit_price: null,
      })),
  ];

  return {
    modules,
    accessories,
    cart_lines,
    topology: topologyResult.topology,
    power,
    enclosure,
    lines,
    // topologyResult.assumptions is the same array as `assumptions` in the
    // normal pipeline — do not concatenate or every note is doubled.
    assumptions: assumptions || topologyResult.assumptions || [],
    provenance: topologyResult.provenance,
  };
}

HM.estimate = estimate;
HM.resolvePanels = resolvePanels;

// ===== prices.js =====
/**
 * Runtime prices from Odoo shop Product ld+json.
 * Never baked into rules.json or the published artifact.
 *
 * Currency selection (in order):
 * 1. Caller / host-page session preference
 * 2. Visible shop price on the product HTML (oe_currency_value amount
 *    matched to an offer; else currency text next to that widget)
 * 3. First offer + currencyAmbiguous when multiple offers exist
 */

const CACHE_PREFIX = "hm_price_";
const URL_CACHE_PREFIX = "hm_price_url_";

/**
 * @param {unknown} node
 * @returns {object[]}
 */
function asArray(node) {
  if (node == null) return [];
  return Array.isArray(node) ? node : [node];
}

/**
 * @param {string} text
 * @returns {string|null}
 */
function currencyFromText(text) {
  if (!text) return null;
  if (/€|\bEUR\b/i.test(text)) return "EUR";
  if (/\blei\b|\bRON\b/i.test(text)) return "RON";
  if (/\$|\bUSD\b/i.test(text)) return "USD";
  if (/£|\bGBP\b/i.test(text)) return "GBP";
  return null;
}

/**
 * Parse a shop price amount from visible widget text (handles "1,464.10").
 * @param {string} text
 * @returns {number|null}
 */
function parseVisibleAmount(text) {
  if (!text) return null;
  const m = String(text).replace(/\s/g, "").match(/(\d{1,3}(?:,\d{3})*(?:\.\d+)?|\d+(?:\.\d+)?)/);
  if (!m) return null;
  const n = Number(m[1].replace(/,/g, ""));
  return Number.isFinite(n) ? n : null;
}

/**
 * Read the visible product price widget — not ld+json offer order.
 * @param {string} html
 * @returns {{ amount: number|null, currency: string|null }}
 */
function detectVisiblePrice(html) {
  if (!html) return { amount: null, currency: null };

  if (typeof DOMParser !== "undefined") {
    const doc = new DOMParser().parseFromString(html, "text/html");
    const nodes = [
      ...doc.querySelectorAll("span.oe_currency_value"),
      ...doc.querySelectorAll("[data-website_sale_currency]"),
      ...doc.querySelectorAll(".product_price .oe_currency_value, .oe_price .oe_currency_value"),
    ];
    for (const node of nodes) {
      const amount = parseVisibleAmount(node.textContent || "");
      const chunk = `${node.textContent || ""} ${node.parentElement?.textContent || ""}`;
      const currency = currencyFromText(chunk);
      if (amount != null || currency) return { amount, currency };
    }
    return { amount: null, currency: null };
  }

  const re =
    /<span[^>]*class="[^"]*oe_currency_value[^"]*"[^>]*>([\s\S]*?)<\/span>([\s\S]{0,80})/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    const amount = parseVisibleAmount(m[1]);
    const currency = currencyFromText(m[0] + m[2]);
    if (amount != null || currency) return { amount, currency };
  }
  return { amount: null, currency: null };
}

/**
 * Infer session currency from visible shop price chrome.
 * @param {string} html
 * @returns {string|null}
 */
function detectCurrencyFromHtml(html) {
  return detectVisiblePrice(html).currency;
}

/**
 * @param {object|object[]} offers
 * @param {{ preferredCurrency?: string|null, visibleAmount?: number|null }} opts
 */
function pickOffer(offers, opts = {}) {
  const list = asArray(offers)
    .flatMap((o) => {
      if (o && typeof o === "object" && Array.isArray(o.offers)) return o.offers;
      return [o];
    })
    .filter(Boolean);

  if (!list.length) return null;

  const visibleAmount = opts.visibleAmount;
  if (visibleAmount != null && Number.isFinite(visibleAmount)) {
    const byAmount = list.find((o) => {
      const p = Number(o.price);
      return Number.isFinite(p) && Math.abs(p - visibleAmount) < 0.021;
    });
    if (byAmount) {
      return {
        offer: byAmount,
        currencyChosen: byAmount.priceCurrency || null,
        ambiguous: false,
      };
    }
  }

  const preferred = opts.preferredCurrency;
  if (preferred) {
    const match = list.find(
      (o) => String(o.priceCurrency || "").toUpperCase() === preferred.toUpperCase(),
    );
    if (match) {
      return { offer: match, currencyChosen: match.priceCurrency, ambiguous: false };
    }
  }

  const first = list[0];
  return {
    offer: first,
    currencyChosen: first.priceCurrency || null,
    ambiguous: list.length > 1,
  };
}

/**
 * @param {string} html
 * @param {{ preferredCurrency?: string|null }} [opts]
 */
function parseProductLdJson(html, opts = {}) {
  const visible = detectVisiblePrice(html);
  const preferred = opts.preferredCurrency ?? visible.currency ?? null;

  if (typeof DOMParser === "undefined") {
    return parseProductLdJsonFallback(html, {
      preferredCurrency: preferred,
      visibleAmount: visible.amount,
    });
  }
  const doc = new DOMParser().parseFromString(html, "text/html");
  const scripts = doc.querySelectorAll('script[type="application/ld+json"]');
  for (const script of scripts) {
    let data;
    try {
      data = JSON.parse(script.textContent || "");
    } catch {
      continue;
    }
    for (const item of asArray(data)) {
      const types = asArray(item["@type"]).map(String);
      if (!types.includes("Product")) continue;
      const sku = item.sku || item.mpn;
      if (!sku) continue;
      const picked = pickOffer(item.offers, {
        preferredCurrency: preferred,
        visibleAmount: visible.amount,
      });
      if (!picked) continue;
      const price = Number(picked.offer.price);
      if (!Number.isFinite(price)) continue;
      const avail = String(picked.offer.availability || "");
      return {
        sku: String(sku),
        price,
        currency: String(picked.currencyChosen || "EUR"),
        available: !avail || avail.includes("InStock") || avail.includes("LimitedAvailability"),
        currencyAmbiguous: picked.ambiguous,
      };
    }
  }
  return null;
}

function parseProductLdJsonFallback(html, opts) {
  const preferred = opts.preferredCurrency ?? null;
  const visibleAmount = opts.visibleAmount ?? null;
  const marker = 'type="application/ld+json"';
  let from = 0;
  while (from < html.length) {
    const i = html.indexOf(marker, from);
    if (i < 0) break;
    const start = html.indexOf(">", i) + 1;
    const end = html.indexOf("</script>", start);
    if (end < 0) break;
    from = end + 9;
    let data;
    try {
      data = JSON.parse(html.slice(start, end));
    } catch {
      continue;
    }
    for (const item of asArray(data)) {
      const types = asArray(item["@type"]).map(String);
      if (!types.includes("Product")) continue;
      const sku = item.sku || item.mpn;
      if (!sku) continue;
      const picked = pickOffer(item.offers, { preferredCurrency: preferred, visibleAmount });
      if (!picked) continue;
      const price = Number(picked.offer.price);
      if (!Number.isFinite(price)) continue;
      const avail = String(picked.offer.availability || "");
      return {
        sku: String(sku),
        price,
        currency: String(picked.currencyChosen || "EUR"),
        available: !avail || avail.includes("InStock"),
        currencyAmbiguous: picked.ambiguous,
      };
    }
  }
  return null;
}

function cacheSet(sku, info) {
  try {
    if (typeof sessionStorage === "undefined") return;
    if (sku) sessionStorage.setItem(CACHE_PREFIX + sku, JSON.stringify(info));
  } catch {
    /* ignore quota */
  }
}

function cacheSetUrl(shopUrl, info) {
  try {
    if (typeof sessionStorage === "undefined" || !shopUrl) return;
    sessionStorage.setItem(URL_CACHE_PREFIX + shopUrl, JSON.stringify(info));
  } catch {
    /* ignore quota */
  }
}

function cacheGetUrl(shopUrl) {
  try {
    if (typeof sessionStorage === "undefined" || !shopUrl) return null;
    const raw = sessionStorage.getItem(URL_CACHE_PREFIX + shopUrl);
    if (!raw) return null;
    const info = JSON.parse(raw);
    if (!info?.sku || !Number.isFinite(info.price)) return null;
    return info;
  } catch {
    return null;
  }
}

/**
 * Detect shop session currency from the current page.
 * Prefers a visible price widget; falls back to active pricelist label.
 * @returns {string|null}
 */
function detectShopCurrency() {
  if (typeof document === "undefined") return null;
  const html = document.documentElement?.outerHTML || "";
  const fromPrice = detectCurrencyFromHtml(html);
  if (fromPrice) return fromPrice;

  // Active pricelist label (e.g. "Romania" → often RON; "Europe" / "EU" → EUR)
  const active =
    document.querySelector(".o_pricelist_dropdown .dropdown-item.active .switcher_pricelist") ||
    document.querySelector(".o_pricelist_dropdown .dropdown-toggle");
  if (active) {
    const label = (active.textContent || "").trim();
    if (/romania|ron|lei/i.test(label)) return "RON";
    if (/europe|euro|\bEU\b|\bEUR\b/i.test(label)) return "EUR";
    if (/usd|dollar/i.test(label)) return "USD";
  }
  return null;
}

/**
 * @param {string} shopUrl
 * @param {{ preferredCurrency?: string|null, fetchImpl?: typeof fetch, bypassCache?: boolean }} [opts]
 */
async function fetchPrice(shopUrl, opts = {}) {
  if (!shopUrl) return null;
  if (!opts.bypassCache) {
    const cached = cacheGetUrl(shopUrl);
    if (cached) return cached;
  }
  const fetchImpl = opts.fetchImpl || (typeof fetch !== "undefined" ? fetch : null);
  if (!fetchImpl) return { sku: "", price: NaN, currency: "", available: false, error: "no_fetch" };

  try {
    const ctrl = typeof AbortSignal !== "undefined" && AbortSignal.timeout ? AbortSignal.timeout(8000) : undefined;
    const res = await fetchImpl(shopUrl, { credentials: "same-origin", signal: ctrl });
    if (!res.ok) {
      return { sku: "", price: NaN, currency: "", available: false, error: `http_${res.status}` };
    }
    const html = await res.text();
    // Host/session preference first; product page visible price is the
    // authority inside parseProductLdJson (amount → matching offer).
    const preferred = opts.preferredCurrency ?? detectShopCurrency();
    const parsed = parseProductLdJson(html, { preferredCurrency: preferred });
    if (!parsed) {
      return { sku: "", price: NaN, currency: "", available: false, error: "no_ldjson" };
    }
    cacheSet(parsed.sku, parsed);
    cacheSetUrl(shopUrl, parsed);
    return parsed;
  } catch (err) {
    return {
      sku: "",
      price: NaN,
      currency: "",
      available: false,
      error: err instanceof Error ? err.message : "fetch_failed",
    };
  }
}

/**
 * @param {string[]} shopUrls
 * @param {{ preferredCurrency?: string|null, fetchImpl?: typeof fetch, bypassCache?: boolean }} [opts]
 */
async function fetchPrices(shopUrls, opts = {}) {
  const map = new Map();
  const urls = [...new Set((shopUrls || []).filter(Boolean))];
  const sessionCurrency = opts.preferredCurrency ?? detectShopCurrency();
  const results = await Promise.all(
    urls.map((url) =>
      fetchPrice(url, {
        ...opts,
        preferredCurrency: opts.preferredCurrency ?? sessionCurrency,
      }).then((info) => ({ url, info })),
    ),
  );
  for (const { url, info } of results) {
    if (info?.sku && Number.isFinite(info.price)) {
      map.set(info.sku, info);
      cacheSet(info.sku, info);
      cacheSetUrl(url, info);
    } else if (info?.error) {
      map.set(url, info);
    }
  }
  return map;
}

/**
 * @param {Map<string, any>|Record<string, any>} prices
 */
function toEstimatePriceMap(prices) {
  const out = {};
  const entries = prices instanceof Map ? prices.entries() : Object.entries(prices || {});
  for (const [key, info] of entries) {
    if (!info || info.error || !Number.isFinite(info.price)) continue;
    const sku = info.sku || key;
    out[sku] = {
      amount: info.price,
      currency: info.currency || "EUR",
      currencyAmbiguous: !!info.currencyAmbiguous,
      available: info.available !== false,
    };
  }
  return out;
}

HM.detectVisiblePrice = detectVisiblePrice;
HM.detectCurrencyFromHtml = detectCurrencyFromHtml;
HM.parseProductLdJson = parseProductLdJson;
HM.detectShopCurrency = detectShopCurrency;
HM.fetchPrice = fetchPrice;
HM.fetchPrices = fetchPrices;
HM.toEstimatePriceMap = toEstimatePriceMap;

// ===== cart.js =====
/**
 * Sequential Odoo Online cart add (one sale.order — no parallel writes).
 */

/**
 * @param {object} line
 * @param {{ fetchImpl?: typeof fetch, csrfToken?: string }} [opts]
 */
async function addCartLine(line, opts = {}) {
  const fetchImpl = opts.fetchImpl || fetch;
  const csrf =
    opts.csrfToken ||
    (typeof window !== "undefined" && window.odoo && window.odoo.csrf_token) ||
    "";
  const res = await fetchImpl("/shop/cart/add", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    credentials: "same-origin",
    body: JSON.stringify({
      jsonrpc: "2.0",
      method: "call",
      params: {
        product_template_id: line.tmpl_id,
        product_id: line.product_id,
        quantity: line.qty,
        csrf_token: csrf,
      },
    }),
  });
  if (!res.ok) {
    return { ok: false, line, error: `http_${res.status}` };
  }
  let body = null;
  try {
    body = await res.json();
  } catch {
    body = null;
  }
  if (body && body.error) {
    return { ok: false, line, error: body.error.message || "rpc_error", body };
  }
  return { ok: true, line, body };
}

/**
 * Add all HomeMaster cart_lines sequentially. Stops on first failure.
 * @param {Array<{tmpl_id:number, product_id:number, qty:number, sku:string}>} cartLines
 * @param {{ fetchImpl?: typeof fetch, csrfToken?: string }} [opts]
 * @returns {Promise<{ added: object[], failed: object|null }>}
 */
async function addAllToCart(cartLines, opts = {}) {
  const added = [];
  for (const line of cartLines || []) {
    const result = await addCartLine(line, opts);
    if (!result.ok) {
      return { added, failed: result };
    }
    added.push(result);
  }
  return { added, failed: null };
}

/**
 * @param {object} estimate
 * @returns {number}
 */
function cartLineCount(estimate) {
  return (estimate.cart_lines ?? []).reduce((s, l) => s + l.qty, 0);
}

/**
 * True when the shop line can be added and counted in the payable total.
 * @param {{amount?: number, available?: boolean}|null|undefined} p
 */
function priceIsCartEligible(p) {
  return !!(p && Number.isFinite(p.amount) && p.available !== false);
}

/**
 * HomeMaster module rows for the purchase list (not companions).
 * @param {object} estimate
 * @param {Record<string, {amount: number, currency: string, available?: boolean}>} prices
 * @returns {Array<{id: string, sku: string, qty: number, status: 'ok'|'oos'|'noprice', amount: number|null, currency: string|null}>}
 */
function modulePurchaseRows(estimate, prices) {
  const mods = estimate?.modules || [];
  return mods.map((m) => {
    const p = prices?.[m.sku];
    if (!p || !Number.isFinite(p.amount)) {
      return {
        id: m.id,
        sku: m.sku || "",
        qty: m.qty || 0,
        status: "noprice",
        amount: null,
        currency: null,
      };
    }
    if (p.available === false) {
      return {
        id: m.id,
        sku: m.sku || "",
        qty: m.qty || 0,
        status: "oos",
        amount: p.amount,
        currency: p.currency || "EUR",
      };
    }
    return {
      id: m.id,
      sku: m.sku || "",
      qty: m.qty || 0,
      status: "ok",
      amount: p.amount,
      currency: p.currency || "EUR",
    };
  });
}

/**
 * IN STOCK tile: priced+available SKUs over all module lines.
 * @param {ReturnType<typeof modulePurchaseRows>} rows
 */
function stockAvailability(rows) {
  const total = rows.length;
  const inStock = rows.filter((r) => r.status === "ok").length;
  return {
    inStock,
    total,
    allOk: total > 0 && inStock === total,
  };
}

/**
 * Cart lines that have a price and are available in the shop.
 * @param {object} estimate
 * @param {Record<string, {amount: number, currency: string, available?: boolean}>} prices
 */
function cartEligibleLines(estimate, prices) {
  return (estimate?.cart_lines || []).filter((line) =>
    priceIsCartEligible(prices?.[line.sku]),
  );
}

/**
 * Sum every HomeMaster line that has a numeric shop price (including out of stock).
 * @param {object} estimate
 * @param {Record<string, {amount: number, currency: string, currencyAmbiguous?: boolean, available?: boolean}>} prices
 * @returns {{total: number, currency: string, pricedQty: number, lineCount: number, unavailableQty: number, unavailableLineCount: number, currencyAmbiguous: boolean} | null}
 */
function systemTotal(estimate, prices) {
  let total = 0;
  let currency = null;
  let pricedQty = 0;
  let lineCount = 0;
  let unavailableQty = 0;
  let unavailableLineCount = 0;
  let currencyAmbiguous = false;
  const lines =
    (estimate.cart_lines && estimate.cart_lines.length
      ? estimate.cart_lines
      : (estimate.modules || []).map((m) => ({ sku: m.sku, qty: m.qty }))) || [];
  for (const line of lines) {
    const p = prices[line.sku];
    if (!p || !Number.isFinite(p.amount)) continue;
    const qty = line.qty || 1;
    total += p.amount * qty;
    currency = p.currency || currency || "EUR";
    pricedQty += qty;
    lineCount += 1;
    if (p.available === false) {
      unavailableQty += qty;
      unavailableLineCount += 1;
    }
    if (p.currencyAmbiguous) currencyAmbiguous = true;
  }
  if (lines.length === 0) return null;
  if (pricedQty === 0) return null;
  return {
    total: Math.round(total * 100) / 100,
    currency: currency || "EUR",
    pricedQty,
    lineCount,
    unavailableQty,
    unavailableLineCount,
    currencyAmbiguous,
  };
}

/**
 * Sum HomeMaster lines that have a numeric price and are available.
 * Missing / out-of-stock prices do not null the whole subtotal;
 * currencyAmbiguous never hides amounts.
 * @param {object} estimate
 * @param {Record<string, {amount: number, currency: string, currencyAmbiguous?: boolean, available?: boolean}>} prices
 * @returns {{total: number, currency: string, pricedQty: number, lineCount: number, missingSku: string[], unavailableSku: string[], currencyAmbiguous: boolean} | null}
 */
function cartTotal(estimate, prices) {
  let total = 0;
  let currency = null;
  let pricedQty = 0;
  let lineCount = 0;
  let currencyAmbiguous = false;
  const missingSku = [];
  const unavailableSku = [];
  const lines =
    (estimate.cart_lines && estimate.cart_lines.length
      ? estimate.cart_lines
      : (estimate.modules || []).map((m) => ({ sku: m.sku, qty: m.qty }))) || [];
  for (const line of lines) {
    const p = prices[line.sku];
    if (!p || !Number.isFinite(p.amount)) {
      if (line.sku) missingSku.push(line.sku);
      continue;
    }
    if (p.available === false) {
      if (line.sku) unavailableSku.push(line.sku);
      continue;
    }
    total += p.amount * (line.qty || 1);
    currency = p.currency || currency || "EUR";
    pricedQty += line.qty || 1;
    lineCount += 1;
    if (p.currencyAmbiguous) currencyAmbiguous = true;
  }
  if (lines.length === 0) return null;
  return {
    total: Math.round(total * 100) / 100,
    currency: currency || "EUR",
    pricedQty,
    lineCount,
    missingSku,
    unavailableSku,
    currencyAmbiguous,
  };
}

HM.addCartLine = addCartLine;
HM.addAllToCart = addAllToCart;
HM.cartLineCount = cartLineCount;
HM.priceIsCartEligible = priceIsCartEligible;
HM.modulePurchaseRows = modulePurchaseRows;
HM.stockAvailability = stockAvailability;
HM.cartEligibleLines = cartEligibleLines;
HM.systemTotal = systemTotal;
HM.cartTotal = cartTotal;

// ===== xlsx.js =====
/**
 * True .xlsx export via SheetJS (CDN). Formulas, not baked values.
 * SheetJS is loaded at runtime — not shipped in the public dist whitelist.
 */

const SHEETJS_CDN = "https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.mjs";

/** @type {Promise<any>|null} */
let xlsxPromise = null;

function loadXlsx() {
  if (!xlsxPromise) {
    xlsxPromise = import(SHEETJS_CDN);
  }
  return xlsxPromise;
}

/**
 * @param {object} estimate
 * @param {{ currency?: string }} [opts]
 * @returns {Promise<ArrayBuffer>}
 */
async function buildEstimateXlsx(estimate, opts = {}) {
  const XLSX = await loadXlsx();
  const currency = opts.currency || "EUR";
  const rows = [];

  rows.push(["HomeMaster estimate"]);
  rows.push([`Currency: ${currency}`]);
  rows.push(["Prices include VAT, same as the shopfront"]);
  rows.push([
    "Panel layout drawings are shown on the Result screen only — SheetJS CE cannot embed rail images in .xlsx.",
  ]);
  if (estimate.split_warning) rows.push([estimate.split_warning]);
  rows.push([]);
  rows.push(["Section", "SKU / requirement", "Qty", "Unit price", "Line total", "Availability"]);

  let r = rows.length + 1; // 1-based next data row

  function pushSection(title, lines) {
    rows.push([title, "", "", "", "", ""]);
    r += 1;
    const start = r;
    for (const line of lines) {
      const qty = line.qty ?? 1;
      const price = line.unit_price;
      const priceCell = price != null && price !== "" ? Number(price) : "";
      const avail =
        line.available === false ? "out of stock" : line.available === true ? "in stock" : "";
      rows.push([
        "",
        line.label || line.sku || line.requirement || "",
        qty,
        priceCell,
        { f: `C${r}*D${r}` },
        avail,
      ]);
      r += 1;
    }
    const end = r - 1;
    if (end >= start) {
      rows.push(["", `${title} subtotal`, "", "", { f: `SUM(E${start}:E${end})` }, ""]);
    } else {
      rows.push(["", `${title} subtotal`, "", "", 0, ""]);
    }
    r += 1;
    rows.push([]);
    r += 1;
    return r - 2;
  }

  const panels = estimate.panels || [];
  const subRows = [];

  if (panels.length > 0) {
    for (const panel of panels) {
      const hmLines = (panel.modules || []).map((m) => ({
        sku: m.sku,
        label: m.id,
        qty: m.qty,
        unit_price: m.price?.amount ?? m.unit_price ?? "",
        available: m.price?.available,
      }));
      const accLines = (panel.accessories || []).map((a) => ({
        label: a.label || a.id || "Accessory",
        qty: a.qty ?? 1,
        unit_price: "",
      }));
      const title = panel.location
        ? `${panel.name} (${panel.location})`
        : panel.name || "Panel";
      subRows.push(pushSection(title, [...hmLines, ...accLines]));
    }
  } else {
    const hmLines = (estimate.modules || []).map((m) => ({
      sku: m.sku,
      label: m.id,
      qty: m.qty,
      unit_price: m.price?.amount ?? m.unit_price ?? "",
      available: m.price?.available,
    }));
    subRows.push(pushSection("HomeMaster", hmLines));
  }

  const projectHm = (estimate.modules || []).map((m) => ({
    sku: m.sku,
    label: m.id,
    qty: m.qty,
    unit_price: m.price?.amount ?? m.unit_price ?? "",
    available: m.price?.available,
  }));
  const projectSub = pushSection("Project total (HomeMaster)", projectHm);

  rows.push([
    "Grand total (HomeMaster)",
    "",
    "",
    "",
    { f: `E${projectSub}` },
  ]);
  r += 1;
  rows.push([]);
  r += 1;

  const notInc = estimate.not_included || [];
  if (notInc.length) {
    rows.push(["Not included — to be specified by the electrical design"]);
    r += 1;
    for (const line of notInc) {
      rows.push(["", String(line)]);
      r += 1;
    }
  }

  const ws = XLSX.utils.aoa_to_sheet(rows);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Estimate");
  return XLSX.write(wb, { bookType: "xlsx", type: "array" });
}

/**
 * @param {object} estimate
 * @param {string} [filename]
 */
async function downloadXlsx(estimate, filename = "homemaster-estimate.xlsx") {
  const buf = await buildEstimateXlsx(estimate);
  const blob = new Blob([buf], {
    type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

/** CSV fallback when SheetJS CDN is blocked */
function estimateToCsv(estimate) {
  const rows = [["Panel", "Kind", "SKU", "Label", "Qty", "Unit price", "Currency"]];
  for (const panel of estimate.panels || []) {
    for (const m of panel.modules || []) {
      rows.push([
        panel.name,
        "module",
        m.sku ?? "",
        m.id ?? "",
        String(m.qty ?? ""),
        m.price?.amount != null ? String(m.price.amount) : "",
        m.price?.currency ?? "",
      ]);
    }
    for (const a of panel.accessories || []) {
      rows.push([
        panel.name,
        "companion",
        "",
        a.label || a.id || "",
        String(a.qty ?? ""),
        "",
        "",
      ]);
    }
  }
  if (!(estimate.panels || []).length) {
    for (const line of estimate.lines ?? []) {
      rows.push([
        "",
        line.kind ?? "",
        line.sku ?? "",
        line.label ?? "",
        String(line.qty ?? ""),
        line.unit_price != null ? String(line.unit_price) : "",
        line.currency ?? "",
      ]);
    }
  }
  return rows.map((r) => r.map(escapeCsv).join(",")).join("\n");
}

function escapeCsv(cell) {
  const s = String(cell);
  if (/[",\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
  return s;
}

function downloadCsv(estimate, filename = "homemaster-estimate.csv") {
  const csv = estimateToCsv(estimate);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

HM.buildEstimateXlsx = buildEstimateXlsx;
HM.downloadXlsx = downloadXlsx;
HM.estimateToCsv = estimateToCsv;
HM.downloadCsv = downloadCsv;

// ===== simple.js =====
/**
 * Simple-mode helpers: room-count → rooms[], weighted distribution, totals sync.
 * Pure — no DOM. Used by ui.js and unit tests.
 */

/** Room types shown as count sliders in Simple (utility → boiler_room). */
const SIMPLE_ROOM_TYPES = [
  { id: "bedroom", label: "Bedrooms" },
  { id: "bath", label: "Bathrooms" },
  { id: "living", label: "Living rooms" },
  { id: "kitchen", label: "Kitchen" },
  { id: "hallway", label: "Hallways" },
  { id: "office", label: "Office" },
  { id: "garage", label: "Garage" },
  { id: "boiler_room", label: "Utility" },
];

/** House totals distributed into rooms[] by template weights. */
const SIMPLE_DISTRIBUTE_FIELDS = [
  "lights_onoff",
  "lights_dimmable",
  "led_strips",
  "switches",
  "shutters",
  "ufh_loops",
  "leak_sensors",
  "motion_sensors",
  "door_contacts",
  "smart_sockets",
];

function defaultSimpleRoomCounts() {
  return {
    bedroom: 2,
    bath: 1,
    living: 1,
    kitchen: 1,
    hallway: 1,
    office: 0,
    garage: 0,
    boiler_room: 0,
  };
}

function defaultSimpleTotals() {
  return {
    lights_onoff: 8,
    lights_dimmable: 2,
    led_strips: 0,
    switches: 10,
    shutters: 0,
    ufh_loops: 0,
    leak_sensors: 2,
    motion_sensors: 1,
    door_contacts: 0,
    smart_sockets: 0,
  };
}

function defaultSimpleToggles() {
  return {
    boiler: "none",
    ventilation: false,
    energy_metering: false,
    security: false,
    garden_watering: false,
    gates: false,
  };
}

/**
 * Deterministic weighted distribution of `total` integer units across `n` slots.
 * weights[i] ≥ 0. Remainder goes to highest weight first, ties by lower index.
 * @returns {number[]}
 */
function distributeByWeights(total, weights) {
  const n = weights.length;
  const out = Array(n).fill(0);
  const T = Math.max(0, Math.floor(Number(total) || 0));
  if (n === 0 || T === 0) return out;

  const w = weights.map((x) => Math.max(0, Number(x) || 0));
  let W = w.reduce((s, x) => s + x, 0);
  if (W <= 0) {
    // Equal share when every weight is zero — still deterministic.
    const base = Math.floor(T / n);
    let rem = T - base * n;
    for (let i = 0; i < n; i++) out[i] = base;
    for (let i = 0; i < n && rem > 0; i++, rem--) out[i] += 1;
    return out;
  }

  let assigned = 0;
  for (let i = 0; i < n; i++) {
    out[i] = Math.floor((T * w[i]) / W);
    assigned += out[i];
  }
  let rem = T - assigned;
  const order = w
    .map((weight, index) => ({ weight, index }))
    .sort((a, b) => b.weight - a.weight || a.index - b.index);
  for (const { index } of order) {
    if (rem <= 0) break;
    out[index] += 1;
    rem -= 1;
  }
  return out;
}

/**
 * Build named rooms from Simple type counts. Always numbered (Bedroom 1, …).
 */
function buildRoomsFromCounts(counts, roomTypeLabels, roomDefaultsFn, panelId) {
  const rooms = [];
  for (const { id } of SIMPLE_ROOM_TYPES) {
    const n = Math.max(0, Math.floor(Number(counts[id]) || 0));
    const baseLabel = roomTypeLabels?.[id] || id;
    for (let i = 1; i <= n; i++) {
      const room = roomDefaultsFn(id);
      room.name = `${baseLabel} ${i}`;
      room.template = id;
      room.panel_id = panelId;
      room.manual = {};
      rooms.push(room);
    }
  }
  return rooms;
}

/**
 * Sum a numeric room field across rooms.
 */
function sumRoomField(rooms, field) {
  return (rooms || []).reduce((s, r) => s + (Math.max(0, Number(r[field]) || 0)), 0);
}

/**
 * Sync Simple slider totals from current rooms (Advanced → Simple).
 */
function totalsFromRooms(rooms) {
  const totals = defaultSimpleTotals();
  for (const field of SIMPLE_DISTRIBUTE_FIELDS) {
    totals[field] = sumRoomField(rooms, field);
  }
  return totals;
}

/**
 * Count rooms by template for Simple sliders.
 */
function countsFromRooms(rooms) {
  const counts = defaultSimpleRoomCounts();
  for (const k of Object.keys(counts)) counts[k] = 0;
  for (const r of rooms || []) {
    const t = r.template;
    if (t in counts) counts[t] += 1;
  }
  return counts;
}

/**
 * Distribute one field onto rooms, respecting manual locks.
 * @returns {{ rooms: object[], undistributed: number }}
 */
function distributeFieldToRooms(rooms, field, total, roomTemplates) {
  const next = (rooms || []).map((r) => ({
    ...r,
    manual: { ...(r.manual || {}) },
  }));
  const T = Math.max(0, Math.floor(Number(total) || 0));

  let lockedSum = 0;
  const editableIdx = [];
  for (let i = 0; i < next.length; i++) {
    if (next[i].manual?.[field]) {
      lockedSum += Math.max(0, Number(next[i][field]) || 0);
    } else {
      editableIdx.push(i);
    }
  }

  let pool = T - lockedSum;
  if (pool < 0) pool = 0;

  if (editableIdx.length === 0) {
    for (const i of editableIdx) next[i][field] = 0;
    return { rooms: next, undistributed: pool > 0 ? pool : Math.max(0, T - lockedSum) };
  }

  const weights = editableIdx.map((i) => {
    const tpl = roomTemplates?.[next[i].template] || {};
    return Math.max(0, Number(tpl[field]) || 0);
  });
  const shares = distributeByWeights(pool, weights);
  for (let k = 0; k < editableIdx.length; k++) {
    next[editableIdx[k]][field] = shares[k];
  }

  // Dimmable cannot exceed on/off lights in the same room.
  if (field === "lights_dimmable") {
    for (const room of next) {
      if (room.manual?.lights_dimmable) continue;
      const max = Math.max(0, Number(room.lights_onoff) || 0);
      room.lights_dimmable = Math.min(Math.max(0, Number(room.lights_dimmable) || 0), max);
    }
  }

  const sumEditable = editableIdx.reduce(
    (s, i) => s + (Math.max(0, Number(next[i][field]) || 0)),
    0,
  );
  const undistributed = Math.max(0, pool - sumEditable);
  return { rooms: next, undistributed };
}

/**
 * Apply all Simple totals onto rooms. Rebuilds room list when counts change.
 * Preserves manual values by matching (template, ordinal) when possible.
 * @returns {{ rooms: object[], warnings: string[] }}
 */
function applySimpleDistribution({
  counts,
  totals,
  rooms,
  roomTypeLabels,
  roomTemplates,
  roomDefaultsFn,
  panelId,
}) {
  const warnings = [];
  const desired = buildRoomsFromCounts(counts, roomTypeLabels, roomDefaultsFn, panelId);

  // Carry manual flags + values from previous rooms of same type/order.
  const prevByType = {};
  for (const r of rooms || []) {
    const t = r.template || "living";
    if (!prevByType[t]) prevByType[t] = [];
    prevByType[t].push(r);
  }
  for (const room of desired) {
    const bucket = prevByType[room.template] || [];
    const prev = bucket.shift();
    if (!prev) continue;
    room.manual = { ...(prev.manual || {}) };
    for (const field of SIMPLE_DISTRIBUTE_FIELDS) {
      if (room.manual[field]) {
        room[field] = prev[field];
      }
    }
    if (prev.panel_id) room.panel_id = prev.panel_id;
  }

  let current = desired;
  for (const field of SIMPLE_DISTRIBUTE_FIELDS) {
    const { rooms: next, undistributed } = distributeFieldToRooms(
      current,
      field,
      totals[field] ?? 0,
      roomTemplates,
    );
    current = next;
    if (undistributed > 0) {
      warnings.push(
        `${undistributed} units could not be distributed — edit rooms in Advanced mode`,
      );
    }
  }

  // Re-clamp dimmable after lights may have changed.
  const dim = distributeFieldToRooms(
    current,
    "lights_dimmable",
    totals.lights_dimmable ?? 0,
    roomTemplates,
  );
  current = dim.rooms;
  if (dim.undistributed > 0) {
    warnings.push(
      `${dim.undistributed} units could not be distributed — edit rooms in Advanced mode`,
    );
  }

  // One warning line per distinct count (avoid spam when several fields fail).
  const byCount = new Map();
  for (const w of warnings) {
    const m = w.match(/^(\d+) /);
    const n = m ? Number(m[1]) : 0;
    byCount.set(n, w);
  }
  return { rooms: current, warnings: [...byCount.values()] };
}

/**
 * Apply Simple system toggles onto systems object (mutates copy).
 */
function applySimpleToggles(systems, toggles) {
  const out = structuredClone(systems);
  out.heating = out.heating || {};
  out.ventilation = out.ventilation || {};
  out.water = out.water || {};
  out.electrical = out.electrical || {};
  out.security = out.security || {};

  const boiler = toggles.boiler || "none";
  out.heating.boiler = boiler === "opentherm" || boiler === "relay" ? boiler : "none";

  if (toggles.ventilation) {
    if (!(Number(out.ventilation.ahu) > 0) && !(Number(out.ventilation.recuperator) > 0)) {
      out.ventilation.recuperator = 1;
    }
  } else {
    out.ventilation.ahu = 0;
    out.ventilation.recuperator = 0;
  }

  out.electrical.energy_phases = toggles.energy_metering
    ? Math.max(3, Number(out.electrical.energy_phases) || 0)
    : 0;

  if (toggles.security) {
    if (!(Number(out.security.dry_contacts) > 0) && !(out.security.powered_sensors || []).length) {
      out.security.dry_contacts = 4;
    }
  } else {
    out.security.dry_contacts = 0;
    out.security.powered_sensors = [];
  }

  out.water.irrigation = toggles.garden_watering
    ? Math.max(1, Number(out.water.irrigation) || 0)
    : 0;

  out.security.gates = toggles.gates ? Math.max(1, Number(out.security.gates) || 0) : 0;

  // Collector loops from room ufh sum are handled by engine max(); mirror house total.
  return out;
}

/** Infer Simple toggles from systems (Advanced → Simple). */
function togglesFromSystems(systems) {
  const s = systems || {};
  const boiler = String(s.heating?.boiler || "none").toLowerCase();
  return {
    boiler: boiler === "opentherm" || boiler === "relay" ? boiler : "none",
    ventilation:
      (Number(s.ventilation?.ahu) || 0) > 0 || (Number(s.ventilation?.recuperator) || 0) > 0,
    energy_metering: (Number(s.electrical?.energy_phases) || 0) > 0,
    security:
      (Number(s.security?.dry_contacts) || 0) > 0 ||
      (s.security?.powered_sensors || []).length > 0,
    garden_watering: (Number(s.water?.irrigation) || 0) > 0,
    gates: (Number(s.security?.gates) || 0) > 0,
  };
}

/**
 * Blank room seed for Simple — only slider totals / toggles create demand.
 * Do not copy Advanced room_templates (extract_fan, DS18B20, …) into examples.
 */
function simpleRoomDefaults(type = "living") {
  return {
    name: "",
    template: type,
    lights_onoff: 0,
    lights_dimmable: 0,
    led_strips: 0,
    led_strip_channels: 4,
    led_single: 0,
    switches: 0,
    shutters: 0,
    ufh_loops: 0,
    ufh_electric: 0,
    lights_0_10v: 0,
    temp_sensor: "none",
    leak_sensors: 0,
    motion_sensors: 0,
    presence_sensors: 0,
    door_contacts: 0,
    smart_sockets: 0,
    extract_fan: 0,
  };
}

/**
 * Map unavailable shop modules → Simple preset fields to clear.
 * Used only for Apartment / House / Villa examples — not for manual sliders.
 *
 * @param {(moduleId: string) => boolean} isAvailable
 * @returns {{ preset: object, exclusions: string[], controllersOk: boolean }}
 */
function adaptPresetForAvailability(preset, isAvailable) {
  const p = structuredClone(preset);
  const exclusions = [];
  const avail = typeof isAvailable === "function" ? isAvailable : () => true;
  const note = (feature, sku) => {
    exclusions.push(`${feature} excluded — ${sku} currently unavailable.`);
  };

  if (!avail("DIM-420-R1") && (Number(p.totals?.lights_dimmable) || 0) > 0) {
    p.totals.lights_dimmable = 0;
    note("Dimming", "DIM-420-R1");
  }

  if (!avail("STR-3221-R1")) {
    // out_24v_ch + presence_in both allocate to STR-3221-R1.
    if ((Number(p.totals?.ufh_loops) || 0) > 0) {
      p.totals.ufh_loops = 0;
      note("Underfloor heating", "STR-3221-R1");
    }
    if ((Number(p.totals?.motion_sensors) || 0) > 0) {
      p.totals.motion_sensors = 0;
      note("Motion sensors", "STR-3221-R1");
    }
    // Stair / accent lighting also needs STR (or RGB for PWM); strip for stock examples.
    p.clearStairLighting = true;
  }

  if (!avail("RGB-621-R1") && (Number(p.totals?.led_strips) || 0) > 0) {
    p.totals.led_strips = 0;
    note("RGB strips", "RGB-621-R1");
  }

  if (!avail("WLD-521-R1") && (Number(p.totals?.leak_sensors) || 0) > 0) {
    p.totals.leak_sensors = 0;
    note("Leak detection", "WLD-521-R1");
  }

  if (!avail("ALM-173-R1") && p.toggles?.security) {
    p.toggles.security = false;
    note("Security zones", "ALM-173-R1");
  }

  if (!avail("ENM-223-R1") && p.toggles?.energy_metering) {
    p.toggles.energy_metering = false;
    note("Energy metering", "ENM-223-R1");
  }

  if (!avail("AIO-422-R1")) {
    // Presets do not set analog/RTD; clear if a caller added them.
    let cleared = false;
    if ((Number(p.totals?.sensors_0_10v) || 0) > 0) {
      p.totals.sensors_0_10v = 0;
      cleared = true;
    }
    if ((Number(p.totals?.rtd_sensors) || 0) > 0) {
      p.totals.rtd_sensors = 0;
      cleared = true;
    }
    if (cleared) note("Analog / RTD sensors", "AIO-422-R1");
  }

  const miniOk = avail("MiniPLC");
  const microOk = avail("MicroPLC");
  const controllersOk = miniOk || microOk;

  return { preset: p, exclusions, controllersOk, preferController: microOk && !miniOk ? "MicroPLC" : miniOk && !microOk ? "MiniPLC" : null };
}

