// ===== panel-layout.js =====
/**
 * Visual DIN-rail panel layout for the Result screen.
 * Packs modules + companions into enclosure rows/sections using
 * assets/panel/manifest.json for tile art.
 */

const SKIP_LAYOUT_IDS = new Set([
  "snubber_rc",
  "internal_wiring",
  "din_enclosure",
  "blanking_plate",
  "din_rail",
  "terminal_markers",
]);

/** @type {Promise<object>|null} */
let manifestPromise = null;

function panelAssetsBase() {
  const rulesUrl =
    (typeof globalThis !== "undefined" &&
      (globalThis.HM_ESTIMATOR_RULES_URL || globalThis.HM_RULES_URL)) ||
    "https://config.home-master.eu/estimator/rules.json";
  try {
    return new URL("./assets/panel/", rulesUrl.replace(/[^/]+$/, "")).href;
  } catch {
    return "https://config.home-master.eu/estimator/assets/panel/";
  }
}

function loadPanelManifest() {
  if (!manifestPromise) {
    const url = new URL("manifest.json", panelAssetsBase()).href;
    manifestPromise = fetch(url)
      .then((r) => {
        if (!r.ok) throw new Error(`panel manifest HTTP ${r.status}`);
        return r.json();
      })
      .catch((err) => {
        manifestPromise = null;
        throw err;
      });
  }
  return manifestPromise;
}

function escapeHtml(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function accIndex(accessories) {
  const map = new Map();
  for (const a of accessories || []) {
    if (!a?.id) continue;
    map.set(a.id, a);
  }
  return map;
}

function moduleIndex(modules) {
  const map = new Map();
  for (const m of modules || []) {
    if (!m?.id) continue;
    map.set(m.id, m);
  }
  return map;
}

/**
 * Expand a BOM line into individual placeable tiles (one per physical unit).
 * Fractional DIN (terminals) stays as one tile of that width — do not split.
 * rowBreakBefore applies only to the first copy.
 */
function pushCopies(out, base, qty) {
  const n = Math.max(0, Math.floor(Number(qty) || 0));
  for (let i = 0; i < n; i++) {
    out.push({
      ...base,
      instance: i,
      rowBreakBefore: i === 0 ? !!base.rowBreakBefore : false,
    });
  }
}

/**
 * Ordered queue matching real assembly (top → bottom):
 * HomeMaster modules (LED PS paired after each RGB/STR) →
 * module-logic PSU → protection (incomer + outgoing mixed) →
 * field terminals last (cables enter from below).
 */
function buildPlacementQueue(panel, rules = {}) {
  const specs = rules.modules ?? {};
  const accessories = panel.accessories || [];
  const acc = accIndex(accessories);
  const mods = moduleIndex(panel.modules);
  const items = [];

  function fromAcc(id, group) {
    const a = acc.get(id);
    if (!a || SKIP_LAYOUT_IDS.has(id)) return;
    const units = Number(a.din_units);
    if (!Number.isFinite(units) || units <= 0) return;
    pushCopies(
      items,
      {
        key: `companion:${id}`,
        id,
        kind: "companion",
        label: a.label || id,
        units,
        group,
        rowBreakBefore: false,
      },
      a.qty,
    );
  }

  function fromModuleLine(mod, group) {
    if (!mod) return;
    const units =
      mod.din_units != null
        ? Number(mod.din_units)
        : Number(specs[mod.id]?.din_units);
    if (!Number.isFinite(units) || units <= 0) return;
    items.push({
      key: `module:${mod.id}`,
      id: mod.id,
      kind: "module",
      label: mod.id,
      units,
      sku: mod.sku || specs[mod.id]?.sku || "",
      shop_url: mod.shop_url || specs[mod.id]?.shop_url || "",
      price: mod.price || null,
      group,
      rowBreakBefore: false,
    });
  }

  /** LED PS companions bound to a strip module — consumed as each module is placed. */
  const ledByModule = {
    "RGB-621-R1": [],
    "STR-3221-R1": [],
  };
  for (const a of accessories) {
    if (!a?.bind_module || !ledByModule[a.bind_module]) continue;
    const units = Number(a.din_units);
    if (!Number.isFinite(units) || units <= 0) continue;
    const copies = Math.max(1, Math.floor(Number(a.qty) || 1));
    for (let i = 0; i < copies; i++) {
      ledByModule[a.bind_module].push(a);
    }
  }

  function placeLedFor(modId, group) {
    const pool = ledByModule[modId];
    if (!pool?.length) return;
    const a = pool.shift();
    const units = Number(a.din_units);
    items.push({
      key: `companion:${a.id}:${a.bind_index ?? items.length}`,
      id: a.id,
      kind: "companion",
      label: a.label || a.id,
      units,
      group,
      rowBreakBefore: false,
      bind_module: a.bind_module,
      bind_index: a.bind_index,
    });
  }

  function placeModuleInstance(mod, group) {
    fromModuleLine(mod, group);
    if (mod?.id === "RGB-621-R1" || mod?.id === "STR-3221-R1") {
      placeLedFor(mod.id, group);
    }
  }

  // 1. Controllers & HomeMaster modules (LED PS immediately after each RGB/STR)
  //    Network gear (HA server, Ethernet switch) sits next to the controller.
  const segments = panel.topology?.segments || [];
  let networkPlaced = false;
  function placeNetworkGear(group) {
    if (networkPlaced) return;
    fromAcc("ha_server_din", group);
    fromAcc("eth_switch_din", group);
    networkPlaced = true;
  }

  if (segments.length) {
    for (let i = 0; i < segments.length; i++) {
      const seg = segments[i];
      const group = `segment-${i + 1}`;
      const ctrlId = seg.controller;
      const ctrlMod = mods.get(ctrlId) || {
        id: ctrlId,
        din_units: specs[ctrlId]?.din_units,
        sku: specs[ctrlId]?.sku,
        shop_url: specs[ctrlId]?.shop_url,
      };
      placeModuleInstance(ctrlMod, group);
      if (i === 0) placeNetworkGear(group);
      for (const slave of seg.slaves || []) {
        const sid = typeof slave === "string" ? slave : slave.id;
        const sMod = {
          id: sid,
          din_units:
            (typeof slave === "object" && slave.din_units) ||
            specs[sid]?.din_units,
          sku: (typeof slave === "object" && slave.sku) || specs[sid]?.sku,
          shop_url:
            (typeof slave === "object" && slave.shop_url) ||
            specs[sid]?.shop_url,
          price: mods.get(sid)?.price || null,
        };
        placeModuleInstance(sMod, group);
      }
    }
  } else {
    const masters = (panel.modules || []).filter((m) => specs[m.id]?.master);
    const slaves = (panel.modules || []).filter((m) => !specs[m.id]?.master);
    for (const m of masters) {
      for (let i = 0; i < (m.qty || 0); i++) {
        placeModuleInstance(m, "segment-1");
        placeNetworkGear("segment-1");
      }
    }
    placeNetworkGear("segment-1");
    for (const m of slaves) {
      for (let i = 0; i < (m.qty || 0); i++) {
        placeModuleInstance(m, "segment-1");
      }
    }
  }

  // Any LED PS left unbound (should not happen) — still place after modules.
  for (const pool of Object.values(ledByModule)) {
    while (pool.length) {
      const a = pool.shift();
      items.push({
        key: `companion:${a.id}:orphan:${items.length}`,
        id: a.id,
        kind: "companion",
        label: a.label || a.id,
        units: Number(a.din_units),
        group: "led-psu",
        rowBreakBefore: false,
      });
    }
  }

  // 2. Module-logic PSU — immediately after modules
  fromAcc("psu_din_60w", "logic-psu");
  fromAcc("psu_din_100w", "logic-psu");

  // 2b. 24 V logic distribution (fuses + V+/0V terminals) after logic PSU
  fromAcc("fuse_24v_branch", "logic-dist");
  fromAcc("terminal_24v", "logic-dist");

  // 3. Protection — incomer and outgoing may share a rail
  fromAcc("mcb_1p_n", "protection");
  fromAcc("rcd_2p", "protection");
  fromAcc("rcbo_1p_n", "protection");
  fromAcc("rcd_4p", "protection");
  fromAcc("mcb_1p", "protection");
  fromAcc("mcb_3p", "protection");
  fromAcc("contactor_modular", "protection");

  // 4. Field terminals and N/PE bars last (cables enter from below)
  fromAcc("terminal_block", "field");
  fromAcc("terminal_block_2t", "field");
  fromAcc("n_bar_12", "field");
  fromAcc("pe_bar_12", "field");

  return items;
}

function blankTile(units = 1) {
  return {
    key: "companion:blanking_plate",
    id: "blanking_plate",
    kind: "companion",
    label: "DIN blanking plate",
    units,
    group: "blank",
    rowBreakBefore: false,
  };
}

/**
 * Group placement queue into atomic chunks. A strip module and its LED PS
 * must stay on the same row — move both together when the pair does not fit.
 */
function placementChunks(items) {
  const chunks = [];
  for (let i = 0; i < (items || []).length; i++) {
    const cur = items[i];
    const nxt = items[i + 1];
    const paired =
      nxt &&
      ((cur.id === "RGB-621-R1" && nxt.id === "psu_led_rgb") ||
        (cur.id === "STR-3221-R1" && nxt.id === "psu_led_str"));
    if (paired) {
      const u0 = Number(cur.units) || 0;
      const u1 = Number(nxt.units) || 0;
      chunks.push({ items: [cur, nxt], units: u0 + u1 });
      i += 1;
    } else {
      chunks.push({ items: [cur], units: Number(cur.units) || 0 });
    }
  }
  return chunks;
}

/**
 * Pack items into enclosure.cabinets × rows × row_width.
 * Fill the current row until the next chunk does not fit, then start a new
 * row. Blanking only fills the remainder after a wrap or at the end.
 * Module + LED PS pairs never split across rows.
 */
function packEnclosureLayout(items, enclosure) {
  const cabinets = Math.max(1, Number(enclosure?.cabinets) || 1);
  const rowsPer = Math.max(1, Number(enclosure?.rows) || 1);
  const rowWidth = Math.max(1, Number(enclosure?.row_width) || 24);
  const eps = 1e-6;

  const sections = Array.from({ length: cabinets }, (_, i) => ({
    index: i + 1,
    rows: [],
  }));

  let secIdx = 0;
  let rowItems = [];
  let used = 0;

  function rowLabel(list) {
    const real = list.filter((t) => t.id !== "blanking_plate");
    if (!real.length) return "Blanking";
    const groups = new Set(real.map((t) => t.group));
    const seg = [...groups].find((g) => String(g).startsWith("segment-"));
    if (seg) {
      const n = seg.split("-")[1];
      const inSeg = real.filter((t) => t.group === seg);
      const modules = inSeg.filter((t) => t.kind === "module");
      const led = inSeg.filter(
        (t) => t.id === "psu_led_rgb" || t.id === "psu_led_str",
      );
      const head = modules[0]?.id || "controller";
      const extraMods = Math.max(0, modules.length - 1);
      const ledNote = led.length
        ? ` + ${led.length} LED PS`
        : "";
      const extraGroups = [...groups].filter(
        (g) => g !== seg && g !== "blank",
      );
      const otherSegs = extraGroups
        .filter((g) => String(g).startsWith("segment-"))
        .map((g) => g.split("-")[1]);
      const nonSeg = extraGroups.filter((g) => !String(g).startsWith("segment-"));
      const segMix = otherSegs.length
        ? ` + segment ${otherSegs.join(" + segment ")}`
        : "";
      const mix =
        nonSeg.length > 0
          ? ` · ${nonSeg
              .map((g) =>
                g === "logic-psu"
                  ? "logic PSU"
                  : g === "logic-dist"
                    ? "24 V distribution"
                    : g === "protection"
                      ? "protection"
                      : g === "field"
                        ? "terminals"
                        : g,
              )
              .join(", ")}`
          : "";
      return `Modules — segment ${n}${segMix} (${head}${extraMods ? ` + ${extraMods}` : ""}${ledNote})${mix}`;
    }
    if (groups.has("logic-psu") || groups.has("power")) {
      return "Module logic PSU";
    }
    if (groups.has("logic-dist")) return "24 V logic distribution";
    if (groups.has("led-psu")) return "LED PS (strip / actuator supply)";
    if (groups.has("protection") || groups.has("incomer")) {
      return "Protection";
    }
    if (groups.has("field")) return "Field terminals & bars";
    return real
      .map((t) => t.label || t.id)
      .slice(0, 3)
      .join(", ");
  }

  function commitRow() {
    if (!rowItems.length && used === 0) return;
    ensureCapacity();
    const remain = rowWidth - used;
    if (remain > eps) {
      let left = remain;
      while (left > 1 + eps) {
        rowItems.push(blankTile(1));
        left -= 1;
      }
      if (left > eps) rowItems.push(blankTile(Math.round(left * 100) / 100));
    }
    const sec = sections[secIdx];
    sec.rows.push({
      items: rowItems,
      label: rowLabel(rowItems),
      used: rowWidth,
    });
    rowItems = [];
    used = 0;
    if (sec.rows.length >= rowsPer) {
      secIdx += 1;
    }
  }

  function ensureCapacity() {
    while (secIdx >= sections.length) {
      sections.push({ index: sections.length + 1, rows: [] });
    }
  }

  function ensureSlot(units) {
    ensureCapacity();
    if (units > rowWidth + eps) {
      if (rowItems.length) commitRow();
      ensureCapacity();
      return;
    }
    if (used + units > rowWidth + eps) {
      commitRow();
      ensureCapacity();
    }
  }

  for (const chunk of placementChunks(items)) {
    const units = Number(chunk.units) || 0;
    if (units <= 0) continue;
    ensureSlot(units);
    for (const item of chunk.items) {
      rowItems.push(item);
      used += Number(item.units) || 0;
    }
  }

  if (rowItems.length) commitRow();

  // Do not pad unused enclosure capacity with blank-only rows/sections.
  // Free DIN belongs on the last occupied row only; rated size stays in summary.
  const usedSections = sections.filter((s) => s.rows.length > 0);
  const visualCabinets = Math.max(1, usedSections.length);
  const visualRows = Math.max(
    1,
    ...(usedSections.length ? usedSections.map((s) => s.rows.length) : [1]),
  );

  return {
    cabinets: visualCabinets,
    rows: visualRows,
    row_width: rowWidth,
    capacity: cabinets * rowsPer * rowWidth,
    sections: usedSections.length ? usedSections : sections.slice(0, 1),
    summary: {
      occupied: enclosure?.din_occupied ?? enclosure?.occupied ?? null,
      free: enclosure?.din_free ?? enclosure?.free ?? null,
      reserve: enclosure?.din_reserve ?? enclosure?.reserve ?? null,
      width_mm: enclosure?.width_mm ?? null,
      height_mm: enclosure?.height_mm ?? null,
      capacity_each: enclosure?.capacity_each ?? rowsPer * rowWidth,
      rated_cabinets: cabinets,
      rated_rows: rowsPer,
    },
  };
}

function buildPanelLayout(panel, rules = {}) {
  const enc = panel?.enclosure;
  if (!enc || enc.status === "blocked" || enc.status === "overflow" || enc.overflow) {
    return null;
  }
  const queue = buildPlacementQueue(panel, rules);
  return packEnclosureLayout(queue, enc);
}

function resolveTileSrc(manifest, item, assetsBase) {
  if (!manifest) return { src: null, missing: true, artUnits: null, noStretch: false };
  if (item.kind === "module") {
    const bySku = item.sku ? manifest.modules?.[item.sku] : null;
    if (bySku?.file) {
      return {
        src: new URL(bySku.file, assetsBase).href,
        missing: false,
        artUnits: bySku.art_units ?? bySku.units ?? null,
        noStretch: !!bySku.no_stretch,
      };
    }
    return { src: null, missing: true, artUnits: null, noStretch: false };
  }
  const entry = manifest.companions?.[item.id];
  if (entry?.file) {
    return {
      src: new URL(entry.file, assetsBase).href,
      missing: false,
      artUnits: entry.art_units ?? entry.units ?? null,
      noStretch: !!entry.no_stretch,
    };
  }
  return { src: null, missing: true, artUnits: null, noStretch: false };
}

function tileTooltip(item, priceMap) {
  const bits = [item.label || item.id, `${item.units} M`];
  if (item.kind === "module") {
    const p =
      item.price ||
      (item.sku && priceMap?.[item.sku]) ||
      null;
    if (p && typeof p.amount === "number") {
      bits.push(`${p.amount} ${p.currency || ""}`.trim());
    }
    if (item.shop_url) bits.push(item.shop_url);
  }
  return bits.filter(Boolean).join(" · ");
}

/**
 * One physical unit → one <img> from the manifest. Never collapse runs;
 * never replace art with a coloured label block.
 */
function renderTile(item, manifest, assetsBase, rowWidth, priceMap) {
  const units = Number(item.units) || 0;
  const tip = escapeHtml(tileTooltip(item, priceMap));
  const hl = escapeHtml(item.key);
  const { src, missing, artUnits, noStretch } = resolveTileSrc(
    manifest,
    item,
    assetsBase,
  );
  const tab = ` tabindex="0" role="button"`;
  const flex = `flex:0 0 calc(100% * ${units} / ${rowWidth});width:calc(100% * ${units} / ${rowWidth});height:100%;`;
  // Do not stretch artwork that is narrower than the DIN slot (e.g. 4 M
  // PSU face in a 6 M logic-PSU / LED-PS slot) — text would duplicate.
  const stretch =
    !noStretch &&
    !(artUnits != null && Number(artUnits) + 1e-6 < units);
  const fit = stretch ? "fill" : "contain";
  // Keep narrower art flush against the previous module (LED PS / logic PSU).
  const pos = stretch ? "center" : "left center";

  if (missing || !src) {
    return `<span class="hm-rail-tile hm-rail-tile--missing" data-hl="${hl}" title="${tip}"${tab} style="${flex}"></span>`;
  }

  const shop =
    item.kind === "module" && item.shop_url
      ? ` data-shop="${escapeHtml(item.shop_url)}"`
      : "";
  return `<img class="hm-rail-tile${stretch ? "" : " hm-rail-tile--contain"}" data-hl="${hl}"${shop} src="${escapeHtml(src)}" alt="${escapeHtml(item.label || item.id)}" title="${tip}" loading="lazy" decoding="async"${tab} style="${flex};object-fit:${fit};object-position:${pos};background:transparent">`;
}

/**
 * @returns {string} HTML
 */
function renderPanelLayoutHtml(layout, manifest, opts = {}) {
  if (!layout) return "";
  const assetsBase = opts.assetsBase || panelAssetsBase();
  const srcUnit = Number(manifest?.unit_px) || 70;
  const srcHeight = Number(manifest?.height_px) || 360;
  const rowWidth = Number(layout.row_width) || 24;
  const rowAspect = (rowWidth * srcUnit) / srcHeight;
  const priceMap = opts.priceMap || {};
  const railFile = manifest?.rail?.file || "rail-empty.svg";
  const railUrl = new URL(railFile, assetsBase).href;

  const occ = layout.summary.occupied;
  const free = layout.summary.free;
  const wmm = layout.summary.width_mm;
  const hmm = layout.summary.height_mm;
  const each = layout.summary.capacity_each;
  const cab = layout.cabinets;
  const layoutBits =
    cab > 1
      ? `${cab} × (${layout.rows} rows × ${layout.row_width}) = ${layout.capacity} modules`
      : `${layout.rows} rows × ${layout.row_width} = ${each} modules`;
  const dinBits = [
    occ != null ? `occupied ${occ}` : null,
    free != null ? `free ${free}` : null,
  ]
    .filter(Boolean)
    .join(" · ");
  const mmBits =
    wmm != null && hmm != null ? `approx. ${wmm} × ${hmm} mm` : null;
  const headline = [layoutBits, dinBits, mmBits].filter(Boolean).join(" · ");

  function sectionSummary(sec) {
    const items = sec.rows.flatMap((r) => r.items);
    const mods = items.filter((t) => t.kind === "module").length;
    const blank = items
      .filter((t) => t.id === "blanking_plate")
      .reduce((s, t) => s + (Number(t.units) || 0), 0);
    const bits = [];
    if (mods) bits.push(`${mods} module${mods === 1 ? "" : "s"}`);
    if (blank > 0) bits.push(`${Math.round(blank * 100) / 100} M free`);
    bits.push(`${sec.rows.length} rail${sec.rows.length === 1 ? "" : "s"}`);
    return bits.join(" · ");
  }

  const sectionsHtml = layout.sections
    .map((sec, idx) => {
      const open = idx === 0;
      const railsLabel = `DIN rail ${sec.rows.length === 1 ? "1" : `1–${sec.rows.length}`}`;
      const rowsHtml = sec.rows
        .map((row) => {
          const tiles = row.items
            .map((it) => renderTile(it, manifest, assetsBase, rowWidth, priceMap))
            .join("");
          return `<div class="hm-rail-row-wrap">
            <div class="hm-rail-row-shell">
              <span class="hm-rail-end hm-rail-end--left" aria-hidden="true"></span>
              <div class="hm-rail-row" style="--row-units:${rowWidth};aspect-ratio:${rowAspect};background-image:url('${escapeHtml(railUrl)}');background-size:calc(100% / ${rowWidth}) 100%;background-repeat:repeat-x;">${tiles}</div>
              <span class="hm-rail-end hm-rail-end--right" aria-hidden="true"></span>
            </div>
            <div class="hm-rail-row__label">${escapeHtml(row.label)}</div>
          </div>`;
        })
        .join("");
      return `<div class="hm-rail-section${open ? "" : " is-collapsed"}" data-section="${sec.index}">
        <button type="button" class="hm-rail-section__toggle" data-rail-toggle aria-expanded="${open ? "true" : "false"}">
          <span>
            <strong>Section ${sec.index}</strong>
            <span class="hm-rail-section__meta">${escapeHtml(railsLabel)} · ${escapeHtml(sectionSummary(sec))}</span>
          </span>
        </button>
        <div class="hm-rail-section__body">${rowsHtml}</div>
      </div>`;
    })
    .join("");

  const multi = layout.sections.length > 1;
  const toolbar = `<div class="hm-rail-block__toolbar">
    <h4>Panel layout</h4>
    ${
      multi
        ? `<button type="button" class="hm-linkish" data-rail-expand-all>Expand all sections</button>`
        : ""
    }
  </div>`;

  const legend = `<ul class="hm-rail-legend" aria-label="Layout legend">
    <li><span class="hm-rail-legend__swatch hm-rail-legend__swatch--mod" aria-hidden="true"></span>Module</li>
    <li><span class="hm-rail-legend__swatch hm-rail-legend__swatch--psu" aria-hidden="true"></span>PSU</li>
    <li><span class="hm-rail-legend__swatch hm-rail-legend__swatch--prot" aria-hidden="true"></span>Protection</li>
    <li><span class="hm-rail-legend__swatch hm-rail-legend__swatch--term" aria-hidden="true"></span>Terminals</li>
    <li><span class="hm-rail-legend__swatch hm-rail-legend__swatch--blank" aria-hidden="true"></span>Blanking</li>
  </ul>`;

  return `<div class="hm-rail-layout">
    ${toolbar}
    <p class="hm-rail-layout__summary">${escapeHtml(headline)}</p>
    <div class="hm-rail-layout__sections">${sectionsHtml}</div>
    ${legend}
  </div>`;
}

/** Bind hover/click/focus cross-highlight between BOM table rows and rail tiles. */
function bindLayoutHighlight(root) {
  if (!root) return;
  let locked = null;
  const clear = () => {
    root.querySelectorAll("[data-hl].is-hl").forEach((el) => el.classList.remove("is-hl"));
  };
  const sync = (key, on) => {
    if (!key) return;
    root.querySelectorAll("[data-hl]").forEach((el) => {
      if (el.getAttribute("data-hl") === key) el.classList.toggle("is-hl", on);
    });
  };
  root.querySelectorAll("[data-hl]").forEach((el) => {
    const key = () => el.getAttribute("data-hl");
    el.addEventListener("mouseenter", () => {
      if (locked) return;
      sync(key(), true);
    });
    el.addEventListener("mouseleave", () => {
      if (locked) return;
      sync(key(), false);
    });
    el.addEventListener("focus", () => {
      if (locked && locked !== key()) {
        clear();
        locked = null;
      }
      sync(key(), true);
    });
    el.addEventListener("blur", () => {
      if (locked) return;
      sync(key(), false);
    });
    el.addEventListener("click", (ev) => {
      const k = key();
      if (!k) return;
      if (el.tagName === "A") return;
      ev.preventDefault();
      if (locked === k) {
        clear();
        locked = null;
        return;
      }
      clear();
      locked = k;
      sync(k, true);
    });
    el.addEventListener("keydown", (ev) => {
      if (ev.key !== "Enter" && ev.key !== " ") return;
      ev.preventDefault();
      el.click();
    });
  });

  root.querySelectorAll("[data-rail-toggle]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const sec = btn.closest(".hm-rail-section");
      if (!sec) return;
      const open = sec.classList.toggle("is-collapsed");
      btn.setAttribute("aria-expanded", open ? "false" : "true");
    });
  });
  const expandAll = root.querySelector("[data-rail-expand-all]");
  if (expandAll) {
    expandAll.addEventListener("click", () => {
      const collapsed = [...root.querySelectorAll(".hm-rail-section.is-collapsed")];
      if (collapsed.length) {
        collapsed.forEach((sec) => {
          sec.classList.remove("is-collapsed");
          const t = sec.querySelector("[data-rail-toggle]");
          if (t) t.setAttribute("aria-expanded", "true");
        });
        expandAll.textContent = "Collapse sections";
      } else {
        root.querySelectorAll(".hm-rail-section").forEach((sec, i) => {
          if (i === 0) return;
          sec.classList.add("is-collapsed");
          const t = sec.querySelector("[data-rail-toggle]");
          if (t) t.setAttribute("aria-expanded", "false");
        });
        expandAll.textContent = "Expand all sections";
      }
    });
  }
}

/**
 * Build a layout model for every panel that has an enclosure.
 * Used by Result UI (and tests).
 */
function layoutsForEstimate(estimate, rules) {
  return (estimate?.panels || []).map((p) => ({
    panel: p,
    layout: buildPanelLayout(p, rules),
  }));
}

HM.loadPanelManifest = loadPanelManifest;
HM.buildPlacementQueue = buildPlacementQueue;
HM.placementChunks = placementChunks;
HM.packEnclosureLayout = packEnclosureLayout;
HM.buildPanelLayout = buildPanelLayout;
HM.renderPanelLayoutHtml = renderPanelLayoutHtml;
HM.bindLayoutHighlight = bindLayoutHighlight;
HM.layoutsForEstimate = layoutsForEstimate;

// ===== share.js =====
/**
 * Compact shareable configuration links: ?c=<base64url>.
 * Schema versioned; prices never embedded (re-fetched on open).
 */

/** Bump when field layout / meaning changes incompatibly. */
const SHARE_SCHEMA_VERSION = 1;

const PTYPE = ["apartment", "house", "townhouse", "commercial"];
const STAGE = ["design", "construction", "renovation", "existing"];
const BOILER = ["none", "opentherm", "relay"];
const HA = ["needed", "own"];
const TEMP = ["none", "DS18B20", "PT100", "PT1000"];

/** Room numeric/select fields → 1–2 letter keys (omit zeros / defaults). */
const ROOM_KEYS = [
  ["lo", "lights_onoff", 0],
  ["ld", "lights_dimmable", 0],
  ["ls", "led_strips", 0],
  ["lc", "led_strip_channels", 4],
  ["l1", "led_single", 0],
  ["sw", "switches", 0],
  ["sh", "shutters", 0],
  ["uf", "ufh_loops", 0],
  ["ue", "ufh_electric", 0],
  ["l0", "lights_0_10v", 0],
  ["ts", "temp_sensor", "none"],
  ["lk", "leak_sensors", 0],
  ["mo", "motion_sensors", 0],
  ["pr", "presence_sensors", 0],
  ["dc", "door_contacts", 0],
  ["ss", "smart_sockets", 0],
  ["ef", "extract_fan", 0],
];

const SYS_SECTIONS = {
  h: "heating",
  v: "ventilation",
  w: "water",
  e: "electrical",
  s: "security",
  l: "lighting_scenes",
};

const HEATING_KEYS = [
  ["b", "boiler", "none"],
  ["c", "collector_loops", 0],
  ["p", "heating_pumps", 0],
  ["f", "fan_coils", 0],
  ["hp", "heat_pump", 0],
  ["fp", "fireplace", 0],
  ["pt", "pt100_sensors", 0],
  ["ds", "ds18b20_sensors", 0],
];
const VENT_KEYS = [
  ["a", "ahu", 0],
  ["r", "recuperator", 0],
  ["x", "extract_fans", 0],
  ["d", "dampers_0_10v", 0],
  ["s0", "sensors_0_10v", 0],
  ["s4", "sensors_4_20ma", 0],
];
const WATER_KEYS = [
  ["lz", "leak_zones", 0],
  ["sv", "shutoff_valves", 0],
  ["wm", "water_meters", 0],
  ["ir", "irrigation", 0],
  ["wp", "water_pumps", 0],
  ["dh", "dhw_recirc", 0],
  ["gv", "gas_valve", 0],
];
const ELEC_KEYS = [
  ["ep", "energy_phases", 0],
  ["ls", "load_shed", 0],
  ["ev", "ev_chargers", 0],
  ["pv", "pv_inverters", 0],
  ["fc", "fault_contacts", 0],
];
const SEC_KEYS = [
  ["dc", "dry_contacts", 0],
  ["g", "gates", 0],
  ["lk", "locks", 0],
  ["pb", "panic_buttons", 0],
];
const LIGHT_KEYS = [
  ["st", "stair_steps", 0],
  ["az", "accent_zones", 0],
  ["gl", "garden_lights", 0],
];

const SECTION_KEYS = {
  heating: HEATING_KEYS,
  ventilation: VENT_KEYS,
  water: WATER_KEYS,
  electrical: ELEC_KEYS,
  security: SEC_KEYS,
  lighting_scenes: LIGHT_KEYS,
};

function idxOf(list, val, fallback = 0) {
  const i = list.indexOf(val);
  return i >= 0 ? i : fallback;
}

function fromIdx(list, i, fallback) {
  return list[i] ?? fallback;
}

function packSparse(obj, keys) {
  const out = {};
  for (const [short, long, def] of keys) {
    const v = obj?.[long];
    if (v == null || v === def) continue;
    if (typeof def === "number" && !(Number(v) > 0) && Number(def) === 0) continue;
    out[short] = typeof def === "number" ? Number(v) || 0 : v;
  }
  return Object.keys(out).length ? out : null;
}

function unpackSparse(packed, keys, target) {
  if (!packed || typeof packed !== "object") return target;
  for (const [short, long, def] of keys) {
    if (Object.prototype.hasOwnProperty.call(packed, short)) {
      target[long] = typeof def === "number" ? Number(packed[short]) || 0 : packed[short];
    }
  }
  return target;
}

function bytesToBase64Url(bytes) {
  let bin = "";
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  const b64 =
    typeof btoa === "function"
      ? btoa(bin)
      : Buffer.from(bytes).toString("base64");
  return b64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function base64UrlToBytes(s) {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4);
  if (typeof atob === "function") {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  return new Uint8Array(Buffer.from(b64, "base64"));
}

function utf8Encode(str) {
  if (typeof TextEncoder !== "undefined") return new TextEncoder().encode(str);
  return Buffer.from(str, "utf8");
}

function utf8Decode(bytes) {
  if (typeof TextDecoder !== "undefined") return new TextDecoder().decode(bytes);
  return Buffer.from(bytes).toString("utf8");
}

/**
 * Build a minimal share payload from live configurator state.
 * @param {object} state
 */
function buildSharePayload(state) {
  const panels = Array.isArray(state.panels) && state.panels.length
    ? state.panels
    : [{ id: "panel-1", name: "Main panel", location: "" }];
  const panelIds = panels.map((p) => p.id);

  const payload = { v: SHARE_SCHEMA_VERSION };

  if (state.ui_mode === "simple") payload.m = "s";
  if (state.expert) payload.x = 1;

  const o = state.object || {};
  const oPacked = [];
  oPacked.push(idxOf(PTYPE, o.property_type, 0));
  oPacked.push(Number(o.floor_area_m2) || 0);
  oPacked.push(Number(o.floors) || 1);
  oPacked.push(idxOf(STAGE, o.stage, 0));
  if (o.name) oPacked.push(String(o.name));
  payload.o = oPacked;

  const needPanels =
    panels.length !== 1 ||
    panels[0].id !== "panel-1" ||
    (panels[0].name && panels[0].name !== "Main panel") ||
    panels[0].location;
  if (needPanels) {
    payload.p = panels.map((p) => {
      const row = [p.id || "panel-1"];
      if (p.name && p.name !== "Main panel") row.push(p.name);
      else row.push("");
      if (p.location) row.push(p.location);
      return row;
    });
  }

  if (!state.expert) {
    const rooms = Array.isArray(state.rooms) ? state.rooms.filter((r) => r?.name?.trim()) : [];
    payload.r = rooms.map((r) => {
      const pIdx = Math.max(0, panelIds.indexOf(r.panel_id || panelIds[0]));
      const sparse = {};
      for (const [short, long, def] of ROOM_KEYS) {
        let v = r[long];
        if (long === "temp_sensor") {
          if (!v || v === def) continue;
          sparse[short] = idxOf(TEMP, v, 0);
          continue;
        }
        if (long === "led_strip_channels") {
          const n = Number(v) || 4;
          if (n === 4) continue;
          sparse[short] = n;
          continue;
        }
        const n = Number(v) || 0;
        if (n === def || n === 0) continue;
        sparse[short] = n;
      }
      if (r.manual && typeof r.manual === "object" && Object.keys(r.manual).length) {
        sparse.m = 1;
      }
      const row = [r.template || "living", r.name.trim(), pIdx];
      if (Object.keys(sparse).length) row.push(sparse);
      return row;
    });

    const y = {};
    for (const [short, long] of Object.entries(SYS_SECTIONS)) {
      const sec = state.systems?.[long] || {};
      const keys = SECTION_KEYS[long];
      const packed = packSparse(sec, keys);
      const out = packed ? { ...packed } : {};
      if (long === "heating" && sec.boiler && sec.boiler !== "none") {
        out.b = idxOf(BOILER, sec.boiler, 0);
      }
      if (long === "security" && Array.isArray(sec.powered_sensors) && sec.powered_sensors.length) {
        out.ps = sec.powered_sensors
          .filter((row) => (Number(row.qty) || 0) > 0)
          .map((row) => [row.type || "pir", Number(row.qty) || 0]);
        if (!out.ps.length) delete out.ps;
      }
      const pIdx = Math.max(0, panelIds.indexOf(sec.panel_id || panelIds[0]));
      if (pIdx > 0) out.pi = pIdx;
      if (Object.keys(out).length) y[short] = out;
    }
    const sys = state.systems?.system || {};
    const g = {};
    if (sys.manual_control === false) g.m = 0;
    if (sys.ha_server && sys.ha_server !== "needed") g.h = idxOf(HA, sys.ha_server, 0);
    if (Object.keys(g).length) y.g = g;
    if (Object.keys(y).length) payload.y = y;
  } else if (state.expertDemand && typeof state.expertDemand === "object") {
    payload.d = state.expertDemand;
  }

  return payload;
}

/**
 * @param {object} payload
 * @returns {{ patch: object, older: boolean, ok: boolean, error?: string }}
 */
function expandSharePayload(payload) {
  if (!payload || typeof payload !== "object") {
    return { patch: null, older: false, ok: false, error: "empty" };
  }
  const ver = Number(payload.v) || 0;
  const older = ver > 0 && ver < SHARE_SCHEMA_VERSION;
  const newer = ver > SHARE_SCHEMA_VERSION;
  // Newer schema: still try known keys; flag as older-message (settings may differ).
  const warn = older || newer || ver === 0;

  const panels = Array.isArray(payload.p) && payload.p.length
    ? payload.p.map((row, i) => ({
        id: String(row[0] || `panel-${i + 1}`),
        name: String(row[1] || (i === 0 ? "Main panel" : `Panel ${i + 1}`)),
        location: String(row[2] || ""),
      }))
    : [{ id: "panel-1", name: "Main panel", location: "" }];
  const panelIds = panels.map((p) => p.id);
  const mainId = panelIds[0];

  const oIn = Array.isArray(payload.o) ? payload.o : [];
  const object = {
    name: oIn[4] != null ? String(oIn[4]) : "",
    property_type: fromIdx(PTYPE, Number(oIn[0]) || 0, "apartment"),
    floor_area_m2: Number(oIn[1]) || 60,
    floors: Math.max(1, Number(oIn[2]) || 1),
    stage: fromIdx(STAGE, Number(oIn[3]) || 0, "design"),
  };

  const expert = !!payload.x;
  let rooms = [];
  let systems = {
    heating: {
      panel_id: mainId,
      boiler: "none",
      collector_loops: 0,
      heating_pumps: 0,
      fan_coils: 0,
      heat_pump: 0,
      fireplace: 0,
      pt100_sensors: 0,
      ds18b20_sensors: 0,
    },
    ventilation: {
      panel_id: mainId,
      ahu: 0,
      recuperator: 0,
      extract_fans: 0,
      dampers_0_10v: 0,
      sensors_0_10v: 0,
      sensors_4_20ma: 0,
    },
    water: {
      panel_id: mainId,
      leak_zones: 0,
      shutoff_valves: 0,
      water_meters: 0,
      irrigation: 0,
      water_pumps: 0,
      dhw_recirc: 0,
      gas_valve: 0,
    },
    electrical: {
      panel_id: mainId,
      energy_phases: 0,
      load_shed: 0,
      ev_chargers: 0,
      pv_inverters: 0,
      fault_contacts: 0,
    },
    security: {
      panel_id: mainId,
      powered_sensors: [],
      dry_contacts: 0,
      gates: 0,
      locks: 0,
      panic_buttons: 0,
    },
    lighting_scenes: {
      panel_id: mainId,
      stair_steps: 0,
      accent_zones: 0,
      garden_lights: 0,
    },
    system: { manual_control: true, ha_server: "needed" },
  };

  if (!expert && Array.isArray(payload.r)) {
    rooms = payload.r.map((row) => {
      const template = String(row[0] || "living");
      const name = String(row[1] || "");
      const pIdx = Number(row[2]) || 0;
      const sparse = row[3] && typeof row[3] === "object" ? row[3] : {};
      const room = {
        template,
        name,
        panel_id: panelIds[pIdx] || mainId,
        lights_onoff: 0,
        lights_dimmable: 0,
        led_strips: 0,
        led_strip_channels: 4,
        led_single: 0,
        switches: 0,
        shutters: 0,
        ufh_loops: 0,
        ufh_electric: 0,
        lights_0_10v: 0,
        temp_sensor: "none",
        leak_sensors: 0,
        motion_sensors: 0,
        presence_sensors: 0,
        door_contacts: 0,
        smart_sockets: 0,
        extract_fan: 0,
        manual: sparse.m ? {} : {},
      };
      for (const [short, long, def] of ROOM_KEYS) {
        if (!Object.prototype.hasOwnProperty.call(sparse, short)) continue;
        if (long === "temp_sensor") {
          room.temp_sensor = fromIdx(TEMP, Number(sparse[short]) || 0, "none");
        } else {
          room[long] = typeof def === "number" ? Number(sparse[short]) || 0 : sparse[short];
        }
      }
      return room;
    });
  }

  if (!expert && payload.y && typeof payload.y === "object") {
    for (const [short, long] of Object.entries(SYS_SECTIONS)) {
      const packed = payload.y[short];
      if (!packed) continue;
      unpackSparse(packed, SECTION_KEYS[long], systems[long]);
      if (long === "heating" && packed.b != null) {
        systems.heating.boiler = fromIdx(BOILER, Number(packed.b) || 0, "none");
      }
      if (long === "security" && Array.isArray(packed.ps)) {
        systems.security.powered_sensors = packed.ps.map((row) => ({
          type: String(row[0] || "pir"),
          qty: Number(row[1]) || 0,
        }));
      }
      if (packed.pi != null) {
        systems[long].panel_id = panelIds[Number(packed.pi)] || mainId;
      }
    }
    if (payload.y.g) {
      const g = payload.y.g;
      if (g.m === 0) systems.system.manual_control = false;
      if (g.h != null) systems.system.ha_server = fromIdx(HA, Number(g.h) || 0, "needed");
    }
  }

  const expertDemand =
    expert && payload.d && typeof payload.d === "object" ? payload.d : {};

  const ui_mode = payload.m === "s" ? "simple" : "advanced";

  return {
    ok: true,
    older: warn,
    patch: {
      ui_mode,
      step: ui_mode === "advanced" ? 3 : 0,
      expert: ui_mode === "simple" ? false : expert,
      object,
      panels,
      rooms,
      rooms_user_edited: true,
      systems,
      expertDemand,
      systems_expanded: null,
      shareFromLink: true,
      shareLinkOlder: warn,
    },
  };
}

function encodeShareLink(state) {
  const payload = buildSharePayload(state);
  const json = JSON.stringify(payload);
  return bytesToBase64Url(utf8Encode(json));
}

function decodeShareLink(token) {
  try {
    const json = utf8Decode(base64UrlToBytes(String(token || "").trim()));
    const payload = JSON.parse(json);
    return expandSharePayload(payload);
  } catch (err) {
    return { ok: false, older: false, patch: null, error: String(err?.message || err) };
  }
}

/** Full URL length for a page origin + path + ?c= */
function shareUrlLength(originPath, state) {
  const c = encodeShareLink(state);
  return `${originPath}?c=${c}`.length;
}

HM.buildSharePayload = buildSharePayload;
HM.expandSharePayload = expandSharePayload;
HM.encodeShareLink = encodeShareLink;
HM.decodeShareLink = decodeShareLink;
HM.shareUrlLength = shareUrlLength;
HM.SHARE_SCHEMA_VERSION = SHARE_SCHEMA_VERSION;

