function moduleRowIcon(id) {
  if (MODULE_ICON_BY_ID[id]) return MODULE_ICON_BY_ID[id];
  const u = String(id || "").toUpperCase();
  if (/PLC/.test(u)) return "controller";
  if (/^DIO|RELAY/.test(u)) return "relay";
  if (/^DIM/.test(u)) return "dimmer";
  if (/^RGB|^STR/.test(u)) return "rgb";
  if (/^ALM|^PIR/.test(u)) return "sensor";
  if (/^WLD|LEAK/.test(u)) return "leak";
  if (/^ENM|METER/.test(u)) return "meter";
  if (/OPENTHERM|OTG|GATEWAY/.test(u)) return "gateway";
  return "gear";
}

function companionRowIcon(id) {
  return COMPANION_ICON_BY_ID[id] || "gear";
}

function companionNote(id, label) {
  return COMPANION_NOTE_BY_ID[id] || label || id;
}

function icoBox(name, size = 16) {
  return `<span class="hm-ico-box">${hmIcon(name, size)}</span>`;
}

function ensureRoomsSeeded() {
  if (state.ui_mode === "simple") {
    if (!state.rooms?.length) runSimpleSync();
    else {
      state.rooms = state.rooms.map((r) => ({
        ...roomDefaults(r.template || "living"),
        ...r,
        template: r.template || "living",
        panel_id: r.panel_id || firstPanelId(),
        manual: r.manual && typeof r.manual === "object" ? r.manual : {},
      }));
    }
    return;
  }
  if (state.rooms?.length && state.rooms_user_edited) {
    state.rooms = state.rooms.map((r) => ({
      ...roomDefaults(r.template || "living"),
      ...r,
      template: r.template || "living",
      panel_id: r.panel_id || firstPanelId(),
      manual: r.manual && typeof r.manual === "object" ? r.manual : {},
    }));
    return;
  }
  state.rooms = seedRoomsFromProperty(
    state.object.property_type || "apartment",
    Number(state.object.floor_area_m2) || 0,
    Number(state.object.floors) || 1,
  ).map((r) => ({ ...r, manual: r.manual || {} }));
  state.rooms_user_edited = false;
}

/** Migrate v4/v5: cabinets → panels; ensure room.manual + simple block. */
function migrateState(saved) {
  if (!Array.isArray(saved.panels) || saved.panels.length === 0) {
    saved.panels = defaultPanels();
  }
  const mainId = saved.panels[0].id || "panel-1";
  saved.panels = saved.panels.map((p, i) => ({
    id: String(p.id || `panel-${i + 1}`),
    name: String(p.name || (i === 0 ? "Main panel" : `Panel ${i + 1}`)),
    location: String(p.location || ""),
  }));
  if (Array.isArray(saved.rooms)) {
    const panelIds = new Set(saved.panels.map((p) => p.id));
    saved.rooms = saved.rooms.map((r) => ({
      ...r,
      panel_id:
        r.panel_id && panelIds.has(r.panel_id) ? r.panel_id : mainId,
      manual: r.manual && typeof r.manual === "object" ? r.manual : {},
    }));
  }
  if (saved.systems) {
    const defaults = emptySystems(mainId);
    const panelIds = new Set(saved.panels.map((p) => p.id));
    for (const k of Object.keys(defaults)) {
      saved.systems[k] = { ...defaults[k], ...(saved.systems[k] || {}) };
      if (k === "system") continue;
      const pid = saved.systems[k].panel_id;
      if (!pid || !panelIds.has(pid)) {
        saved.systems[k].panel_id = mainId;
      }
    }
    if (saved.systems.system) {
      delete saved.systems.system.cabinets;
    }
  }
  if (!saved.simple || typeof saved.simple !== "object") {
    saved.simple = {
      counts: defaultSimpleRoomCounts(),
      totals: defaultSimpleTotals(),
      toggles: defaultSimpleToggles(),
      warnings: [],
    };
  } else {
    saved.simple = {
      counts: { ...defaultSimpleRoomCounts(), ...(saved.simple.counts || {}) },
      totals: { ...defaultSimpleTotals(), ...(saved.simple.totals || {}) },
      toggles: { ...defaultSimpleToggles(), ...(saved.simple.toggles || {}) },
      warnings: Array.isArray(saved.simple.warnings) ? saved.simple.warnings : [],
    };
  }
  if (saved.ui_mode !== "advanced") saved.ui_mode = "simple";
  return saved;
}

function loadState() {
  try {
    let raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) raw = localStorage.getItem("hm_configurator_v5");
    if (!raw) raw = localStorage.getItem("hm_configurator_v4");
    if (!raw) {
      try {
        const mode = localStorage.getItem(MODE_KEY);
        if (mode === "advanced" || mode === "simple") state.ui_mode = mode;
      } catch {
        /* ignore */
      }
      return;
    }
    const saved = migrateState(JSON.parse(raw));
    if (saved.rulesVersion && rules && saved.rulesVersion !== rules.version) return;
    Object.assign(state, saved, { rulesVersion: rules?.version });
    if (!state.panels?.length) state.panels = defaultPanels();
    if (!state.systems) state.systems = emptySystems(firstPanelId());
    const defaults = emptySystems(firstPanelId());
    state.systems = { ...defaults, ...state.systems };
    for (const k of Object.keys(defaults)) {
      state.systems[k] = { ...defaults[k], ...(saved.systems?.[k] || {}) };
      if (k !== "system" && !state.systems[k].panel_id) {
        state.systems[k].panel_id = firstPanelId();
      }
    }
    delete state.systems.system?.cabinets;
    if (!state.simple) {
      state.simple = {
        counts: defaultSimpleRoomCounts(),
        totals: defaultSimpleTotals(),
        toggles: defaultSimpleToggles(),
        warnings: [],
      };
    }
    if (state.ui_mode !== "advanced") state.ui_mode = "simple";
  } catch {
    /* ignore */
  }
}

function markRoomFieldManual(room, key) {
  if (!room.manual || typeof room.manual !== "object") room.manual = {};
  if (SIMPLE_DISTRIBUTE_FIELDS.includes(key) || key === "lights_dimmable") {
    room.manual[key] = true;
  }
}

function runSimpleSync({ rebuildCounts = false } = {}) {
  if (rebuildCounts) {
    /* keep state.simple.counts as set by sliders */
  }
  const { rooms, warnings } = applySimpleDistribution({
    counts: state.simple.counts,
    totals: state.simple.totals,
    rooms: state.rooms,
    roomTypeLabels: rules?.room_type_labels,
    roomTemplates: rules?.room_templates,
    roomDefaultsFn: (t) => simpleRoomDefaults(t),
    panelId: firstPanelId(),
  });
  state.rooms = rooms;
  state.rooms_user_edited = true;
  state.simple.warnings = warnings;
  state.systems = applySimpleToggles(state.systems, state.simple.toggles);
  // Mirror UFH house total from slider for Systems collector field.
  state.systems.heating.collector_loops = Math.max(
    0,
    Number(state.simple.totals.ufh_loops) || 0,
  );
}

/**
 * Build the exact Simple example configuration used for card price AND click apply.
 * Always starts from emptySystems — never merges leftover Advanced/Simple systems.
 */
function buildExampleConfig(kind) {
  const raw = simplePreset(kind === "villa" ? "villa" : kind === "house" ? "house" : "apartment");
  const { preset: p, exclusions, controllersOk } = adaptPresetForAvailability(
    raw,
    moduleIsAvailable,
  );
  const { rooms, warnings } = applySimpleDistribution({
    counts: p.counts,
    totals: p.totals,
    rooms: [],
    roomTypeLabels: rules?.room_type_labels,
    roomTemplates: rules?.room_templates,
    roomDefaultsFn: (t) => simpleRoomDefaults(t),
    panelId: firstPanelId(),
  });
  let systems = applySimpleToggles(emptySystems(firstPanelId()), p.toggles);
  systems.heating.collector_loops = Math.max(0, Number(p.totals.ufh_loops) || 0);
  if (p.clearStairLighting && systems.lighting_scenes) {
    systems.lighting_scenes.stair_steps = 0;
    systems.lighting_scenes.accent_zones = 0;
  }
  const inputs = {
    panels: resolvePanels({ panels: [{ id: "panel-1", name: "Main panel", location: "" }] }),
    rooms,
    systems,
    stage: state.object.stage || "design",
    property_type: p.property_type,
    floor_area_m2: p.floor_area_m2,
    floors: p.floors,
  };
  return {
    kind: kind === "villa" ? "villa" : kind === "house" ? "house" : "apartment",
    preset: p,
    exclusions,
    controllersOk,
    rooms,
    systems,
    warnings,
    inputs,
  };
}

function applyPreset(kind) {
  const cfg = buildExampleConfig(kind);
  state.object.property_type = cfg.preset.property_type;
  state.object.floor_area_m2 = cfg.preset.floor_area_m2;
  state.object.floors = cfg.preset.floors;
  state.simple.counts = cfg.preset.counts;
  state.simple.totals = cfg.preset.totals;
  state.simple.toggles = cfg.preset.toggles;
  state.simple.preset = cfg.kind;
  state.simple.stockExclusions = cfg.exclusions;
  state.simple.controllersOk = cfg.controllersOk;
  state.simple.warnings = cfg.warnings || [];
  state.rooms = cfg.rooms;
  state.systems = cfg.systems;
  state.rooms_user_edited = true;
  state.panels = [{ id: "panel-1", name: "Main panel", location: "" }];
}

function syncSimpleSlidersFromRooms() {
  state.simple.totals = totalsFromRooms(state.rooms);
  state.simple.counts = countsFromRooms(state.rooms);
  state.simple.toggles = togglesFromSystems(state.systems);
  state.simple.warnings = [];
}

/** True when shop ld+json marks the module InStock (or we have no price yet). */
function moduleIsAvailable(moduleId) {
  const spec = rules?.modules?.[moduleId];
  if (!spec?.sku) return true;
  const p = priceMap[spec.sku];
  if (!p) return true;
  return p.available !== false;
}

/** Fetch shop pages for every module SKU so example presets can drop OOS features. */
async function ensureStockCatalog() {
  const specs = rules?.modules || {};
  const urls = [
    ...new Set(
      Object.values(specs)
        .map((s) => s?.shop_url)
        .filter(Boolean),
    ),
  ];
  if (!urls.length) return;
  const missing = urls.filter((u) => {
    const spec = Object.values(specs).find((s) => s.shop_url === u);
    return spec?.sku && !(priceMap[spec.sku] && Number.isFinite(priceMap[spec.sku].amount));
  });
  if (!missing.length) return;
  const map = await fetchPrices(missing, { preferredCurrency: detectShopCurrency() });
  priceMap = { ...priceMap, ...toEstimatePriceMap(map) };
}

function saveState() {
  try {
    localStorage.setItem(
      STORAGE_KEY,
      JSON.stringify({ ...state, rulesVersion: rules?.version }),
    );
  } catch {
    /* ignore */
  }
}

function applySharePatch(patch) {
  if (!patch) return false;
  Object.assign(state, patch);
  if (!state.panels?.length) state.panels = defaultPanels();
  if (!state.systems) state.systems = emptySystems(firstPanelId());
  const mode = patch.ui_mode === "simple" ? "simple" : "advanced";
  state.ui_mode = mode;
  if (mode === "advanced") state.step = 3;
  if (mode === "simple") syncSimpleSlidersFromRooms();
  saveState();
  try {
    localStorage.setItem(MODE_KEY, mode);
  } catch {
    /* ignore */
  }
  return true;
}

/** Read ?c= from the page URL and restore configuration → Result. */
function consumeShareQuery() {
  if (typeof location === "undefined") return false;
  let params;
  try {
    params = new URLSearchParams(location.search);
  } catch {
    return false;
  }
  const token = params.get("c");
  if (!token) return false;
  const decoded = decodeShareLink(token);
  if (!decoded.ok || !decoded.patch) {
    console.warn("HM estimator: share link decode failed", decoded.error);
    return false;
  }
  applySharePatch(decoded.patch);
  state.shareLinkOlder = !!decoded.older;
  return true;
}

function buildShareUrl() {
  const token = encodeShareLink(state);
  if (typeof location === "undefined") return `?c=${token}`;
  const url = new URL(location.href);
  url.searchParams.set("c", token);
  return url.toString();
}

async function copyShareLink(button) {
  const url = buildShareUrl();
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(url);
    } else {
      const ta = document.createElement("textarea");
      ta.value = url;
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
    }
    if (button) {
      button.textContent = "Link copied";
      button.disabled = true;
      setTimeout(() => {
        button.innerHTML = `${hmIcon("link", 16)} Copy link`;
        button.disabled = false;
      }, 2000);
    }
    return true;
  } catch (err) {
    console.warn("copy link", err);
    if (button) {
      button.textContent = "Copy failed";
      setTimeout(() => {
        button.innerHTML = `${hmIcon("link", 16)} Copy link`;
      }, 2000);
    }
    return false;
  }
}

function buildInputs() {
  // Simple mode always uses one panel; Advanced keeps user-created panels.
  const panels =
    state.ui_mode === "simple"
      ? [{ id: "panel-1", name: "Main panel", location: "" }]
      : resolvePanels({ panels: state.panels });
  const mainId = panels[0]?.id || "panel-1";
  if (state.expert) {
    return {
      panels,
      mode: "expert",
      expert: { demand: { ...state.expertDemand } },
      stage: state.object.stage,
      systems: {
        system: { ...state.systems.system },
      },
    };
  }
  const systems = JSON.parse(JSON.stringify(state.systems));
  if (state.ui_mode === "simple") {
    for (const sec of [
      "heating",
      "ventilation",
      "water",
      "electrical",
      "security",
      "lighting_scenes",
    ]) {
      if (systems[sec] && typeof systems[sec] === "object") {
        systems[sec].panel_id = mainId;
      }
    }
  }
  return {
    panels,
    property_type: state.object.property_type,
    floor_area_m2: state.object.floor_area_m2,
    floors: state.object.floors,
    stage: state.object.stage,
    name: state.object.name,
    rooms: state.rooms.map((r) => ({
      ...r,
      panel_id:
        state.ui_mode === "simple" ? mainId : r.panel_id || mainId,
    })),
    systems,
  };
}

function runEstimate(inputs, prices = priceMap) {
  if (!rules) throw new Error("Rules not loaded");
  return estimate(inputs, rules, prices);
}

async function refreshPrices(result) {
  const fromPanels = (result.panels || []).flatMap((p) => p.modules || []);
  const mods = fromPanels.length ? fromPanels : result.modules || [];
  const urls = [...new Set(mods.map((m) => m.shop_url).filter(Boolean))];
  if (!urls.length) return { missingSkus: [], unavailable: [] };

  const gen = ++priceFetchGen;
  const preferred = detectShopCurrency();
  let map = await fetchPrices(urls, { preferredCurrency: preferred });
  if (gen !== priceFetchGen) return { missingSkus: [], unavailable: [], superseded: true };

  // Merge — never wipe prices already known (avoids blank first paint / races).
  const next = toEstimatePriceMap(map);
  priceMap = { ...priceMap, ...next };

  // Retry once for modules still missing a price (transient shop failures).
  const stillMissingUrls = mods
    .filter((m) => m.shop_url && m.sku && !(priceMap[m.sku] && Number.isFinite(priceMap[m.sku].amount)))
    .map((m) => m.shop_url);
  const retryUrls = [...new Set(stillMissingUrls)];
  if (retryUrls.length) {
    map = await fetchPrices(retryUrls, {
      preferredCurrency: preferred,
      bypassCache: true,
    });
    if (gen !== priceFetchGen) return { missingSkus: [], unavailable: [], superseded: true };
    priceMap = { ...priceMap, ...toEstimatePriceMap(map) };
  }

  const missingSkus = [
    ...new Set(
      mods
        .filter((m) => m.sku && !(priceMap[m.sku] && Number.isFinite(priceMap[m.sku].amount)))
        .map((m) => m.sku),
    ),
  ];
  const unavailable = mods.filter(
    (m) => m.sku && priceMap[m.sku] && priceMap[m.sku].available === false,
  );
  return { missingSkus, unavailable };
}

function formatPrice(p) {
  if (!p || typeof p.amount !== "number" || !Number.isFinite(p.amount)) {
    return '<span class="hm-muted">—</span>';
  }
  const amb = p.currencyAmbiguous
    ? ' <span class="hm-muted">(currency may not match shop session)</span>'
    : "";
  const stock =
    p.available === false
      ? ' <span class="hm-warn">not available in shop</span>'
      : "";
  return `${p.amount} ${p.currency || ""}${amb}${stock}`;
}

function formatPriceCell(p) {
  if (!p || typeof p.amount !== "number" || !Number.isFinite(p.amount)) {
    return `<span class="hm-price-dot" title="Price unavailable — not counted in the total" aria-label="Price unavailable"></span>`;
  }
  const stock =
    p.available === false
      ? ` <span class="hm-warn">out of stock</span>`
      : "";
  return `<span class="hm-bom__price">${p.amount} ${escapeAttr(p.currency || "")}${stock}</span>`;
}

/**
 * @param {object} result
 * @param {object} prices
 * @param {{ omitShopUnavailable?: boolean }} [opts]
 *   omitShopUnavailable — Simple shows OOS inline; skip the top warning.
 */
function collectResultNotes(result, prices, opts = {}) {
  const notes = [];
  if (result.split_warning) notes.push(result.split_warning);
  for (const a of result.assumptions || []) {
    if (/ALM 12 V rail:.*exceeds/i.test(a) || /Reserve suggestion|prices incomplete|exceeds/i.test(a)) {
      notes.push(a);
    }
  }
  const tot = cartTotal(result, prices);
  if (tot?.missingSku?.length && !opts.omitShopUnavailable) {
    const skus = [...new Set(tot.missingSku)];
    notes.push(
      `${skus.length} line(s) without a price — total is understated (${skus.join(", ")}).`,
    );
  }
  if (!opts.omitShopUnavailable) {
    const mods = [
      ...((result.panels || []).flatMap((p) => p.modules || [])),
      ...(result.modules || []),
    ];
    const seen = new Set();
    const unavailable = [];
    for (const m of mods) {
      if (!m?.sku || seen.has(m.sku)) continue;
      seen.add(m.sku);
      const p = prices[m.sku];
      if (p && Number.isFinite(p.amount) && p.available === false) {
        unavailable.push(m.id || m.sku);
      }
    }
    if (unavailable.length) {
      notes.push(`Not available in the shop: ${unavailable.join(", ")}.`);
    }
  }
  return [...new Set(notes)];
}

function resultNotesBarHtml(notes) {
  if (!notes.length) return "";
  return `<div class="hm-notes">
            <button type="button" class="hm-notes-bar" id="hm-notes-toggle" aria-expanded="false">
              ${hmIcon("warning", 18)}
              <span>${notes.length} note${notes.length === 1 ? "" : "s"} to review</span>
              <span class="hm-notes-bar__chev">${hmIcon("chevron", 16)}</span>
            </button>
            <div class="hm-notes-body" id="hm-notes-body" hidden>
              ${notes.map((n) => `<p class="hm-warn">${escapeAttr(n)}</p>`).join("")}
            </div>
          </div>`;
}

/**
 * Shared Result hero — price | metric tiles | optional action stack (Advanced).
 * @param {{ priceHtml: string, stats: Array<{icon:string,value:string|number,label:string,tone?:string}>, actionsHtml?: string }} opts
 */
function resultHeroHtml({ priceHtml, stats, actionsHtml = "" }) {
  const statsHtml = (stats || [])
    .map((s) => {
      const tone = s.tone ? ` hm-result-stat--${escapeAttr(s.tone)}` : "";
      return `<div class="hm-result-stat${tone}">${hmIcon(s.icon, 20)}<span class="hm-result-stat__n">${s.value}</span><span class="hm-result-stat__l">${escapeAttr(s.label)}</span></div>`;
    })
    .join("");
  const actions = actionsHtml
    ? `<div class="hm-result-hero__actions">${actionsHtml}</div>`
    : "";
  return `<div class="hm-card hm-result-hero${actionsHtml ? "" : " hm-result-hero--simple"}">
          <div>
            ${priceHtml}
            <p class="hm-result-hero__sub">incl. VAT · equipment only</p>
          </div>
          <div class="hm-result-stats">${statsHtml}</div>
          ${actions}
        </div>`;
}

function bindNotesToggle(root) {
  const notesBtn = root.querySelector("#hm-notes-toggle");
  if (!notesBtn) return;
  notesBtn.onclick = () => {
    const body = root.querySelector("#hm-notes-body");
    if (!body) return;
    const open = body.hidden;
    body.hidden = !open;
    notesBtn.setAttribute("aria-expanded", open ? "true" : "false");
  };
}

function formatModuleBuyPrice(row) {
  const qty = Number(row.qty) || 1;
  const cur = escapeAttr(row.currency || "");
  if (row.amount != null && Number.isFinite(row.amount)) {
    const line = Math.round(row.amount * qty * 100) / 100;
    const unit = `${row.amount}${cur ? ` ${cur}` : ""}`;
    const total = `${line}${cur ? ` ${cur}` : ""}`;
    const priceBit =
      qty > 1
        ? `<span class="hm-simple-buy__price">${unit} each · ${total}</span>`
        : `<span class="hm-simple-buy__price">${total}</span>`;
    if (row.status === "oos") {
      return `${priceBit} · <span class="hm-simple-buy__oos">out of stock</span>`;
    }
    if (row.status === "ok") return priceBit;
  }
  if (row.status === "oos") {
    return `<span class="hm-simple-buy__oos">out of stock</span>`;
  }
  return `<span class="hm-muted">price pending</span>`;
}

function modulesYouBuyHtml(rows, { limit = 6 } = {}) {
  if (!rows.length) {
    return `<p class="hm-muted">No HomeMaster modules in this estimate.</p>`;
  }
  const shown = rows.slice(0, limit);
  const rest = rows.length - shown.length;
  const item = (r, extra = false) =>
    `<li${extra ? ' class="hm-simple-buy__extra" hidden' : ""}><span class="hm-simple-buy__line"><span class="hm-simple-buy__qty">${r.qty}×</span> <span class="hm-simple-buy__id">${escapeAttr(r.id)}</span> · ${formatModuleBuyPrice(r)}</span></li>`;
  const list = shown.map((r) => item(r)).join("");
  const extras = rest > 0 ? rows.slice(limit).map((r) => item(r, true)).join("") : "";
  const more =
    rest > 0
      ? `<li class="hm-simple-buy__more"><button type="button" id="s-mods-more">+ ${rest} more</button></li>`
      : "";
  return `<ul class="hm-simple-buy__list">${list}${extras}${more}</ul>`;
}

/** Subtitle under Add to cart: in-stock cart total only. */
function cartHintHtml(cartTot, sysTot) {
  if (!cartTot || !cartTot.pricedQty) {
    if (sysTot && sysTot.pricedQty > 0 && sysTot.unavailableLineCount > 0) {
      return `<p class="hm-simple-actions__hint hm-muted">In cart now: nothing — ${sysTot.unavailableLineCount} module${sysTot.unavailableLineCount === 1 ? "" : "s"} unavailable</p>`;
    }
    return `<p class="hm-simple-actions__hint hm-muted">No priced units to add</p>`;
  }
  let text = `In cart now: ${cartTot.total} ${escapeAttr(cartTot.currency)}`;
  const n = sysTot?.unavailableLineCount || cartTot.unavailableSku?.length || 0;
  if (n > 0) {
    text += ` · ${n} module${n === 1 ? "" : "s"} unavailable`;
  }
  return `<p class="hm-simple-actions__hint">${text}</p>`;
}

function channelUsageTable(usage, { fold = true } = {}) {
  const rows = (usage || []).filter((r) => r.needed > 0 || r.reserve);
  if (!rows.length) return "";
  const body = rows
    .map((r) => {
      const tip = r.note ? ` title="${escapeAttr(r.note)}"` : "";
      return `<tr${tip}><td>${escapeAttr(r.label)}</td><td>${r.needed}</td><td>${r.supplied}</td><td>${r.spare}</td></tr>`;
    })
    .join("");
  const table = `
    <table class="hm-table hm-channel-table">
      <thead><tr><th>Channel type</th><th>Needed</th><th>Supplied</th><th>Spare</th></tr></thead>
      <tbody>${body}</tbody>
    </table>`;
  if (!fold) return table;
  return `<details class="hm-fold">
    <summary>${hmIcon("chart", 18)} Channel usage <span class="hm-fold__chev">${hmIcon("chevron", 16)}</span></summary>
    <div class="hm-fold__body">${table}</div>
  </details>`;
}

function notIncludedBlock(items) {
  const list = (items || []).map((t) => String(t).trim()).filter(Boolean);
  if (!list.length) return "";
  const body = list.map((t) => `<li>${escapeAttr(t)}</li>`).join("");
  return `<div class="hm-card hm-not-included">
    <h3>Not included — to be specified by the electrical design</h3>
    <ul class="hm-not-included__list">${body}</ul>
  </div>`;
}

function enclosureMessage(enclosure, { compact = false } = {}) {
  if (!enclosure) return `<p>Enclosure: —</p>`;
  if (enclosure.status === "blocked") {
    if (enclosure.reason === "din_units_missing") {
      const mods = (enclosure.modules || []).join(", ");
      return `<p class="hm-warn">Panel layout: blocked — DIN width unknown for ${mods || "some HomeMaster modules"}</p>`;
    }
    return `<p class="hm-warn">Panel layout: blocked — ${enclosure.reason}</p>`;
  }
  if (enclosure.status === "overflow" || enclosure.overflow) {
    return `<p class="hm-warn">Enclosure: ${enclosure.din_needed} M needed exceeds max ${enclosure.max_sections || 4}×(6×24)=${(enclosure.max_sections || 4) * (enclosure.max_capacity || 144)} M — add another panel on screen 1 or reduce demand.</p>`;
  }
  const occupied = enclosure.occupied ?? enclosure.din_occupied ?? enclosure.din_total;
  const free = enclosure.free ?? enclosure.din_free;
  const breakdown =
    occupied != null && free != null
      ? `occupied ${occupied} M · needed ${enclosure.din_needed} M · free after rounding ${free} M`
      : `${enclosure.din_total} M occupied → ${enclosure.din_needed} M needed`;
  if (compact || enclosure.panels > 1) {
    return `<p>DIN (${enclosure.panels > 1 ? "all panels" : "panel"}): ${breakdown} → capacity ${enclosure.capacity} M</p>`;
  }
  const cabinets = enclosure.cabinets || 1;
  const each = enclosure.capacity_each ?? enclosure.capacity;
  const layout =
    cabinets > 1
      ? `${cabinets} × (${enclosure.rows} rows × ${enclosure.row_width})`
      : `${enclosure.rows} rows × ${enclosure.row_width}`;
  const mm =
    enclosure.width_mm != null && enclosure.height_mm != null
      ? `, approx. ${enclosure.width_mm} × ${enclosure.height_mm} mm`
      : "";
  const coupled = cabinets > 1 ? " — coupled sections" : "";
  const blank =
    enclosure.blanking_qty > 0
      ? ` · ${enclosure.blanking_qty} blanking plate(s)`
      : "";
  return `<p>Enclosure: ${breakdown} → ${cabinets > 1 ? `${cabinets}×` : "1×"} enclosure ${each} M (${layout}${mm})${coupled}${blank}</p>`;
}

function priceIntegrityHtml(result, prices) {
  return collectResultNotes(result, prices)
    .map((n) => `<p class="hm-warn">${escapeAttr(n)}</p>`)
    .join("");
}

function el(html) {
  const t = document.createElement("template");
  t.innerHTML = html.trim();
  return t.content.firstElementChild;
}

function escapeAttr(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;");
}

/**
 * @param {HTMLElement} root
 */
function mountConfigurator(root) {
  root.innerHTML = "";
  const shell = el(`
    <div class="hm-estimator">
      <header class="hm-estimator__header">
        <h1>How much does a HomeMaster system cost?</h1>
        <p class="hm-estimator__tagline">HomeMaster modules only — panel, protection and installation are quoted separately.</p>
        <div class="hm-mode-toggle" role="group" aria-label="Configurator mode">
          <button type="button" id="hm-mode-simple" class="hm-mode-btn">Simple</button>
          <button type="button" id="hm-mode-advanced" class="hm-mode-btn">Advanced</button>
        </div>
        <label class="hm-expert" id="hm-expert-wrap"><input type="checkbox" id="hm-expert"> Expert mode (direct demand)</label>
      </header>
      <div class="hm-examples" id="hm-examples"></div>
      <nav class="hm-steps" id="hm-steps"></nav>
      <div class="hm-layout" id="hm-layout">
        <main class="hm-main" id="hm-main"></main>
        <aside class="hm-summary" id="hm-summary"></aside>
      </div>
      <div class="hm-simple-dock" id="hm-simple-dock" hidden></div>
    </div>
  `);
  root.appendChild(shell);

  const stepsNav = shell.querySelector("#hm-steps");
  const main = shell.querySelector("#hm-main");
  const summary = shell.querySelector("#hm-summary");
  const layout = shell.querySelector("#hm-layout");
  const examplesEl = shell.querySelector("#hm-examples");
  const simpleDock = shell.querySelector("#hm-simple-dock");
  const expertCb = shell.querySelector("#hm-expert");
  const expertWrap = shell.querySelector("#hm-expert-wrap");
  const modeSimpleBtn = shell.querySelector("#hm-mode-simple");
  const modeAdvancedBtn = shell.querySelector("#hm-mode-advanced");
  const estimatorRoot = shell;

  function setUiMode(mode, { syncFromRooms = false } = {}) {
    const next = mode === "advanced" ? "advanced" : "simple";
    if (next === "simple" && state.ui_mode === "advanced") {
      syncSimpleSlidersFromRooms();
    }
    if (next === "advanced" && state.ui_mode === "simple") {
      runSimpleSync();
      state.object.floor_area_m2 = estimateFloorAreaFromCounts(
        state.simple.counts,
        state.object.property_type,
      );
      state.step = 0;
    }
    // Simple → Advanced: do not redistribute.
    state.ui_mode = next;
    try {
      localStorage.setItem(MODE_KEY, next);
    } catch {
      /* ignore */
    }
    if (syncFromRooms) syncSimpleSlidersFromRooms();
    saveState();
    render();
  }

  modeSimpleBtn.addEventListener("click", () => setUiMode("simple"));
  modeAdvancedBtn.addEventListener("click", () => setUiMode("advanced"));

  expertCb.checked = !!state.expert;
  expertCb.addEventListener("change", () => {
    state.expert = expertCb.checked;
    saveState();
    render();
  });

  function renderModeChrome() {
    const simple = state.ui_mode === "simple";
    modeSimpleBtn.classList.toggle("is-active", simple);
    modeAdvancedBtn.classList.toggle("is-active", !simple);
    stepsNav.hidden = simple || !!state.expert;
    expertWrap.hidden = simple;
    layout.classList.toggle("hm-layout--simple", simple);
    examplesEl.hidden = !simple;
    estimatorRoot.classList.toggle("hm-estimator--simple", simple);
    if (!simple && simpleDock) {
      simpleDock.hidden = true;
      simpleDock.innerHTML = "";
    }
  }

  function renderExamples() {
    if (state.ui_mode !== "simple") {
      examplesEl.innerHTML = "";
      return;
    }
    const cards = [
      ["apartment", "Apartment", "apartment"],
      ["house", "Detached house", "house"],
      ["villa", "Large villa", "villa"],
    ];
    examplesEl.innerHTML = `
      <p class="hm-examples__label">Start from an example</p>
      <div class="hm-examples__row">
        ${cards
          .map(
            ([id, label, icon]) =>
              `<div class="hm-example-wrap">
                <button type="button" class="hm-example-card${
                  state.simple?.preset === id ? " is-selected" : ""
                }" data-preset="${id}">
                  <span class="hm-example-card__ico">${hmIcon(icon, 22)}</span>
                  <span class="hm-example-card__text">
                    <strong>${label}</strong>
                    <span class="hm-example-price" data-preset-price="${id}">…</span>
                  </span>
                </button>
                <div class="hm-example-excl" data-preset-excl="${id}" hidden></div>
              </div>`,
          )
          .join("")}
      </div>`;
    examplesEl.querySelectorAll("[data-preset]").forEach((btn) => {
      btn.onclick = async () => {
        // Apply immediately so the UI matches the card; then refresh stock and re-apply.
        applyPreset(btn.dataset.preset);
        saveState();
        render();
        await ensureStockCatalog();
        applyPreset(btn.dataset.preset);
        saveState();
        render();
        refreshExamplePrices();
      };
    });
    refreshExamplePrices();
  }

  async function refreshExamplePrices() {
    if (state.ui_mode !== "simple") return;
    await ensureStockCatalog();
    for (const kind of ["apartment", "house", "villa"]) {
      const elPrice = examplesEl.querySelector(`[data-preset-price="${kind}"]`);
      const elExcl = examplesEl.querySelector(`[data-preset-excl="${kind}"]`);
      if (!elPrice) continue;
      try {
        const cfg = buildExampleConfig(kind);
        if (elExcl) {
          if (cfg.exclusions.length || !cfg.controllersOk) {
            const lines = [...cfg.exclusions];
            if (!cfg.controllersOk) {
              lines.push(
                "Controllers unavailable — MiniPLC and MicroPLC are currently out of stock.",
              );
            }
            elExcl.hidden = false;
            elExcl.innerHTML = lines.map((t) => `<p>${escapeAttr(t)}</p>`).join("");
          } else {
            elExcl.hidden = true;
            elExcl.innerHTML = "";
          }
        }
        if (!cfg.controllersOk) {
          elPrice.textContent = "unavailable";
          continue;
        }
        let result = estimate(cfg.inputs, rules, priceMap);
        const urls = (result.modules || []).map((m) => m.shop_url).filter(Boolean);
        if (urls.length) {
          const map = await fetchPrices(urls, { preferredCurrency: detectShopCurrency() });
          priceMap = { ...priceMap, ...toEstimatePriceMap(map) };
          // Re-adapt after prices: OOS gates may change once availability is known.
          const cfg2 = buildExampleConfig(kind);
          if (elExcl) {
            if (cfg2.exclusions.length || !cfg2.controllersOk) {
              const lines = [...cfg2.exclusions];
              if (!cfg2.controllersOk) {
                lines.push(
                  "Controllers unavailable — MiniPLC and MicroPLC are currently out of stock.",
                );
              }
              elExcl.hidden = false;
              elExcl.innerHTML = lines.map((t) => `<p>${escapeAttr(t)}</p>`).join("");
            }
          }
          if (!cfg2.controllersOk) {
            elPrice.textContent = "unavailable";
            continue;
          }
          result = estimate(cfg2.inputs, rules, priceMap);
        }
        const sys = systemTotal(result, priceMap);
        elPrice.textContent =
          sys && sys.pricedQty > 0 ? `${sys.total} ${sys.currency}` : "see estimate";
      } catch {
        elPrice.textContent = "—";
      }
    }
  }

  function renderSteps() {
    if (state.ui_mode === "simple") {
      stepsNav.innerHTML = "";
      return;
    }
    stepsNav.innerHTML = STEPS.map(
      (name, i) =>
        `<button type="button" class="hm-step ${i === state.step ? "is-active" : ""}" data-step="${i}">${i + 1}. ${name}</button>`,
    ).join("");
    stepsNav.querySelectorAll(".hm-step").forEach((btn) => {
      btn.addEventListener("click", () => {
        state.step = Number(btn.dataset.step);
        saveState();
        render();
      });
    });
  }

  function liveResult() {
    try {
      return runEstimate(buildInputs(), priceMap);
    } catch (err) {
      return { error: String(err) };
    }
  }

  function renderSummary(result) {
    if (state.step === 3) {
      summary.hidden = true;
      summary.innerHTML = "";
      layout.classList.add("hm-layout--result");
      return;
    }
    summary.hidden = false;
    layout.classList.remove("hm-layout--result");
    if (result.error) {
      summary.innerHTML = `<p class="hm-warn">${result.error}</p>`;
      return;
    }
    const tot = cartTotal(result, priceMap);
    let priceHtml = `<p class="hm-simple-price">—</p>`;
    if (tot && tot.pricedQty > 0) {
      priceHtml = `<p class="hm-simple-price">${tot.total} <span>${escapeAttr(tot.currency)}</span></p>`;
    }
    const ptype =
      PROPERTY_TYPES.find(([v]) => v === state.object.property_type)?.[1] ||
      state.object.property_type;
    const namedRooms = (state.rooms || []).filter((r) => r.name?.trim()).length;
    const sysBits = SYSTEM_SECTIONS.filter((sec) => sectionHasContent(sec, state.systems)).map(
      (sec) => sec.title,
    );
    const area = Number(state.object.floor_area_m2) || 0;
    const priceNotes = priceIntegrityHtml(result, priceMap);
    const warns = (result.assumptions || [])
      .filter((a) => /ALM 12 V rail:.*exceeds/i.test(a))
      .map((a) => `<p class="hm-warn">${escapeAttr(a)}</p>`)
      .join("");
    const split = result.split_warning
      ? `<p class="hm-warn">${escapeAttr(result.split_warning)}</p>`
      : "";
    summary.innerHTML = `
      <div class="hm-simple-result__head">
        ${hmIcon("estimate", 20)}
        <h2>Progress</h2>
      </div>
      ${priceHtml}
      ${priceNotes}
      <ul class="hm-simple-lines">
        <li><span class="hm-simple-line__ico">${hmIcon("house", 18)}</span><span>${escapeAttr(ptype)}${area ? ` · ${area} m²` : ""}</span></li>
        <li><span class="hm-simple-line__ico">${hmIcon("rooms", 18)}</span><span>${namedRooms} room${namedRooms === 1 ? "" : "s"}</span></li>
        <li><span class="hm-simple-line__ico">${hmIcon("gear", 18)}</span><span>${
          sysBits.length ? escapeAttr(sysBits.join(", ")) : "No whole-home systems yet"
        }</span></li>
        <li><span class="hm-simple-line__ico">${hmIcon("estimate", 18)}</span><span>${state.panels.length} panel${state.panels.length === 1 ? "" : "s"}</span></li>
      </ul>
      ${split}
      ${warns}
      <p class="hm-muted">Channel usage appears on the Result step.</p>
    `;
  }

  function reseedRooms(force) {
    if (!force && state.rooms_user_edited) return;
    state.rooms = seedRoomsFromProperty(
      state.object.property_type,
      Number(state.object.floor_area_m2) || 0,
      Number(state.object.floors) || 1,
    );
    state.rooms_user_edited = false;
    state.rooms_expanded = 0;
  }

  function renderObject() {
    const o = state.object;
    const s = state.systems.system;
    if (state.panels_expanded == null || state.panels_expanded >= state.panels.length) {
      state.panels_expanded = 0;
    }
    main.innerHTML = `
      <h2>Property</h2>
      <label>Project name <input id="f-name" value="${escapeAttr(o.name || "")}"></label>
      <label>Property type
        <select id="f-ptype">${PROPERTY_TYPES.map(
          ([v, lab]) =>
            `<option value="${v}" ${v === o.property_type ? "selected" : ""}>${lab}</option>`,
        ).join("")}</select>
      </label>
      <label>Floor area m² <input id="f-area" type="number" min="0" value="${o.floor_area_m2 ?? 60}"></label>
      <label>Number of floors <input id="f-floors" type="number" min="1" value="${o.floors || 1}"></label>
      <label>Project stage
        <select id="f-stage">${STAGES.map(
          ([v, lab]) =>
            `<option value="${v}" ${v === o.stage ? "selected" : ""}>${lab}</option>`,
        ).join("")}</select>
      </label>
      <p class="hm-muted">Property type and floor area choose a room template and pre-fill the Rooms step. Stage goes to the quote only — it does not change the module list.</p>

      <h3>Panels</h3>
      <p class="hm-muted">A panel is a DIN enclosure (distribution board) that holds the HomeMaster modules for part of the home. One panel is enough for most apartments and small houses. Add another when floors or outbuildings need a separate board — each panel gets its own controller, bus, PSU and enclosure.</p>
      <div id="panel-notice" class="hm-room-undo" ${state.panel_migrate_notice ? "" : "hidden"}>${
        state.panel_migrate_notice
          ? `<span>${escapeAttr(state.panel_migrate_notice)}</span>`
          : ""
      }</div>
      <div id="panel-list"></div>
      <button type="button" id="add-panel">+ panel</button>

      <details class="hm-sys-section" open>
        <summary>System</summary>
        <div class="hm-sys-grid">
          <div class="hm-room-field">
            <div class="hm-room-field__label"><span>Manual controls on modules</span></div>
            <select id="f-manual">
              <option value="yes" ${s.manual_control !== false ? "selected" : ""}>Yes</option>
              <option value="no" ${s.manual_control === false ? "selected" : ""}>No</option>
            </select>
          </div>
          <div class="hm-room-field">
            <div class="hm-room-field__label"><span>Home Assistant server</span></div>
            <select id="f-ha">
              <option value="needed" ${s.ha_server === "needed" ? "selected" : ""}>Needed</option>
              <option value="own" ${s.ha_server === "own" ? "selected" : ""}>Have my own</option>
            </select>
          </div>
        </div>
      </details>
      <div class="hm-actions"><button type="button" id="hm-next">Next</button></div>
    `;

    const panelList = main.querySelector("#panel-list");
    function paintPanels() {
      panelList.innerHTML = state.panels
        .map((p, i) => {
          const open = i === state.panels_expanded;
          if (!open) {
            const loc = p.location ? ` · ${p.location}` : "";
            return `<button type="button" class="hm-room-collapsed" data-pexpand="${i}">
              <span class="hm-room-icon">Panel</span>
              <span class="hm-room-collapsed__text"><strong>${escapeAttr(p.name)}</strong>
                <span class="hm-muted">${escapeAttr(loc)}</span></span>
              <span class="hm-room-chevron">▾</span>
            </button>`;
          }
          const canDelete = state.panels.length > 1;
          return `<article class="hm-room-card hm-room-card--open" data-pi="${i}">
            <header class="hm-room-card__toolbar">
              <button type="button" class="hm-room-collapse" data-pcollapse="${i}" aria-label="Collapse">▴</button>
              <h3 class="hm-room-card__title">${escapeAttr(p.name || "Panel")}</h3>
              ${
                canDelete
                  ? `<button type="button" class="hm-room-delete" data-prm="${i}">
                <svg class="hm-room-delete__icon" width="14" height="14" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M3 6h18M8 6V4h8v2M9 10v8M12 10v8M15 10v8M6 6l1 14h10l1-14"/>
                </svg>
                Delete panel
              </button>`
                  : ""
              }
            </header>
            <div class="hm-room-card__identity">
              <div class="hm-room-field">
                <div class="hm-room-field__label"><span>Name</span></div>
                <input data-pk="name" value="${escapeAttr(p.name || "")}" placeholder="e.g. Floor 1">
              </div>
              <div class="hm-room-field">
                <div class="hm-room-field__label"><span>Location <span class="hm-muted">(optional)</span></span></div>
                <input data-pk="location" value="${escapeAttr(p.location || "")}" placeholder="e.g. Utility room">
              </div>
            </div>
          </article>`;
        })
        .join("");

      panelList.querySelectorAll("[data-pexpand]").forEach((btn) => {
        btn.onclick = () => {
          state.panels_expanded = Number(btn.dataset.pexpand);
          saveState();
          paintPanels();
        };
      });
      panelList.querySelectorAll("[data-pcollapse]").forEach((btn) => {
        btn.onclick = () => {
          state.panels_expanded = -1;
          saveState();
          paintPanels();
        };
      });
      panelList.querySelectorAll(".hm-room-card").forEach((card) => {
        const i = Number(card.dataset.pi);
        card.querySelectorAll("[data-pk]").forEach((inp) => {
          const apply = () => {
            const k = inp.dataset.pk;
            state.panels[i][k] = inp.value;
            if (k === "name") {
              const t = card.querySelector(".hm-room-card__title");
              if (t) t.textContent = inp.value.trim() || "Panel";
            }
            saveState();
            bump();
          };
          inp.oninput = inp.onchange = apply;
        });
        const rm = card.querySelector("[data-prm]");
        if (rm) {
          rm.onclick = () => {
            if (state.panels.length <= 1) return;
            const removed = state.panels[i];
            const fallback = state.panels[i === 0 ? 1 : 0].id;
            state.panels.splice(i, 1);
            let moved = 0;
            for (const room of state.rooms) {
              if (room.panel_id === removed.id) {
                room.panel_id = fallback;
                moved += 1;
              }
            }
            for (const sec of SYSTEM_SECTIONS) {
              if (state.systems[sec.id]?.panel_id === removed.id) {
                state.systems[sec.id].panel_id = fallback;
              }
            }
            if (state.panels_expanded >= state.panels.length) {
              state.panels_expanded = state.panels.length - 1;
            }
            state.panel_migrate_notice =
              moved > 0
                ? `${moved} room(s) from “${removed.name}” moved to “${panelById(fallback).name}”.`
                : "";
            saveState();
            renderObject();
            bump();
          };
        }
      });
    }
    paintPanels();

    main.querySelector("#add-panel").onclick = () => {
      const n = state.panels.length + 1;
      state.panels.push({
        id: `panel-${Date.now().toString(36)}`,
        name: `Panel ${n}`,
        location: "",
      });
      state.panels_expanded = state.panels.length - 1;
      state.panel_migrate_notice = "";
      saveState();
      paintPanels();
      bump();
    };

    main.querySelector("#f-manual").onchange = (e) => {
      state.systems.system.manual_control = e.target.value === "yes";
      saveState();
      bump();
    };
    main.querySelector("#f-ha").onchange = (e) => {
      state.systems.system.ha_server = e.target.value;
      saveState();
      bump();
    };
    const bumpProperty = () => {
      reseedRooms(false);
      saveState();
      bump();
    };
    main.querySelector("#f-name").oninput = (e) => {
      state.object.name = e.target.value;
      saveState();
    };
    main.querySelector("#f-ptype").onchange = (e) => {
      state.object.property_type = e.target.value;
      reseedRooms(true);
      saveState();
      bump();
    };
    main.querySelector("#f-area").oninput = (e) => {
      state.object.floor_area_m2 = Number(e.target.value) || 0;
      bumpProperty();
    };
    main.querySelector("#f-floors").oninput = (e) => {
      state.object.floors = Math.max(1, Number(e.target.value) || 1);
      bumpProperty();
    };
    main.querySelector("#f-stage").onchange = (e) => {
      state.object.stage = e.target.value;
      saveState();
    };
    main.querySelector("#hm-next").onclick = () => {
      if (!state.rooms_user_edited) reseedRooms(true);
      state.step = state.expert ? 3 : 1;
      saveState();
      render();
    };
  }

  function fieldControl(room, key, kind, inputId) {
    const idAttr = inputId ? ` id="${escapeAttr(inputId)}"` : "";
    if (kind === "channels") {
      const v = room.led_strip_channels || 4;
      return `<select data-k="${key}"${idAttr}>${[3, 4, 5]
        .map((n) => `<option value="${n}" ${n === v ? "selected" : ""}>${n} channels</option>`)
        .join("")}</select>`;
    }
    if (kind === "temp") {
      const v = room.temp_sensor || "none";
      return `<select data-k="${key}"${idAttr}>${TEMP_OPTIONS.map(
        ([val, lab]) => `<option value="${val}" ${val === v ? "selected" : ""}>${lab}</option>`,
      ).join("")}</select>`;
    }
    const n = Number(room[key]) || 0;
    return `<span class="hm-stepper">
      <button type="button" class="hm-stepper__btn" data-step="-1" data-k="${key}" aria-label="Decrease">−</button>
      <input${idAttr} data-k="${key}" type="number" min="0" value="${n}" inputmode="numeric">
      <button type="button" class="hm-stepper__btn" data-step="1" data-k="${key}" aria-label="Increase">+</button>
    </span>`;
  }

  function roomFieldHtml(room, field, roomIndex) {
    if (!roomFieldVisible(room, field)) return "";
    const [k, label, kind, opts] = field;
    const inputId = `room-${roomIndex}-${k}`;
    const tip = opts?.tip
      ? `<button type="button" class="hm-field-tip" title="${escapeAttr(opts.tip)}" aria-label="${escapeAttr(opts.tip)}">?</button>`
      : "";
    const icon = opts?.icon ? hmIcon(opts.icon, 16) : "";
    return `<label class="hm-room-field" for="${escapeAttr(inputId)}">
      <span class="hm-room-field__label">${icon}<span class="hm-room-field__text">${escapeAttr(label)}</span>${tip}</span>
      ${fieldControl(room, k, kind, inputId)}
    </label>`;
  }

  function renderRooms() {
    const templates = Object.keys(rules.room_templates || {});
    if (state.rooms_expanded == null || state.rooms_expanded >= state.rooms.length) {
      state.rooms_expanded = Math.max(0, state.rooms.length - 1);
    }
    /** @type {{ room: object, index: number, timer: ReturnType<typeof setTimeout> } | null} */
    let undoDelete = null;

    main.innerHTML = `
      <h2>Rooms</h2>
      <p class="hm-muted">Pre-filled from the property on step 1 — each room keeps the type from that template. Rooms without a name are drafts and are ignored. When you rename a room by hand, type is not inferred from the name; pick Type yourself.</p>
      <div id="room-undo" class="hm-room-undo" hidden></div>
      <div id="room-list"></div>
      <button type="button" id="add-room">+ room</button>
      <button type="button" id="reset-rooms">Reset rooms from property</button>
      <div class="hm-actions">
        <button type="button" id="hm-back">Back</button>
        <button type="button" id="hm-next">Next</button>
      </div>
    `;
    const list = main.querySelector("#room-list");
    const undoBar = main.querySelector("#room-undo");

    function clearUndo() {
      if (undoDelete?.timer) clearTimeout(undoDelete.timer);
      undoDelete = null;
      undoBar.hidden = true;
      undoBar.innerHTML = "";
    }

    function showUndo(room, index) {
      if (undoDelete?.timer) clearTimeout(undoDelete.timer);
      undoDelete = {
        room,
        index,
        timer: setTimeout(() => {
          undoDelete = null;
          undoBar.hidden = true;
          undoBar.innerHTML = "";
        }, 5000),
      };
      const label = room.name?.trim() || "Untitled room";
      undoBar.hidden = false;
      undoBar.innerHTML = `
        <span>Deleted <strong>${escapeAttr(label)}</strong>.</span>
        <button type="button" id="hm-undo-delete">Undo</button>`;
      undoBar.querySelector("#hm-undo-delete").onclick = () => {
        if (!undoDelete) return;
        const { room: restored, index: at } = undoDelete;
        clearUndo();
        state.rooms_user_edited = true;
        const insertAt = Math.min(Math.max(0, at), state.rooms.length);
        state.rooms.splice(insertAt, 0, restored);
        state.rooms_expanded = insertAt;
        saveState();
        paintRooms();
        bump();
      };
    }

    function paintRooms() {
      if (state.rooms_expanded >= state.rooms.length) {
        state.rooms_expanded = Math.max(0, state.rooms.length - 1);
      }
      list.innerHTML = state.rooms
        .map((r, i) => {
          const template =
            r.template && rules.room_templates?.[r.template] ? r.template : "living";
          if (r.template !== template) r.template = template;
          const expanded = i === state.rooms_expanded;
          const summary = roomSummaryBits(r);
          const summaryText = summary || "no equipment set";
          const title = r.name?.trim() || "Untitled room";
          const roomPanelId = r.panel_id || firstPanelId();
          const roomPanelName = panelById(roomPanelId)?.name || "Main panel";
          if (!expanded) {
            return `
            <button type="button" class="hm-room-collapsed" data-expand="${i}">
              <span class="hm-room-type" aria-hidden="true">
                <span class="hm-room-type__ico">${hmIcon(roomTypeSvg(template), 18)}</span>
                <span class="hm-room-icon">${roomTypeIcon(template)}</span>
              </span>
              <span class="hm-room-collapsed__text">
                <strong>${escapeAttr(title)}</strong>
                <span class="hm-muted"> · ${escapeAttr(roomPanelName)}${summaryText ? ` · ${escapeAttr(summaryText)}` : ""}</span>
              </span>
              <span class="hm-room-chevron" aria-hidden="true">▾</span>
            </button>`;
          }
          const typeOpts = templates
            .map(
              (t) =>
                `<option value="${t}" ${t === template ? "selected" : ""}>${roomTypeLabel(t)}</option>`,
            )
            .join("");
          const lightFields = ROOM_FIELDS_LIGHT.map((f) => roomFieldHtml(r, f, i)).join("");
          const otherFields = ROOM_FIELDS_OTHER.map((f) => roomFieldHtml(r, f, i)).join("");
          const moreFields = ROOM_FIELDS_MORE.map((f) => roomFieldHtml(r, f, i)).join("");
          return `
          <article class="hm-room-card hm-room-card--open" data-i="${i}">
            <header class="hm-room-card__toolbar">
              <button type="button" class="hm-room-collapse" data-collapse="${i}" aria-label="Collapse room">▴</button>
              <span class="hm-room-type" aria-hidden="true">
                <span class="hm-room-type__ico">${hmIcon(roomTypeSvg(template), 18)}</span>
              </span>
              <h3 class="hm-room-card__title">${escapeAttr(title)}</h3>
              <button type="button" class="hm-room-delete" data-rm="${i}">
                <svg class="hm-room-delete__icon" width="14" height="14" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2">
                  <path d="M3 6h18M8 6V4h8v2M9 10v8M12 10v8M15 10v8M6 6l1 14h10l1-14"/>
                </svg>
                Delete room
              </button>
            </header>
            <div class="hm-room-card__identity hm-room-card__identity--3">
              <label class="hm-room-field" for="room-${i}-name">
                <span class="hm-room-field__label"><span class="hm-room-field__text">Name</span></span>
                <input id="room-${i}-name" data-k="name" value="${escapeAttr(r.name || "")}" placeholder="Room name">
              </label>
              <label class="hm-room-field" for="room-${i}-template">
                <span class="hm-room-field__label"><span class="hm-room-field__text">Type</span></span>
                <select id="room-${i}-template" data-k="template">${typeOpts}</select>
              </label>
              <label class="hm-room-field" for="room-${i}-panel_id">
                <span class="hm-room-field__label"><span class="hm-room-field__text">Panel</span></span>
                ${panelSelectHtml(roomPanelId, `id="room-${i}-panel_id" data-k="panel_id"`)}
              </label>
            </div>
            <div class="hm-room-group">
              <h4 class="hm-room-group__title">${hmIcon("light", 16)} Lighting</h4>
              <div class="hm-room-card__grid">${lightFields}</div>
            </div>
            <div class="hm-room-group">
              <h4 class="hm-room-group__title">${hmIcon("gear", 16)} Other</h4>
              <div class="hm-room-card__grid">${otherFields}</div>
            </div>
            <details class="hm-room-more"><summary>More</summary>
              <div class="hm-room-card__grid">${moreFields}</div>
            </details>
          </article>`;
        })
        .join("");

      list.querySelectorAll("[data-expand]").forEach((btn) => {
        btn.onclick = () => {
          state.rooms_expanded = Number(btn.dataset.expand);
          saveState();
          paintRooms();
        };
      });
      list.querySelectorAll("[data-collapse]").forEach((btn) => {
        btn.onclick = () => {
          state.rooms_expanded = -1;
          saveState();
          paintRooms();
        };
      });

      list.querySelectorAll(".hm-room-card").forEach((card) => {
        const i = Number(card.dataset.i);
        card.querySelectorAll("input[data-k], select[data-k]").forEach((inp) => {
          const apply = (opts = {}) => {
            state.rooms_user_edited = true;
            const key = inp.dataset.k;
            if (key === "template") {
              const name = state.rooms[i].name;
              const next = inp.value;
              const prevManual = state.rooms[i].manual || {};
              const prevPanel = state.rooms[i].panel_id;
              state.rooms[i] = {
                ...roomDefaults(next),
                name,
                template: next,
                panel_id: prevPanel || firstPanelId(),
                manual: prevManual,
              };
              saveState();
              paintRooms();
              bump();
              return;
            }
            if (key === "name") {
              state.rooms[i].name = inp.value;
              const titleEl = card.querySelector(".hm-room-card__title");
              if (titleEl) {
                titleEl.textContent = inp.value.trim() || "Untitled room";
              }
            } else if (key === "panel_id") {
              state.rooms[i].panel_id = inp.value;
            } else if (key === "temp_sensor") state.rooms[i].temp_sensor = inp.value;
            else if (key === "led_strip_channels")
              state.rooms[i].led_strip_channels = Number(inp.value) || 4;
            else {
              state.rooms[i][key] = Number(inp.value) || 0;
              markRoomFieldManual(state.rooms[i], key);
              if (key === "lights_onoff" || key === "lights_dimmable") {
                const lights = Number(state.rooms[i].lights_onoff) || 0;
                if ((Number(state.rooms[i].lights_dimmable) || 0) > lights) {
                  state.rooms[i].lights_dimmable = lights;
                }
              }
            }
            saveState();
            // After blur/change on a parent count, refresh dependent field visibility.
            if (
              opts.commit &&
              (key === "lights_onoff" || key === "led_strips")
            ) {
              paintRooms();
            }
            bump();
          };
          inp.onchange = () => apply({ commit: true });
          if (inp.tagName !== "SELECT") inp.oninput = () => apply({ commit: false });
        });
        card.querySelectorAll(".hm-stepper__btn").forEach((btn) => {
          btn.onclick = (ev) => {
            ev.preventDefault();
            const key = btn.dataset.k;
            const input = card.querySelector(`input[data-k="${key}"]`);
            if (!input) return;
            const delta = Number(btn.dataset.step) || 0;
            const next = Math.max(0, (Number(input.value) || 0) + delta);
            input.value = String(next);
            input.dispatchEvent(new Event("change", { bubbles: true }));
          };
        });
        const rm = card.querySelector("[data-rm]");
        if (rm) {
          rm.onclick = () => {
            state.rooms_user_edited = true;
            const [removed] = state.rooms.splice(i, 1);
            if (state.rooms_expanded === i) state.rooms_expanded = -1;
            else if (state.rooms_expanded > i) state.rooms_expanded -= 1;
            saveState();
            showUndo(removed, i);
            paintRooms();
            bump();
          };
        }
      });
    }

    paintRooms();
    main.querySelector("#add-room").onclick = () => {
      clearUndo();
      state.rooms_user_edited = true;
      state.rooms.push({
        ...roomDefaults("living"),
        template: "living",
        panel_id: firstPanelId(),
      });
      state.rooms_expanded = state.rooms.length - 1;
      saveState();
      paintRooms();
      bump();
    };
    main.querySelector("#reset-rooms").onclick = () => {
      clearUndo();
      reseedRooms(true);
      saveState();
      paintRooms();
      bump();
    };
    main.querySelector("#hm-back").onclick = () => {
      clearUndo();
      state.step = 0;
      saveState();
      render();
    };
    main.querySelector("#hm-next").onclick = () => {
      clearUndo();
      state.step = 2;
      saveState();
      render();
    };
  }

  function sysFieldControl(sectionId, key, kind, value, inputId) {
    const idAttr = inputId ? ` id="${escapeAttr(inputId)}"` : "";
    if (kind === "boiler") {
      return `<select data-sys="${sectionId}.${key}"${idAttr}>
        <option value="none" ${value === "none" ? "selected" : ""}>None</option>
        <option value="opentherm" ${value === "opentherm" ? "selected" : ""}>OpenTherm</option>
        <option value="relay" ${value === "relay" ? "selected" : ""}>Relay</option>
      </select>`;
    }
    if (kind === "powered_sensors") return ""; // custom block
    const n = Number(value) || 0;
    return `<span class="hm-stepper">
      <button type="button" class="hm-stepper__btn" data-step="-1" data-sys="${sectionId}.${key}" aria-label="Decrease">−</button>
      <input${idAttr} data-sys="${sectionId}.${key}" type="number" min="0" value="${n}" inputmode="numeric">
      <button type="button" class="hm-stepper__btn" data-step="1" data-sys="${sectionId}.${key}" aria-label="Increase">+</button>
    </span>`;
  }

  function sysFieldIcon(sectionId, key) {
    const map = {
      boiler: "boiler",
      collector_loops: "heat",
      heating_pumps: "heat",
      fan_coils: "vent",
      heat_pump: "heat",
      fireplace: "heat",
      pt100_sensors: "heat",
      ds18b20_sensors: "heat",
      ahu: "vent",
      recuperator: "vent",
      extract_fans: "vent",
      dampers_0_10v: "vent",
      sensors_0_10v: "vent",
      sensors_4_20ma: "vent",
      leak_zones: "leak",
      shutoff_valves: "water",
      water_meters: "water",
      irrigation: "water",
      water_pumps: "water",
      dhw_recirc: "water",
      gas_valve: "water",
      energy_phases: "energy",
      load_shed: "energy",
      ev_chargers: "energy",
      pv_inverters: "energy",
      fault_contacts: "energy",
      powered_sensors: "security",
      dry_contacts: "security",
      gates: "gate",
      locks: "security",
      panic_buttons: "security",
      stair_steps: "light",
      accent_zones: "light",
      garden_lights: "light",
    };
    return map[key] || "gear";
  }

  function shortSysLabel(label) {
    return label
      .replace(" (house total)", "")
      .replace(" / air handling", "")
      .replace(" (actuators)", "")
      .replace(" (pulse)", "")
      .replace(" / inverter status contacts", "")
      .replace(" / garage doors", "")
      .replace(" / alarm buttons", "")
      .replace(" / cove lighting zones", "")
      .replace(" / outdoor lighting", "");
  }

  function renderPoweredSensors(container) {
    const types = rules.alarm_sensor_types || {};
    const rows = state.systems.security.powered_sensors || [];
    container.innerHTML = `
      <div class="hm-sensor-list">
        ${rows
          .map(
            (row, i) => `
          <div class="hm-sensor-row" data-si="${i}">
            <select data-sk="type">${Object.entries(types)
              .map(
                ([k, v]) =>
                  `<option value="${k}" ${k === row.type ? "selected" : ""}>${v.label || k}</option>`,
              )
              .join("")}</select>
            <input data-sk="qty" type="number" min="0" value="${row.qty || 0}">
            <button type="button" data-srm="${i}">×</button>
          </div>`,
          )
          .join("")}
        <button type="button" id="add-sensor">+ powered sensor</button>
        <p class="hm-hint">ALM rail budget 150 mA per module — the estimate warns if sensor current exceeds it.</p>
      </div>`;
    container.querySelectorAll(".hm-sensor-row").forEach((row) => {
      const i = Number(row.dataset.si);
      row.querySelectorAll("[data-sk]").forEach((inp) => {
        inp.onchange = inp.oninput = () => {
          const k = inp.dataset.sk;
          if (k === "type") state.systems.security.powered_sensors[i].type = inp.value;
          else state.systems.security.powered_sensors[i].qty = Number(inp.value) || 0;
          saveState();
          bump();
        };
      });
      row.querySelector("[data-srm]").onclick = () => {
        state.systems.security.powered_sensors.splice(i, 1);
        saveState();
        renderPoweredSensors(container);
        bump();
      };
    });
    container.querySelector("#add-sensor").onclick = () => {
      const first = Object.keys(types)[0] || "pir";
      state.systems.security.powered_sensors.push({ type: first, qty: 1 });
      saveState();
      renderPoweredSensors(container);
      bump();
    };
  }

  function renderEngineering() {
    const sys = state.systems;
    const multiPanel = state.panels.length > 1;
    const showAll = !!state.systems_show_all;

    if (!Array.isArray(state.systems_expanded)) {
      const nonEmpty = SYSTEM_SECTIONS.filter((sec) => sectionHasContent(sec, sys)).map(
        (s) => s.id,
      );
      state.systems_expanded = nonEmpty.length ? nonEmpty.slice(0, 1) : [SYSTEM_SECTIONS[0].id];
    }

    const globalPanel = sys[SYSTEM_SECTIONS[0].id]?.panel_id || firstPanelId();

    const panelBar = multiPanel
      ? `<div class="hm-sys-panel-bar">
          <label class="hm-room-field" for="sys-global-panel">
            <span class="hm-room-field__label">${hmIcon("estimate", 16)}<span class="hm-room-field__text">Panel for systems</span></span>
            ${panelSelectHtml(globalPanel, 'id="sys-global-panel" data-sys-global-panel')}
          </label>
          <p class="hm-muted">Whole-home equipment is assigned to this panel. Rooms keep their own panel choice on the Rooms step.</p>
        </div>`
      : "";

    const sectionsHtml = SYSTEM_SECTIONS.map((sec) => {
      const open = state.systems_expanded.includes(sec.id);
      const summary = sectionSummaryText(sec, sys);
      const used = sectionHasContent(sec, sys);
      if (!open) {
        return `<button type="button" class="hm-sys-collapsed" data-sys-expand="${sec.id}">
          <span class="hm-sys-collapsed__ico">${hmIcon(sec.icon || "gear", 18)}</span>
          <span class="hm-sys-collapsed__text">
            <strong>${escapeAttr(sec.title)}</strong>
            <span class="hm-muted">${escapeAttr(summary)}</span>
          </span>
          <span class="hm-room-chevron" aria-hidden="true">▾</span>
        </button>`;
      }
      const fields = sec.fields
        .map(([key, label, kind]) => {
          const revealEmpty = showAll || !used;
          if (kind === "powered_sensors") {
            const rows = sys.security.powered_sensors || [];
            const n = rows.reduce((s, r) => s + (Number(r.qty) || 0), 0);
            if (!revealEmpty && n === 0) return "";
            return `<div class="hm-sys-field">
              <span class="hm-room-field__label">${hmIcon("security", 16)}<span class="hm-room-field__text">${escapeAttr(shortSysLabel(label))}</span></span>
              <div data-powered-host></div>
            </div>`;
          }
          const val = sys[sec.id]?.[key];
          if (kind === "boiler") {
            if (!revealEmpty && (!val || val === "none")) return "";
          } else if (!revealEmpty && !(Number(val) > 0)) {
            return "";
          }
          const tip =
            sec.id === "heating" && key === "collector_loops"
              ? `<button type="button" class="hm-field-tip" title="Compared with the sum of per-room underfloor loops; the engine uses the maximum, not the sum." aria-label="Help">?</button>`
              : "";
          const inputId = `sys-${sec.id}-${key}`;
          return `<label class="hm-room-field" for="${escapeAttr(inputId)}">
            <span class="hm-room-field__label">${hmIcon(sysFieldIcon(sec.id, key), 16)}<span class="hm-room-field__text">${escapeAttr(shortSysLabel(label))}</span>${tip}</span>
            ${sysFieldControl(sec.id, key, kind, val, inputId)}
          </label>`;
        })
        .join("");
      const emptyNote =
        !fields && !showAll
          ? `<p class="hm-muted">No values set — turn on “Show all fields” to edit.</p>`
          : "";
      return `<article class="hm-sys-section hm-sys-section--open" data-sys-sec="${sec.id}">
        <header class="hm-sys-section__head">
          <button type="button" class="hm-room-collapse" data-sys-collapse="${sec.id}" aria-label="Collapse">▴</button>
          <span class="hm-sys-collapsed__ico">${hmIcon(sec.icon || "gear", 18)}</span>
          <h3 class="hm-sys-section__title">${escapeAttr(sec.title)}</h3>
          <span class="hm-muted">${used ? escapeAttr(summary) : "not used"}</span>
        </header>
        <div class="hm-sys-grid">${fields}${emptyNote}</div>
      </article>`;
    }).join("");

    main.innerHTML = `
      <h2>Systems</h2>
      <p class="hm-muted">Describe equipment — the engine converts it to channel demand. Expand one section at a time.</p>
      ${panelBar}
      <label class="hm-check hm-sys-showall"><input type="checkbox" id="sys-show-all" ${showAll ? "checked" : ""}> Show all fields</label>
      ${sectionsHtml}
      <div class="hm-actions">
        <button type="button" id="hm-back">Back</button>
        <button type="button" id="hm-next">To result</button>
      </div>
    `;

    const poweredHost = main.querySelector("[data-powered-host]");
    if (poweredHost) renderPoweredSensors(poweredHost);

    main.querySelector("#sys-show-all").onchange = (e) => {
      state.systems_show_all = e.target.checked;
      saveState();
      renderEngineering();
      bump();
    };

    const globalSel = main.querySelector("[data-sys-global-panel]");
    if (globalSel) {
      globalSel.onchange = () => {
        for (const sec of SYSTEM_SECTIONS) {
          state.systems[sec.id].panel_id = globalSel.value;
        }
        saveState();
        bump();
      };
    }

    main.querySelectorAll("[data-sys-expand]").forEach((btn) => {
      btn.onclick = () => {
        const id = btn.dataset.sysExpand;
        state.systems_expanded = [id];
        saveState();
        renderEngineering();
      };
    });
    main.querySelectorAll("[data-sys-collapse]").forEach((btn) => {
      btn.onclick = () => {
        state.systems_expanded = [];
        saveState();
        renderEngineering();
      };
    });

    main.querySelectorAll("input[data-sys], select[data-sys]").forEach((inp) => {
      const apply = () => {
        const [sec, key] = inp.dataset.sys.split(".");
        if (key === "boiler") {
          state.systems.heating.boiler = inp.value;
        } else {
          state.systems[sec][key] = Number(inp.value) || 0;
        }
        saveState();
        bump();
      };
      inp.onchange = apply;
      inp.oninput = apply;
    });

    main.querySelectorAll(".hm-stepper__btn[data-sys]").forEach((btn) => {
      btn.onclick = (ev) => {
        ev.preventDefault();
        const key = btn.dataset.sys;
        const input = main.querySelector(`input[data-sys="${key}"]`);
        if (!input) return;
        const delta = Number(btn.dataset.step) || 0;
        input.value = String(Math.max(0, (Number(input.value) || 0) + delta));
        input.dispatchEvent(new Event("change", { bubbles: true }));
      };
    });

    main.querySelector("#hm-back").onclick = () => {
      state.step = 1;
      saveState();
      render();
    };
    main.querySelector("#hm-next").onclick = () => {
      state.step = 3;
      saveState();
      render();
    };
  }

  function renderExpert() {
    main.innerHTML = `
      <h2>Expert demand (JSON)</h2>
      <textarea id="expert-json" rows="16">${JSON.stringify(state.expertDemand, null, 2)}</textarea>
      <div class="hm-actions">
        <button type="button" id="hm-apply">Apply</button>
        <button type="button" id="hm-next">To result</button>
      </div>
    `;
    main.querySelector("#hm-apply").onclick = () => {
      try {
        state.expertDemand = JSON.parse(main.querySelector("#expert-json").value || "{}");
        saveState();
        bump();
      } catch (e) {
        alert("JSON: " + e.message);
      }
    };
    main.querySelector("#hm-next").onclick = () => {
      state.step = 3;
      saveState();
      render();
    };
  }

  function panelResultBlock(panel, opts = {}) {
    const { manifest = null, priceMap: prices = priceMap } = opts;
    const ctrl = (panel.modules || []).filter((m) => rules.modules?.[m.id]?.master);
    const slaves = (panel.modules || []).filter((m) => !rules.modules?.[m.id]?.master);
    const modules = [...ctrl, ...slaves];
    let modSubtotal = 0;
    let modCurrency = "";
    let missingPrice = 0;
    const modRows = modules
      .map((m) => {
        const p = prices[m.sku];
        if (p && typeof p.amount === "number") {
          modSubtotal += p.amount * (m.qty || 0);
          modCurrency = p.currency || modCurrency;
        } else {
          missingPrice += 1;
        }
        const din = m.din_units != null ? `${m.din_units} M` : "—";
        return `<tr data-hl="module:${escapeAttr(m.id)}">
          <td><div class="hm-bom__item">${icoBox(moduleRowIcon(m.id))}<span><strong>${m.qty}×</strong> <a href="${m.shop_url || "#"}">${escapeAttr(m.id)}</a><br><span class="hm-muted">${escapeAttr(m.sku || "")}</span></span></div></td>
          <td class="hm-bom__num">${din}</td>
          <td class="hm-bom__price">${formatPriceCell(p)}</td>
        </tr>`;
      })
      .join("");
    const accessories = panel.accessories || [];
    const primaryAcc = accessories.filter((a) => !CONSUMABLE_COMPANION_IDS.has(a.id));
    const consumableAcc = accessories.filter((a) => CONSUMABLE_COMPANION_IDS.has(a.id));
    const accAll = [...primaryAcc, ...consumableAcc];
    const accCount = accAll.reduce((s, a) => s + (Number(a.qty) || 0), 0);
    const accDin = accAll.reduce(
      (s, a) => s + (Number(a.din_units) || 0) * (Number(a.qty) || 0),
      0,
    );
    const accRow = (a) => {
      const din =
        a.din_units != null
          ? `${Math.round((Number(a.din_units) || 0) * (Number(a.qty) || 0) * 100) / 100} M`
          : "—";
      return `<tr data-hl="companion:${escapeAttr(a.id)}">
        <td><div class="hm-bom__item">${hmIcon(companionRowIcon(a.id), 18)}<span><strong>${a.qty}×</strong> ${escapeAttr(a.label || a.id)}<br><span class="hm-muted">${escapeAttr(companionNote(a.id, a.label))}</span></span></div></td>
        <td class="hm-bom__num">${din}</td>
      </tr>`;
    };
    const primaryRows = primaryAcc.map(accRow).join("");
    const consumableRows = consumableAcc.map(accRow).join("");
    const consumableN = consumableAcc.reduce((s, a) => s + (Number(a.qty) || 0), 0);

    const segs = panel.topology?.segments?.length ?? 0;
    const terms = (panel.topology?.segments || []).reduce(
      (s, seg) => s + (seg.terminators || 0),
      0,
    );
    const ctrlCount = ctrl.reduce((s, m) => s + (m.qty || 0), 0);
    const psuW = panel.power?.total_w ?? "—";
    const occ = panel.occupied ?? panel.din_occupied ?? panel.enclosure?.occupied ?? panel.enclosure?.din_occupied;
    const free = panel.free ?? panel.din_free ?? panel.enclosure?.free ?? panel.enclosure?.din_free;
    const cap = panel.capacity ?? panel.enclosure?.capacity ?? "—";
    const enc = panel.enclosure;
    const encChip =
      enc?.cabinets > 1
        ? `${enc.cabinets}× (${enc.rows}×${enc.row_width})`
        : enc
          ? `${enc.rows || "—"}×${enc.row_width || "—"}`
          : "—";
    const loc = panel.location ? ` · ${escapeAttr(panel.location)}` : "";
    const yaml = (panel.topology?.esphome_yaml || "").replace(/</g, "&lt;");

    let layoutHtml = "";
    if (manifest) {
      const layout = buildPanelLayout(panel, rules);
      if (layout) {
        layoutHtml = `<div class="hm-rail-block hm-card">${renderPanelLayoutHtml(layout, manifest, { priceMap: prices })}</div>`;
      }
    }

    const subLine =
      typeof modSubtotal === "number" && modSubtotal > 0
        ? `${Math.round(modSubtotal * 100) / 100} ${escapeAttr(modCurrency)}`
        : "—";
    const under =
      missingPrice > 0
        ? `<tr><td colspan="3"><span class="hm-warn">Subtotal understated — ${missingPrice} line(s) without a price</span></td></tr>`
        : "";

    const powerRows = (panel.power?.requirements || []).filter((r) =>
      ["module_logic_psu", "str_led_ps", "rgb_led_ps"].includes(r.kind),
    );
    const powerHtml = powerRows.length
      ? `<div class="hm-card">
          <h4>Power supplies</h4>
          <ul class="hm-power-list">
            ${powerRows.map((r) => `<li>${escapeAttr(r.text)}</li>`).join("")}
          </ul>
        </div>`
      : "";

    return `
      <section class="hm-panel-result">
        <div class="hm-card">
          <h3>${escapeAttr(panel.name)}${loc}</h3>
          <div class="hm-chip-row">
            <span class="hm-chip">${hmIcon("ruler", 18)} DIN ${occ != null ? `${occ} M occupied` : "—"} · ${free != null ? `${free} M free` : ""} · ${cap} M</span>
            <span class="hm-chip">${hmIcon("busbar", 18)} RS-485 · ${segs} seg · ${ctrlCount} ctrl · ${terms} term</span>
            <span class="hm-chip">${hmIcon("psu", 18)} Logic 24 V · ≥${typeof psuW === "number" ? Math.ceil(psuW) : psuW} W</span>
            <span class="hm-chip">${hmIcon("enclosure", 18)} Enclosure · ${escapeAttr(encChip)}</span>
          </div>
        </div>
        ${powerHtml}
        <div class="hm-card">
          <h4>HomeMaster modules</h4>
          <table class="hm-bom">
            <thead><tr><th>Item</th><th class="hm-bom__num">Width</th><th class="hm-bom__price">Price</th></tr></thead>
            <tbody>${modRows || `<tr><td colspan="3" class="hm-muted">—</td></tr>`}
              <tr class="hm-bom__sub"><td>Subtotal</td><td></td><td class="hm-bom__price">${subLine}</td></tr>
              ${under}
            </tbody>
          </table>
        </div>
        <div class="hm-card hm-card--paper">
          <div class="hm-acc-head">
            <h4>Companions &amp; materials</h4>
            <span class="hm-muted">${accCount} items · ${Math.round(accDin * 100) / 100} M of DIN width</span>
          </div>
          <table class="hm-bom hm-bom--acc">
            <thead><tr><th>Item</th><th class="hm-bom__num">Width</th></tr></thead>
            <tbody>
              ${primaryRows}
              ${consumableRows
                .replace(/<tr /g, '<tr class="hm-acc-consumable" hidden ')
                .replace(/<tr>/g, '<tr class="hm-acc-consumable" hidden>')}
              ${
                consumableAcc.length
                  ? `<tr><td colspan="2"><button type="button" class="hm-linkish" data-acc-more data-n="${consumableN || consumableAcc.length}">Show all ${consumableN || consumableAcc.length} items</button></td></tr>`
                  : ""
              }
            </tbody>
          </table>
        </div>
        ${layoutHtml}
        <details class="hm-fold">
          <summary>${hmIcon("code", 18)} ESPHome YAML <span class="hm-fold__chev">${hmIcon("chevron", 16)}</span></summary>
          <div class="hm-fold__body"><pre>${yaml || "—"}</pre></div>
        </details>
      </section>`;
  }

  async function renderResult() {
    let result = liveResult();
    main.innerHTML = `<p>Loading prices from the shop…</p>`;
    await refreshPrices(result);
    result = liveResult();
    await refreshPrices(result);
    result = liveResult();
    renderSummary(result);

    let manifest = null;
    try {
      manifest = await loadPanelManifest();
    } catch (err) {
      console.warn("panel layout manifest:", err);
    }

    const tot = cartTotal(result, priceMap);
    const notes = collectResultNotes(result, priceMap);
    const modQty = (result.panels || []).reduce(
      (s, p) => s + (p.modules || []).reduce((a, m) => a + (m.qty || 0), 0),
      0,
    );
    const panelN = result.panels?.length || state.panels.length || 1;
    const dinW =
      result.enclosure?.capacity ??
      result.panels?.reduce((s, p) => s + (p.enclosure?.capacity || 0), 0) ??
      "—";
    const sections = result.panels?.reduce(
      (s, p) => s + (p.enclosure?.cabinets || 1),
      0,
    ) ?? 1;

    let priceHtml = `<p class="hm-result-hero__price">—</p>`;
    if (tot && tot.pricedQty > 0) {
      priceHtml = `<p class="hm-result-hero__price">${tot.total} <span>${escapeAttr(tot.currency)}</span></p>`;
    }

    const notesBar = resultNotesBarHtml(notes);

    const shareOlder = state.shareLinkOlder
      ? `<p class="hm-warn hm-share-older">This link was created with an older version — some settings may have changed</p>`
      : "";

    const panelBlocks = (result.panels || [])
      .map((p) => panelResultBlock(p, { manifest, priceMap }))
      .join("");

    const hero = resultHeroHtml({
      priceHtml,
      stats: [
        { icon: "cube", value: modQty, label: "Modules" },
        { icon: "panel", value: panelN, label: "Panel" },
        { icon: "ruler", value: dinW, label: "DIN width" },
        { icon: "layers", value: sections, label: "Sections" },
      ],
      actionsHtml: `
            <button type="button" class="hm-btn-pill hm-btn-pill--primary" id="hm-cart">${hmIcon("cart", 16)} Add to cart</button>
            <button type="button" class="hm-btn-pill hm-btn-pill--ghost" id="hm-xlsx">${hmIcon("download", 16)} Download</button>
            <button type="button" class="hm-btn-pill hm-btn-pill--ghost" id="hm-share">${hmIcon("link", 16)} Copy link</button>
            <button type="button" class="hm-btn-pill hm-btn-pill--ghost" id="hm-back">Back</button>`,
    });

    main.innerHTML = `
      <div class="hm-result">
        ${hero}
        ${shareOlder}
        ${notesBar}
        ${panelBlocks || `<div class="hm-card"><p>No panels.</p></div>`}
        ${channelUsageTable(result.channel_usage)}
        ${notIncludedBlock(result.not_included)}
        <div id="hm-cart-status"></div>
      </div>
    `;

    bindLayoutHighlight(main);
    bindNotesToggle(main);
    main.querySelectorAll("[data-acc-more]").forEach((btn) => {
      btn.onclick = () => {
        const table = btn.closest("table");
        const rows = table?.querySelectorAll("tr.hm-acc-consumable") || [];
        const show = [...rows].some((r) => r.hidden);
        rows.forEach((r) => {
          r.hidden = !show;
        });
        const n = btn.dataset.n || "";
        btn.textContent = show ? `Hide extras` : `Show all ${n} items`;
      };
    });
    main.querySelector("#hm-xlsx").onclick = () =>
      downloadXlsx(result).catch(() => downloadCsv(result));
    main.querySelector("#hm-share").onclick = (ev) => copyShareLink(ev.currentTarget);
    main.querySelector("#hm-back").onclick = () => {
      state.step = state.expert ? 0 : 2;
      saveState();
      render();
    };
    main.querySelector("#hm-cart").onclick = async () => {
      const status = main.querySelector("#hm-cart-status");
      status.textContent = "Adding…";
      const lines = cartEligibleLines(result, priceMap);
      const { added, failed } = await addAllToCart(lines);
      if (failed) {
        status.innerHTML = `
          <p class="hm-warn">Added ${added.length} item(s); failed on ${failed.line?.sku}: ${failed.error}</p>
          <p><a href="/shop/cart">Open cart</a> · you can still download the estimate</p>`;
        return;
      }
      status.innerHTML = `<p>Done: ${added.length} item(s). <a href="/shop/cart">Go to cart</a></p>`;
    };
  }

  function bump() {
    if (state.ui_mode === "simple") return;
    renderSummary(liveResult());
  }

  function sliderRow(id, label, value, min, max, icon) {
    const lo = Number(min) || 0;
    const hi = Number(max) || 1;
    const v = Number(value) || 0;
    const pct = hi > lo ? Math.max(0, Math.min(100, ((v - lo) / (hi - lo)) * 100)) : 0;
    return `<div class="hm-slider" data-slider="${escapeAttr(id)}">
      <div class="hm-slider__label">
        <span class="hm-slider__name">${icon ? hmIcon(icon, 16) : ""}<span>${escapeAttr(label)}</span></span>
        <strong class="hm-slider__val-desk" id="${id}-val">${value}</strong>
      </div>
      <input type="range" class="hm-slider__range" id="${id}" min="${min}" max="${max}" value="${value}" style="--hm-slider-pct:${pct}%">
      <div class="hm-stepper" aria-label="${escapeAttr(label)}">
        <button type="button" class="hm-stepper__btn" data-for="${escapeAttr(id)}" data-step="-1" aria-label="Decrease">−</button>
        <strong class="hm-stepper__val" id="${id}-val-step">${value}</strong>
        <button type="button" class="hm-stepper__btn" data-for="${escapeAttr(id)}" data-step="1" aria-label="Increase">+</button>
      </div>
    </div>`;
  }

  function sectionTitle(icon, title) {
    return `<h3 class="hm-simple-sec__title">${hmIcon(icon, 18)}<span>${escapeAttr(title)}</span></h3>`;
  }

  function renderSimple() {
    summary.innerHTML = "";
    const c = state.simple.counts;
    const t = state.simple.totals;
    const g = state.simple.toggles;
    const warn = (state.simple.warnings || [])
      .map((w) => `<p class="hm-warn">${escapeAttr(w)}</p>`)
      .join("");

    const roomIcons = {
      bedroom: "bed",
      bath: "bath",
      living: "living",
      kitchen: "kitchen",
      hallway: "hall",
      office: "office",
      garage: "garage",
      boiler_room: "utility",
    };
    const roomSliders = SIMPLE_ROOM_TYPES.map(({ id, label }) =>
      sliderRow(`sc-${id}`, label, c[id] ?? 0, 0, 10, roomIcons[id]),
    ).join("");

    const equipFields = [
      ["lights_onoff", "Light groups", 40, "light"],
      ["lights_dimmable", "of which dimmable", 40, "dim"],
      ["led_strips", "RGB strips", 20, "rgb"],
      ["switches", "Wall switches", 60, "switch"],
      ["shutters", "Blinds / shutters", 30, "shutter"],
      ["ufh_loops", "Underfloor heating loops", 40, "heat"],
      ["leak_sensors", "Leak sensors", 20, "leak"],
      ["motion_sensors", "Motion detectors", 30, "motion"],
      ["door_contacts", "Door contacts", 40, "door"],
      ["smart_sockets", "Sockets", 30, "socket"],
    ];
    const lightsOn = (Number(t.lights_onoff) || 0) > 0;
    const equipVisible = (id) => {
      if (id === "lights_dimmable") return lightsOn;
      return (Number(t[id]) || 0) > 0;
    };
    const activeEquip = equipFields.filter(([id]) => equipVisible(id));
    const hiddenEquip = equipFields.filter(([id]) => !equipVisible(id));
    const equipActiveHtml = activeEquip
      .map(([id, label, max, icon]) => sliderRow(`st-${id}`, label, t[id] ?? 0, 0, max, icon))
      .join("");
    const equipHiddenHtml = hiddenEquip
      .map(([id, label, max, icon]) => sliderRow(`st-${id}`, label, t[id] ?? 0, 0, max, icon))
      .join("");
    const equipAdd =
      hiddenEquip.length > 0
        ? `<details class="hm-add-equip"><summary>Add equipment</summary><div class="hm-slider-stack">${equipHiddenHtml}</div></details>`
        : "";

    // Settings before result in DOM (mobile order = keyboard order); CSS puts result right on desktop.
    main.innerHTML = `
      <div class="hm-simple">
        <div class="hm-simple__settings">
          <div class="hm-simple-sec hm-simple-sec--top">
            <label class="hm-simple__ptype">Property type
              <select id="s-ptype">${PROPERTY_TYPES.map(
                ([v, lab]) =>
                  `<option value="${v}" ${v === state.object.property_type ? "selected" : ""}>${lab}</option>`,
              ).join("")}</select>
            </label>
          </div>

          <section class="hm-simple-sec">
            ${sectionTitle("rooms", "Rooms")}
            <div class="hm-slider-grid">${roomSliders}</div>
          </section>

          <section class="hm-simple-sec">
            ${sectionTitle("gear", "Equipment")}
            <div class="hm-slider-stack">${equipActiveHtml}</div>
            ${equipAdd}
          </section>

          <section class="hm-simple-sec">
            ${sectionTitle("estimate", "Whole-home systems")}
            <div class="hm-simple-toggles">
              <label class="hm-simple-toggle">
                <span class="hm-simple-toggle__lab">${hmIcon("boiler", 16)} Boiler</span>
                <select id="s-boiler">
                  <option value="none" ${g.boiler === "none" ? "selected" : ""}>None</option>
                  <option value="opentherm" ${g.boiler === "opentherm" ? "selected" : ""}>OpenTherm</option>
                  <option value="relay" ${g.boiler === "relay" ? "selected" : ""}>Relay</option>
                </select>
              </label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-vent" ${g.ventilation ? "checked" : ""}>${hmIcon("vent", 16)} Ventilation</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-energy" ${g.energy_metering ? "checked" : ""}>${hmIcon("energy", 16)} Energy metering</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-sec" ${g.security ? "checked" : ""}>${hmIcon("security", 16)} Security</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-water" ${g.garden_watering ? "checked" : ""}>${hmIcon("water", 16)} Garden watering</label>
              <label class="hm-check hm-simple-chip"><input type="checkbox" id="s-gates" ${g.gates ? "checked" : ""}>${hmIcon("gate", 16)} Gates</label>
            </div>
          </section>
          ${warn}
        </div>
        <div class="hm-simple__result" id="hm-simple-result">
          <p class="hm-muted">Calculating…</p>
        </div>
      </div>`;

    const setValDisplays = (id, n) => {
      const a = main.querySelector(`#${id}-val`);
      const b = main.querySelector(`#${id}-val-step`);
      if (a) a.textContent = String(n);
      if (b) b.textContent = String(n);
    };

    const bindControl = (id, apply) => {
      const input = main.querySelector(`#${id}`);
      if (!input) return;
      const sync = (raw) => {
        let n = Number(raw) || 0;
        const lo = Number(input.min) || 0;
        const hi = Number(input.max) || 1;
        n = Math.max(lo, Math.min(hi, n));
        input.value = String(n);
        setValDisplays(id, n);
        const pct = hi > lo ? Math.max(0, Math.min(100, ((n - lo) / (hi - lo)) * 100)) : 0;
        input.style.setProperty("--hm-slider-pct", `${pct}%`);
        apply(n);
        runSimpleSync();
        saveState();
        paintSimpleResult();
      };
      input.oninput = () => sync(input.value);
      main.querySelectorAll(`[data-for="${id}"]`).forEach((btn) => {
        btn.onclick = () => {
          const step = Number(btn.dataset.step) || 0;
          sync((Number(input.value) || 0) + step);
        };
      });
    };

    for (const { id } of SIMPLE_ROOM_TYPES) {
      bindControl(`sc-${id}`, (n) => {
        state.simple.counts[id] = n;
      });
    }
    for (const field of SIMPLE_DISTRIBUTE_FIELDS) {
      bindControl(`st-${field}`, (n) => {
        state.simple.totals[field] = n;
        if (field === "lights_dimmable") {
          const lights = Number(state.simple.totals.lights_onoff) || 0;
          if (n > lights) {
            state.simple.totals.lights_dimmable = lights;
            const inp = main.querySelector("#st-lights_dimmable");
            if (inp) inp.value = String(lights);
            setValDisplays("st-lights_dimmable", lights);
          }
        }
        // Promote newly non-zero equipment out of "Add equipment" on next paint of settings.
        if (field !== "lights_dimmable" && n > 0) {
          const details = main.querySelector(".hm-add-equip");
          const row = main.querySelector(`[data-slider="st-${field}"]`);
          if (details && row && details.contains(row)) {
            const stack = main.querySelector(".hm-simple-sec .hm-slider-stack");
            if (stack) stack.appendChild(row);
            if (!details.querySelector("[data-slider]")) details.remove();
          }
        }
      });
    }

    main.querySelector("#s-ptype").onchange = (e) => {
      state.object.property_type = e.target.value;
      saveState();
    };
    main.querySelector("#s-boiler").onchange = (e) => {
      state.simple.toggles.boiler = e.target.value;
      runSimpleSync();
      saveState();
      paintSimpleResult();
    };
    for (const [id, key] of [
      ["s-vent", "ventilation"],
      ["s-energy", "energy_metering"],
      ["s-sec", "security"],
      ["s-water", "garden_watering"],
      ["s-gates", "gates"],
    ]) {
      main.querySelector(`#${id}`).onchange = (e) => {
        state.simple.toggles[key] = e.target.checked;
        runSimpleSync();
        saveState();
        paintSimpleResult();
      };
    }

    paintSimpleResult();
  }

  async function paintSimpleResult() {
    const host = main.querySelector("#hm-simple-result");
    if (!host) return;
    let result = liveResult();
    await refreshPrices(result);
    result = liveResult();
    await refreshPrices(result);
    result = liveResult();
    const cartTot = cartTotal(result, priceMap);
    const sysTot = systemTotal(result, priceMap);
    const rows = modulePurchaseRows(result, priceMap);
    const modQty = rows.reduce((s, r) => s + (r.qty || 0), 0);
    const roomN =
      (state.rooms || []).filter((r) => r?.name?.trim()).length ||
      Object.values(state.simple?.counts || {}).reduce((s, n) => s + (Number(n) || 0), 0);
    const unavailableLines = rows.filter((r) => r.status === "oos").length;
    const lines = simpleCustomerSummary(
      state.simple.totals,
      state.simple.toggles,
      state.systems,
    );
    const coverList = lines
      .map(
        (l) =>
          `<li><span class="hm-simple-line__ico">${hmIcon(l.kind, 18)}</span><span>${escapeAttr(l.text)}</span></li>`,
      )
      .join("");
    let priceHtml = `<p class="hm-result-hero__price">—</p>`;
    if (sysTot && sysTot.pricedQty > 0) {
      priceHtml = `<p class="hm-result-hero__price">${sysTot.total} <span>${escapeAttr(sysTot.currency)}</span></p>`;
    }
    const stats = [
      { icon: "cube", value: modQty, label: "Modules" },
      { icon: "rooms", value: roomN, label: "Rooms" },
    ];
    if (unavailableLines > 0) {
      stats.push({
        icon: "warning",
        value: unavailableLines,
        label: "Unavailable",
        tone: "warn",
      });
    }
    const notes = collectResultNotes(result, priceMap, { omitShopUnavailable: true });
    const notesBar = resultNotesBarHtml(notes);
    const shareOlder = state.shareLinkOlder
      ? `<p class="hm-warn hm-share-older">This link was created with an older version — some settings may have changed</p>`
      : "";
    const warn = (state.simple.warnings || [])
      .map((w) => `<p class="hm-warn">${escapeAttr(w)}</p>`)
      .join("");

    const head = resultHeroHtml({ priceHtml, stats });

    host.innerHTML = `
      ${head}
      ${shareOlder}
      ${notesBar}
      <div class="hm-card hm-simple-buy">
        <h3 class="hm-simple-buy__h">What it covers</h3>
        <ul class="hm-simple-lines">${coverList || "<li class='hm-muted'>Adjust the controls to build your system.</li>"}</ul>
        <h3 class="hm-simple-buy__h">Modules you buy</h3>
        ${modulesYouBuyHtml(rows)}
      </div>
      <div class="hm-card hm-simple-actions">
        <div class="hm-simple-actions__primary">
          <button type="button" class="hm-btn-pill hm-btn-pill--primary" id="s-cart">${hmIcon("cart", 16)} Add to cart</button>
          <button type="button" class="hm-btn-pill hm-btn-pill--ghost" id="s-fullspec">${hmIcon("gear", 16)} Configure in detail</button>
          <button type="button" class="hm-btn-pill hm-btn-pill--ghost" id="s-xlsx">${hmIcon("download", 16)} Download</button>
          <button type="button" class="hm-btn-pill hm-btn-pill--ghost" id="s-share">${hmIcon("link", 16)} Copy link</button>
        </div>
        ${cartHintHtml(cartTot, sysTot)}
      </div>
      ${warn}
      <div id="s-cart-status"></div>`;

    bindNotesToggle(host);
    const moreBtn = host.querySelector("#s-mods-more");
    if (moreBtn) {
      moreBtn.onclick = () => {
        host.querySelectorAll(".hm-simple-buy__extra").forEach((li) => {
          li.hidden = false;
        });
        moreBtn.closest("li")?.remove();
      };
    }
    host.querySelector("#s-fullspec").onclick = () => setUiMode("advanced");
    host.querySelector("#s-xlsx").onclick = () =>
      downloadXlsx(result).catch(() => downloadCsv(result));
    host.querySelector("#s-share").onclick = (ev) => copyShareLink(ev.currentTarget);
    const addToCart = async () => {
      const status = host.querySelector("#s-cart-status");
      if (status) status.textContent = "Adding…";
      const { added, failed } = await addAllToCart(cartEligibleLines(result, priceMap));
      if (failed) {
        if (status) {
          status.innerHTML = `<p class="hm-warn">Added ${added.length}; failed on ${failed.line?.sku}</p>`;
        }
        return;
      }
      const units = added.reduce((s, a) => s + (a.line?.qty || 0), 0);
      if (status) {
        status.innerHTML = `<p>Done: ${units} unit${units === 1 ? "" : "s"}. <a href="/shop/cart">Go to cart</a></p>`;
      }
    };
    host.querySelector("#s-cart").onclick = addToCart;

    // Mobile sticky price bar — desktop hides via CSS.
    if (simpleDock) {
      const dockPrice =
        sysTot && sysTot.pricedQty > 0
          ? `${sysTot.total} ${escapeAttr(sysTot.currency)}`
          : "—";
      simpleDock.hidden = false;
      simpleDock.innerHTML = `
        <button type="button" class="hm-simple-dock__price" id="s-dock-price">${dockPrice}</button>
        <button type="button" class="hm-btn-pill hm-btn-pill--primary hm-simple-dock__cart" id="s-dock-cart">${hmIcon("cart", 16)} Add to cart</button>`;
      simpleDock.querySelector("#s-dock-price").onclick = () => {
        host.scrollIntoView({ behavior: "smooth", block: "start" });
      };
      simpleDock.querySelector("#s-dock-cart").onclick = addToCart;
    }
  }

  function render() {
    renderModeChrome();
    renderExamples();
    renderSteps();
    if (state.ui_mode === "simple") {
      if (!state.rooms?.length) runSimpleSync();
      renderSimple();
      return;
    }
    if (state.expert && state.step > 0 && state.step < 3) {
      renderExpert();
      bump();
      return;
    }
    if (state.step === 0) renderObject();
    else if (state.step === 1) renderRooms();
    else if (state.step === 2) renderEngineering();
    else renderResult();
    if (state.step !== 3) bump();
  }

  render();
}

function findRoot() {
  if (typeof document === "undefined") return null;
  return (
    document.getElementById("hm-configurator") ||
    document.getElementById("hm-system-builder") ||
    document.querySelector("[data-hm-estimator]")
  );
}

async function init() {
  ensureStylesheet();
  await loadRules();
  loadState();
  const fromShare = consumeShareQuery();
  if (!fromShare) {
    state.shareFromLink = false;
    state.shareLinkOlder = false;
    ensureRoomsSeeded();
  }
  const root = findRoot();
  if (root) mountConfigurator(root);
  else console.error("HM estimator: mount node not found (#hm-configurator / #hm-system-builder)");
}

function ensureStylesheet() {
  if (typeof document === "undefined") return;
  const href = "https://config.home-master.eu/estimator/app.css";
  if (
    [...document.querySelectorAll("link[rel='stylesheet']")].some((l) =>
      l.href.includes("/estimator/app.css"),
    )
  ) {
    return;
  }
  const link = document.createElement("link");
  link.rel = "stylesheet";
  link.href = href;
  document.head.appendChild(link);
}

function boot() {
  init().catch((err) => {
    const root = findRoot();
    if (root) {
      root.innerHTML = `<p class="hm-warn">Estimator failed: ${err?.message || err}</p>`;
    }
    console.error(err);
  });
}

if (typeof document !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot, { once: true });
  } else {
    boot();
  }
}

HM.loadRules = loadRules;
HM.seedRoomsFromProperty = seedRoomsFromProperty;
HM.runEstimate = runEstimate;
HM.mountConfigurator = mountConfigurator;
HM.init = init;


export { estimate, loadRules, runEstimate, mountConfigurator, init, fetchPrice, fetchPrices, addAllToCart, downloadXlsx, encodeShareLink, decodeShareLink };
